INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-01_1-1', '01-1', '馬太福音(一)1~14 章', 'MAT', '馬太福音', '新約', 'gospels', 1, 14, '經文辨識', '根據《馬太福音(一)1~14 章》的內容，以下哪一句經文出自這個範圍？', '到了一座城，名叫 拿撒勒，就住在那裏。這是要應驗先知所說，他將稱為 拿撒勒人的話了。', '在我父的家裏有許多住處；若是沒有，我就早已告訴你們了。我去原是為你們預備地方去。', '耶穌見所請的客揀擇首位，就用比喻對他們說：', '他們說：「要下毒手除滅那些惡人，將葡萄園另租給那按着時候交果子的園戶。」', 0, '正確內容記載於 馬太福音 2:23。', '馬太福音 2:23', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-01_1-2', '01-1', '馬太福音(一)1~14 章', 'MAT', '馬太福音', '新約', 'gospels', 1, 14, '出處辨識', '「你們禱告的時候，不可像那假冒為善的人，愛站在會堂裏和十字路口上禱告，故意叫人看見。我實在告訴你們，他…」的經文出處是哪裡？', '馬太福音 11:3', '馬太福音 6:5', '馬太福音 11:22', '馬太福音 2:14', 1, '正確內容記載於 馬太福音 6:5。', '馬太福音 6:5', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-01_1-3', '01-1', '馬太福音(一)1~14 章', 'MAT', '馬太福音', '新約', 'gospels', 1, 14, '經文辨識', '根據《馬太福音(一)1~14 章》的內容，以下哪一句經文出自這個範圍？', '就慶賀他說：「恭喜， 猶太人的王啊！」', '我實實在在地告訴你們，人若遵守我的道，就永遠不見死。」', '但要叫你們知道，人子在地上有赦罪的權柄」；就對癱子說：「起來！拿你的褥子回家去吧。」', '這婦人是 希臘人，屬 敘利腓尼基族。她求耶穌趕出那鬼離開她的女兒。', 2, '正確內容記載於 馬太福音 9:6。', '馬太福音 9:6', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-01_1-4', '01-1', '馬太福音(一)1~14 章', 'MAT', '馬太福音', '新約', 'gospels', 1, 14, '出處辨識', '「凡勞苦擔重擔的人可以到我這裏來，我就使你們得安息。」的經文出處是哪裡？', '馬太福音 3:2', '馬太福音 10:30', '馬太福音 5:38', '馬太福音 11:28', 3, '正確內容記載於 馬太福音 11:28。', '馬太福音 11:28', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-01_1-5', '01-1', '馬太福音(一)1~14 章', 'MAT', '馬太福音', '新約', 'gospels', 1, 14, '經文辨識', '根據《馬太福音(一)1~14 章》的內容，以下哪一句經文出自這個範圍？', '遇見一顆重價的珠子，就去變賣他一切所有的，買了這顆珠子。', '鬼屢次把他扔在火裏、水裏，要滅他。你若能做甚麼，求你憐憫我們，幫助我們。」', '「你們法利賽人有禍了！因為你們將薄荷、芸香並各樣菜蔬獻上十分之一，那公義和愛上帝的事反倒不行了。這原是你們當行的；那也是不可不行的。', '說：「主啊，憐憫我的兒子！他害癲癇的病很苦，屢次跌在火裏，屢次跌在水裏。', 0, '正確內容記載於 馬太福音 13:46。', '馬太福音 13:46', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-01_2-1', '01-2', '馬太福音(二)15~28 章', 'MAT', '馬太福音', '新約', 'gospels', 15, 28, '經文辨識', '根據《馬太福音(二)15~28 章》的內容，以下哪一句經文出自這個範圍？', '耶穌洗完了他們的腳，就穿上衣服，又坐下，對他們說：「我向你們所做的，你們明白嗎？', '從此，耶穌才指示門徒，他必須上 耶路撒冷去，受長老、祭司長、文士許多的苦，並且被殺，第三日復活。', '婦人說：「我知道彌賽亞（就是那稱為基督的）要來；他來了，必將一切的事都告訴我們。」', '「這個人為甚麼這樣說呢？他說僭妄的話了。除了上帝以外，誰能赦罪呢？」', 1, '正確內容記載於 馬太福音 16:21。', '馬太福音 16:21', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-01_2-2', '01-2', '馬太福音(二)15~28 章', 'MAT', '馬太福音', '新約', 'gospels', 15, 28, '出處辨識', '「這樣，那在後的，將要在前；在前的，將要在後了。 」的經文出處是哪裡？', '馬太福音 20:16', '馬太福音 24:10', '馬太福音 17:15', '馬太福音 15:21', 0, '正確內容記載於 馬太福音 20:16。', '馬太福音 20:16', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-01_2-3', '01-2', '馬太福音(二)15~28 章', 'MAT', '馬太福音', '新約', 'gospels', 15, 28, '經文辨識', '根據《馬太福音(二)15~28 章》的內容，以下哪一句經文出自這個範圍？', '這樣，從 亞伯拉罕到 大衛共有十四代；從 大衛到遷至 巴比倫的時候也有十四代；從遷至 巴比倫的時候到基督又有十四代。', '拿順是 亞米拿達的兒子； 亞米拿達是 亞蘭的兒子； 亞蘭是 希斯崙的兒子； 希斯崙是 法勒斯的兒子； 法勒斯是 猶大的兒子；', '有許多人到他那裏聚集，他只得上船坐下，眾人都站在岸上。', '又喜愛人在街市上問他安，稱呼他拉比 。', 3, '正確內容記載於 馬太福音 23:7。', '馬太福音 23:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-01_2-4', '01-2', '馬太福音(二)15~28 章', 'MAT', '馬太福音', '新約', 'gospels', 15, 28, '出處辨識', '「我赤身露體，你們給我穿；我病了，你們看顧我；我在監裏，你們來看我。』」的經文出處是哪裡？', '馬太福音 25:36', '馬太福音 15:33', '馬太福音 21:3', '馬太福音 24:10', 0, '正確內容記載於 馬太福音 25:36。', '馬太福音 25:36', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-01_2-5', '01-2', '馬太福音(二)15~28 章', 'MAT', '馬太福音', '新約', 'gospels', 15, 28, '經文辨識', '根據《馬太福音(二)15~28 章》的內容，以下哪一句經文出自這個範圍？', '在 拉瑪聽見號咷大哭的聲音， 是 拉結哭她兒女， 不肯受安慰， 因為他們都不在了。', '他們給他脫了衣服，穿上一件朱紅色袍子，', '就把禮物留在壇前，先去同弟兄和好，然後來獻禮物。', '耶穌對他說：「律法上寫的是甚麼？你念的是怎樣呢？」', 1, '正確內容記載於 馬太福音 27:28。', '馬太福音 27:28', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-02-1', '02', '創世記(一)1~25 章', 'GEN', '創世記', '舊約', 'pentateuch', 1, 25, '經文辨識', '根據《創世記(一)1~25 章》的內容，以下哪一句經文出自這個範圍？', '你看，我們從前在口袋裏所見的銀子，尚且從 迦南地帶來還你，我們怎能從你主人家裏偷竊金銀呢？', '他們回答說：「你僕人－我們的父親平安；他還在。」於是他們低頭下拜。', '又對 亞當說： 你既聽從妻子的話， 吃了我所吩咐你不可吃的那樹上的果子， 地必為你的緣故受咒詛； 你必終身勞苦才能從地裏得吃的。', '日後，你的兒子問你說：『這是甚麼意思？』你就說：『耶和華用大能的手將我們從 埃及為奴之家領出來。', 2, '正確內容記載於 創世記 3:17。', '創世記 3:17', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-02-2', '02', '創世記(一)1~25 章', 'GEN', '創世記', '舊約', 'pentateuch', 1, 25, '出處辨識', '「流你們血、害你們命的，無論是獸是人，我必討他的罪，就是向各人的弟兄也是如此。」的經文出處是哪裡？', '創世記 9:5', '創世記 4:18', '創世記 11:1', '創世記 19:6', 0, '正確內容記載於 創世記 9:5。', '創世記 9:5', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-02-3', '02', '創世記(一)1~25 章', 'GEN', '創世記', '舊約', 'pentateuch', 1, 25, '經文辨識', '根據《創世記(一)1~25 章》的內容，以下哪一句經文出自這個範圍？', '「你曉諭 以色列人說：你們到了我賜給你們的地，收割莊稼的時候，要將初熟的莊稼一捆帶給祭司。', '求你記念你的僕人 亞伯拉罕、 以撒、 以色列。你曾指着自己起誓說：『我必使你們的後裔像天上的星那樣多，並且我所應許的這全地，必給你們的後裔，他們要永遠…', '摩西在 以色列人面前所陳明的律法－', '亞伯蘭聽見他姪兒被擄去，就率領他家裏生養的精練壯丁三百一十八人，直追到 但，', 3, '正確內容記載於 創世記 14:14。', '創世記 14:14', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-02-4', '02', '創世記(一)1~25 章', 'GEN', '創世記', '舊約', 'pentateuch', 1, 25, '出處辨識', '「向 所多瑪和 蛾摩拉與平原的全地觀看，不料，那地方煙氣上騰，如同燒窯一般。」的經文出處是哪裡？', '創世記 1:11', '創世記 6:2', '創世記 19:28', '創世記 8:1', 2, '正確內容記載於 創世記 19:28。', '創世記 19:28', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-02-5', '02', '創世記(一)1~25 章', 'GEN', '創世記', '舊約', 'pentateuch', 1, 25, '經文辨識', '根據《創世記(一)1~25 章》的內容，以下哪一句經文出自這個範圍？', '若被 野獸撕碎，看守的要帶來當作證據，所撕的不必賠還。', '把飯擺在他面前，叫他吃，他卻說：「我不吃，等我說明白我的事情再吃。」 拉班說：「請說。」', '現在，我兒，你要照着我所吩咐你的，聽從我的話。', '他們隨時審判百姓，有難斷的案件就呈到 摩西那裏，但各樣小事他們自己審判。', 1, '正確內容記載於 創世記 24:33。', '創世記 24:33', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-03-1', '03', '創世記(二)25~50 章', 'GEN', '創世記', '舊約', 'pentateuch', 25, 50, '經文辨識', '根據《創世記(二)25~50 章》的內容，以下哪一句經文出自這個範圍？', '以撒對 雅各說：「我兒，你近前來，我摸摸你，知道你真是我的兒子 以掃不是。」', '頭的周圍不可剃，鬍鬚的周圍也不可損壞。', '耶和華上帝使各樣的樹從地裏長出來，可以悅人的眼目， 其上的果子好作食物。園子當中又有生命樹和分別善惡的樹。', '亞比米勒召了 亞伯拉罕來，對他說：「你怎麼向我這樣行呢？我在甚麼事上得罪了你，你竟使我和我國裏的人陷在大罪裏？你向我行不當行的事了！」', 0, '正確內容記載於 創世記 27:21。', '創世記 27:21', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-03-2', '03', '創世記(二)25~50 章', 'GEN', '創世記', '舊約', 'pentateuch', 25, 50, '出處辨識', '「又叫 米斯巴，意思說：「我們彼此離別以後，願耶和華在你我中間鑒察。」的經文出處是哪裡？', '創世記 49:6', '創世記 38:20', '創世記 27:32', '創世記 31:49', 3, '正確內容記載於 創世記 31:49。', '創世記 31:49', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-03-3', '03', '創世記(二)25~50 章', 'GEN', '創世記', '舊約', 'pentateuch', 25, 50, '經文辨識', '根據《創世記(二)25~50 章》的內容，以下哪一句經文出自這個範圍？', '燔祭壇和壇的一切器具，並洗濯盆與盆座，', '上帝稱空氣為「天」。有晚上，有早晨，是第二日。', '以色列說：「你去看看你哥哥們平安不平安，群羊平安不平安，就回來報信給我」；於是打發他出 希伯崙谷，他就往 示劍去了。', '又琢出兩塊紅瑪瑙，鑲在金槽上，彷彿刻圖書，按着 以色列兒子的名字雕刻；', 2, '正確內容記載於 創世記 37:14。', '創世記 37:14', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-03-4', '03', '創世記(二)25~50 章', 'GEN', '創世記', '舊約', 'pentateuch', 25, 50, '出處辨識', '「把你們的小兄弟帶到我這裏來，如此，你們的話便有證據，你們也不至於死。」他們就照樣而行。」的經文出處是哪裡？', '創世記 44:2', '創世記 42:20', '創世記 27:23', '創世記 29:32', 1, '正確內容記載於 創世記 42:20。', '創世記 42:20', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-03-5', '03', '創世記(二)25~50 章', 'GEN', '創世記', '舊約', 'pentateuch', 25, 50, '經文辨識', '根據《創世記(二)25~50 章》的內容，以下哪一句經文出自這個範圍？', '於是 約瑟為 埃及地定下常例，直到今日：法老必得五分之一，惟獨祭司的地不歸法老。', '你們要追趕仇敵，他們必倒在你們刀下。', '摩西說：「我要過去看這大異象，這荊棘為何沒有燒壞呢？」', '她父親也聽見她所許的願並約束自己的話，卻向她默默不言，她所許的願並約束自己的話就都要為定。', 0, '正確內容記載於 創世記 47:26。', '創世記 47:26', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-04-1', '04', '出埃及記', 'EXO', '出埃及記', '舊約', 'pentateuch', 1, 40, '經文辨識', '根據《出埃及記》的內容，以下哪一句經文出自這個範圍？', '你如今趕逐我離開這地，以致不見你面；我必流離飄蕩在地上，凡遇見我的必殺我。」', '走近 亞捫人之地，不可擾害他們，也不可與他們爭戰。 亞捫人的地，我不賜給你們為業，因我已將那地賜給 羅得的子孫為業。』（', '拉結說：「上帝伸了我的冤，也聽了我的聲音，賜我一個兒子」，因此給他起名叫 但。', '但法老說：「你們是懶惰的！你們是懶惰的！所以說：『容我們去祭祀耶和華。』', 3, '正確內容記載於 出埃及記 5:17。', '出埃及記 5:17', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-04-2', '04', '出埃及記', 'EXO', '出埃及記', '舊約', 'pentateuch', 1, 40, '出處辨識', '「他們從 疏割起行，在曠野邊的 以倘安營。」的經文出處是哪裡？', '出埃及記 29:44', '出埃及記 21:36', '出埃及記 13:20', '出埃及記 16:22', 2, '正確內容記載於 出埃及記 13:20。', '出埃及記 13:20', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-04-3', '04', '出埃及記', 'EXO', '出埃及記', '舊約', 'pentateuch', 1, 40, '經文辨識', '根據《出埃及記》的內容，以下哪一句經文出自這個範圍？', '不可吃的乃是鵰、狗頭鵰、紅頭鵰、', '「凡與獸淫合的，總要把他治死。', '他們從 伯特利起行，離 以法他還有一段路程， 拉結臨產甚是艱難。', '三人中有一位說：「到明年這時候，我必要回到你這裏；你的妻子 撒拉必生一個兒子。」 撒拉在那人後邊的帳棚門口也聽見了這話。', 1, '正確內容記載於 出埃及記 22:19。', '出埃及記 22:19', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-04-4', '04', '出埃及記', 'EXO', '出埃及記', '舊約', 'pentateuch', 1, 40, '出處辨識', '「早晨要獻這一隻，黃昏的時候要獻那一隻。」的經文出處是哪裡？', '出埃及記 29:39', '出埃及記 9:3', '出埃及記 4:1', '出埃及記 28:16', 0, '正確內容記載於 出埃及記 29:39。', '出埃及記 29:39', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-04-5', '04', '出埃及記', 'EXO', '出埃及記', '舊約', 'pentateuch', 1, 40, '經文辨識', '根據《出埃及記》的內容，以下哪一句經文出自這個範圍？', '兩隻公牛，五隻公綿羊，五隻公山羊，五隻一歲的公羊羔作平安祭。這是 丟珥的兒子 以利雅薩的供物。', '從此以後，你的名不再叫 亞伯蘭，要叫 亞伯拉罕，因為我已立你作多國的父。', '猶大啊，你弟兄們必讚美你； 你手必掐住仇敵的頸項； 你父親的兒子們必向你下拜。', '他用精金做一個燈臺；這燈臺的座和幹，與杯、球、花，都是接連一塊錘出來的。', 3, '正確內容記載於 出埃及記 37:17。', '出埃及記 37:17', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-05_1-1', '05-1', '馬可福音(一)1~8 章', 'MRK', '馬可福音', '新約', 'gospels', 1, 8, '經文辨識', '根據《馬可福音(一)1~8 章》的內容，以下哪一句經文出自這個範圍？', '耶穌治好了許多害各樣病的人，又趕出許多鬼，不許鬼說話，因為鬼認識他。', '烏西雅生 約坦； 約坦生 亞哈斯； 亞哈斯生 希西家；', '「我又告訴你們，凡在人面前認我的，人子在上帝的使者面前也必認他；', '亞伯拉罕生 以撒； 以撒生 雅各； 雅各生 猶大和他的弟兄；', 0, '正確內容記載於 馬可福音 1:34。', '馬可福音 1:34', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-05_1-2', '05-1', '馬可福音(一)1~8 章', 'MRK', '馬可福音', '新約', 'gospels', 1, 8, '出處辨識', '「若一家自相紛爭，那家就站立不住。」的經文出處是哪裡？', '馬可福音 1:11', '馬可福音 3:25', '馬可福音 7:4', '馬可福音 2:1', 1, '正確內容記載於 馬可福音 3:25。', '馬可福音 3:25', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-05_1-3', '05-1', '馬可福音(一)1~8 章', 'MRK', '馬可福音', '新約', 'gospels', 1, 8, '經文辨識', '根據《馬可福音(一)1~8 章》的內容，以下哪一句經文出自這個範圍？', '就差他們往 伯利恆去，說：「你們去仔細尋訪那小孩子，尋到了就來報信，我也好去拜他。」', '這樣，從 亞伯拉罕到 大衛共有十四代；從 大衛到遷至 巴比倫的時候也有十四代；從遷至 巴比倫的時候到基督又有十四代。', '耶穌准了他們，污鬼就出來，進入豬裏去。於是那群豬闖下山崖，投在海裏，淹死了。 豬的數目約有二千。', '因為將來有好些人冒我的名來，說：『我是基督』，並且要迷惑許多人。', 2, '正確內容記載於 馬可福音 5:13。', '馬可福音 5:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-05_1-4', '05-1', '馬可福音(一)1~8 章', 'MRK', '馬可福音', '新約', 'gospels', 1, 8, '出處辨識', '「耶穌出來，見有許多的人，就憐憫他們，因為他們如同羊沒有牧人一般，於是開口教訓他們許多道理。」的經文出處是哪裡？', '馬可福音 3:24', '馬可福音 6:2', '馬可福音 6:15', '馬可福音 6:34', 3, '正確內容記載於 馬可福音 6:34。', '馬可福音 6:34', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-05_1-5', '05-1', '馬可福音(一)1~8 章', 'MRK', '馬可福音', '新約', 'gospels', 1, 8, '經文辨識', '根據《馬可福音(一)1~8 章》的內容，以下哪一句經文出自這個範圍？', '又有幾條小魚；耶穌祝了福，就吩咐也擺在眾人面前。', '合城的人都出來迎見耶穌，既見了就央求他離開他們的境界。', '耶穌周圍一看，對門徒說：「有錢財的人進上帝的國是何等地難哪！」', '耶穌從那裏往前走，看見一個人名叫 馬太，坐在稅關上，就對他說：「你跟從我來。」他就起來跟從了耶穌。', 0, '正確內容記載於 馬可福音 8:7。', '馬可福音 8:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-05_2-1', '05-2', '馬可福音(二)9~16 章', 'MRK', '馬可福音', '新約', 'gospels', 9, 16, '經文辨識', '根據《馬可福音(二)9~16 章》的內容，以下哪一句經文出自這個範圍？', '亞伯拉罕生 以撒； 以撒生 雅各； 雅各生 猶大和他的弟兄；', '耶穌坐下，叫十二個門徒來，說：「若有人願意作首先的，他必作眾人末後的，作眾人的用人。」', '問他說：「你告訴我們，你仗着甚麼權柄做這些事？給你這權柄的是誰呢？」', '耶穌對眾人說：「你們要努力進窄門。我告訴你們，將來有許多人想要進去，卻是不能。', 1, '正確內容記載於 馬可福音 9:35。', '馬可福音 9:35', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-05_2-2', '05-2', '馬可福音(二)9~16 章', 'MRK', '馬可福音', '新約', 'gospels', 9, 16, '出處辨識', '「他們去了，便看見一匹驢駒拴在門外街道上，就把牠解開。」的經文出處是哪裡？', '馬可福音 10:45', '馬可福音 11:28', '馬可福音 11:4', '馬可福音 14:37', 2, '正確內容記載於 馬可福音 11:4。', '馬可福音 11:4', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-05_2-3', '05-2', '馬可福音(二)9~16 章', 'MRK', '馬可福音', '新約', 'gospels', 9, 16, '經文辨識', '根據《馬可福音(二)9~16 章》的內容，以下哪一句經文出自這個範圍？', '「你們不要論斷人，免得你們被論斷。', '以律生 以利亞撒； 以利亞撒生 馬但； 馬但生 雅各；', '愛惜自己生命的，就失喪生命；在這世上恨惡自己生命的，就要保守生命到永生。', '耶穌對銀庫坐着，看眾人怎樣投錢入庫。有好些財主往裏投了若干的錢。', 3, '正確內容記載於 馬可福音 12:41。', '馬可福音 12:41', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-05_2-4', '05-2', '馬可福音(二)9~16 章', 'MRK', '馬可福音', '新約', 'gospels', 9, 16, '出處辨識', '「耶穌對他說：「我實在告訴你，就在今天夜裏，雞叫兩遍以先，你要三次不認我。」的經文出處是哪裡？', '馬可福音 14:30', '馬可福音 11:20', '馬可福音 9:9', '馬可福音 12:29', 0, '正確內容記載於 馬可福音 14:30。', '馬可福音 14:30', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-05_2-5', '05-2', '馬可福音(二)9~16 章', 'MRK', '馬可福音', '新約', 'gospels', 9, 16, '經文辨識', '根據《馬可福音(二)9~16 章》的內容，以下哪一句經文出自這個範圍？', '他們給他脫了衣服，穿上一件朱紅色袍子，', '我若靠着別西卜趕鬼，你們的子弟趕鬼又靠着誰呢？這樣，他們就要斷定你們的是非。', '以色列的王基督，現在可以從十字架上下來，叫我們看見，就信了。」那和他同釘的人也是譏誚他。', '他們不明白耶穌是指着父說的。', 2, '正確內容記載於 馬可福音 15:32。', '馬可福音 15:32', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-06-1', '06', '利未記', 'LEV', '利未記', '舊約', 'pentateuch', 1, 27, '經文辨識', '根據《利未記》的內容，以下哪一句經文出自這個範圍？', '約瑟住在他主人 埃及人的家中，耶和華與他同在，他就百事順利。', '祭司要用指頭蘸些贖罪祭牲的血，抹在燔祭壇的四角上，所有的血都要倒在壇的腳那裏，', '他們從 伯特利起行，離 以法他還有一段路程， 拉結臨產甚是艱難。', '並將我的銀杯和那少年人糴糧的銀子一同裝在他的口袋裏。」家宰就照 約瑟所說的話行了；', 1, '正確內容記載於 利未記 4:34。', '利未記 4:34', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-06-2', '06', '利未記', 'LEV', '利未記', '舊約', 'pentateuch', 1, 27, '出處辨識', '「凡在海裏、河裏，並一切水裏游動的活物，無翅無鱗的，你們都當以為可憎。」的經文出處是哪裡？', '利未記 11:10', '利未記 8:2', '利未記 27:16', '利未記 13:49', 0, '正確內容記載於 利未記 11:10。', '利未記 11:10', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-06-3', '06', '利未記', 'LEV', '利未記', '舊約', 'pentateuch', 1, 27, '經文辨識', '根據《利未記》的內容，以下哪一句經文出自這個範圍？', '利百加對 以撒說：「我因這 赫人的女子連性命都厭煩了；倘若 雅各也娶 赫人的女子為妻，像這些一樣，我活着還有甚麼益處呢？」', '就用一百塊 銀子向 示劍的父親、 哈抹的子孫買了支帳棚的那塊地，', '我願你如今在這裏指着上帝對我起誓，不要欺負我與我的兒子，並我的子孫。我怎樣厚待了你，你也要照樣厚待我與你所寄居這地的民。」', '患漏症的人沒有用水涮手，無論摸了誰，誰必不潔淨到晚上，並要洗衣服，用水洗澡。', 3, '正確內容記載於 利未記 15:11。', '利未記 15:11', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-06-4', '06', '利未記', 'LEV', '利未記', '舊約', 'pentateuch', 1, 27, '出處辨識', '「無論男女，是交鬼的或行巫術的，總要治死他們。人必用石頭把他們打死，罪要歸到他們身上。」的經文出處是哪裡？', '利未記 2:3', '利未記 14:21', '利未記 20:27', '利未記 4:3', 2, '正確內容記載於 利未記 20:27。', '利未記 20:27', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-06-5', '06', '利未記', 'LEV', '利未記', '舊約', 'pentateuch', 1, 27, '經文辨識', '根據《利未記》的內容，以下哪一句經文出自這個範圍？', '你們眼中不要愛惜你們的家具，因為 埃及全地的美物都是你們的。』」', '他和買主同住，要像每年雇的工人，買主不可嚴嚴地轄管他。', '你如今趕逐我離開這地，以致不見你面；我必流離飄蕩在地上，凡遇見我的必殺我。」', '就是在 迦南地 幔利前、 麥比拉田間的洞；那洞和田是 亞伯拉罕向 赫人 以弗崙買來為業，作墳地的。', 1, '正確內容記載於 利未記 25:53。', '利未記 25:53', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-07_1-1', '07-1', '路加福音(一)1~12 章', 'LUK', '路加福音', '新約', 'gospels', 1, 12, '經文辨識', '根據《路加福音(一)1~12 章》的內容，以下哪一句經文出自這個範圍？', '凡聽見的人都將這事放在心裏，說：「這個孩子將來怎麼樣呢？因為有主與他同在。」', '凡不結好果子的樹就砍下來，丟在火裏。', '當下，有一個婦人，她的小女兒被污鬼附着，聽見耶穌的事，就來俯伏在他腳前。', '我實實在在地告訴你，你年少的時候，自己束上 帶子，隨意往來；但年老的時候，你要伸出手來，別人要把你束上，帶你到不願意去的地方。」', 0, '正確內容記載於 路加福音 1:66。', '路加福音 1:66', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-07_1-2', '07-1', '路加福音(一)1~12 章', 'LUK', '路加福音', '新約', 'gospels', 1, 12, '出處辨識', '「耶穌對他們說：「你們必引這俗語向我說：『醫生，你醫治自己吧！我們聽見你在 迦百農所行的事，也當行在你自…」的經文出處是哪裡？', '路加福音 5:25', '路加福音 12:30', '路加福音 9:42', '路加福音 4:23', 3, '正確內容記載於 路加福音 4:23。', '路加福音 4:23', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-07_1-3', '07-1', '路加福音(一)1~12 章', 'LUK', '路加福音', '新約', 'gospels', 1, 12, '經文辨識', '根據《路加福音(一)1~12 章》的內容，以下哪一句經文出自這個範圍？', '那死人就坐起，並且說話。耶穌便把他交給他母親。', '左右的人見光景不好，就說：「主啊！我們拿刀砍可以不可以？」', '耶穌又離開他們去了。第三次禱告，說的話還是與先前一樣。', '祭司長和文士看見耶穌所行的奇事，又見小孩子在殿裏喊着說：「和散那歸於 大衛的子孫！」就甚惱怒，', 0, '正確內容記載於 路加福音 7:15。', '路加福音 7:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-07_1-4', '07-1', '路加福音(一)1~12 章', 'LUK', '路加福音', '新約', 'gospels', 1, 12, '出處辨識', '「彼得和他的同伴都打盹，既清醒了，就看見耶穌的榮光，並同他站着的那兩個人。」的經文出處是哪裡？', '路加福音 9:20', '路加福音 9:32', '路加福音 1:75', '路加福音 1:32', 1, '正確內容記載於 路加福音 9:32。', '路加福音 9:32', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-07_1-5', '07-1', '路加福音(一)1~12 章', 'LUK', '路加福音', '新約', 'gospels', 1, 12, '經文辨識', '根據《路加福音(一)1~12 章》的內容，以下哪一句經文出自這個範圍？', '你們律法師有禍了！因為你們把知識的鑰匙奪了去，自己不進去，正要進去的人你們也阻擋他們。」', '有一朵雲彩來遮蓋他們；也有聲音從雲彩裏出來，說：「這是我的愛子，你們要聽他。」', '這天國的福音要傳遍天下，對萬民作見證，然後末期才來到。」', '但我告訴你們，當審判的日子， 所多瑪所受的，比你還容易受呢！」', 0, '正確內容記載於 路加福音 11:52。', '路加福音 11:52', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-07_2-1', '07-2', '路加福音(二)13~24 章', 'LUK', '路加福音', '新約', 'gospels', 13, 24, '經文辨識', '根據《路加福音(二)13~24 章》的內容，以下哪一句經文出自這個範圍？', '「你們聽見有話說：『當愛你的鄰舍，恨你的仇敵。』', '起來！我們走吧。看哪，賣我的人近了！」', '奮銳黨的 西門，還有賣耶穌的 加略人 猶大。', '眾人一口同音地推辭。頭一個說：『我買了一塊地，必須去看看。請你准我辭了。』', 3, '正確內容記載於 路加福音 14:18。', '路加福音 14:18', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-07_2-2', '07-2', '路加福音(二)13~24 章', 'LUK', '路加福音', '新約', 'gospels', 13, 24, '出處辨識', '「人也不得說：『看哪，在這裏！看哪，在那裏！』因為上帝的國就在你們心裏。」的經文出處是哪裡？', '路加福音 16:1', '路加福音 14:17', '路加福音 17:21', '路加福音 22:32', 2, '正確內容記載於 路加福音 17:21。', '路加福音 17:21', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-07_2-3', '07-2', '路加福音(二)13~24 章', 'LUK', '路加福音', '新約', 'gospels', 13, 24, '經文辨識', '根據《路加福音(二)13~24 章》的內容，以下哪一句經文出自這個範圍？', '人點燈，不放在斗底下，是放在燈臺上，就照亮一家的人。', '耶穌進了殿，趕出裏頭做買賣的人，', '耶穌就動了慈心，把他們的眼睛一摸，他們立刻看見，就跟從了耶穌。', '馬大對耶穌說：「主啊，你若早在這裏，我兄弟必不死。', 1, '正確內容記載於 路加福音 19:45。', '路加福音 19:45', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-07_2-4', '07-2', '路加福音(二)13~24 章', 'LUK', '路加福音', '新約', 'gospels', 13, 24, '出處辨識', '「飯後也照樣拿起杯來，說：「這杯是用我血所立的新約，是為你們流出來的。」的經文出處是哪裡？', '路加福音 22:20', '路加福音 20:6', '路加福音 13:4', '路加福音 13:24', 0, '正確內容記載於 路加福音 22:20。', '路加福音 22:20', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-07_2-5', '07-2', '路加福音(二)13~24 章', 'LUK', '路加福音', '新約', 'gospels', 13, 24, '經文辨識', '根據《路加福音(二)13~24 章》的內容，以下哪一句經文出自這個範圍？', '於是耶穌對門徒說：「若有人要跟從我，就當捨己，背起他的十字架來跟從我。', '不料，那些園戶彼此說：『這是承受產業的。來吧，我們殺他，產業就歸我們了！』', '猶大從 她瑪氏生 法勒斯和 謝拉； 法勒斯生 希斯崙； 希斯崙生 亞蘭；', '那日是預備日，安息日也快到了。', 3, '正確內容記載於 路加福音 23:54。', '路加福音 23:54', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-08_1-1', '08-1', '民數記(一)1~18 章', 'NUM', '民數記', '舊約', 'pentateuch', 1, 18, '經文辨識', '根據《民數記(一)1~18 章》的內容，以下哪一句經文出自這個範圍？', '以撒便領 利百加進了他母親 撒拉的帳棚，娶了她為妻，並且愛她。 以撒自從他母親不在了，這才得了安慰。', '於是， 摩西曉諭 亞倫和 亞倫的子孫，並 以色列眾人。', '第七天，再把頭上所有的頭髮與鬍鬚、眉毛，並全身的毛，都剃了；又要洗衣服，用水洗身，就潔淨了。', '他軍隊被數的，共有三萬五千四百名。', 3, '正確內容記載於 民數記 2:23。', '民數記 2:23', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-08_1-2', '08-1', '民數記(一)1~18 章', 'NUM', '民數記', '舊約', 'pentateuch', 1, 18, '出處辨識', '「又要從素祭中取出一把，作為這事的紀念，燒在壇上，然後叫婦人喝這水。」的經文出處是哪裡？', '民數記 16:37', '民數記 4:2', '民數記 5:26', '民數記 10:4', 2, '正確內容記載於 民數記 5:26。', '民數記 5:26', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-08_1-3', '08-1', '民數記(一)1~18 章', 'NUM', '民數記', '舊約', 'pentateuch', 1, 18, '經文辨識', '根據《民數記(一)1~18 章》的內容，以下哪一句經文出自這個範圍？', '百姓就都摘下他們耳上的金環，拿來給 亞倫。', '然後 利未人進去，在 亞倫和他兒子面前，在會幕中辦事。耶和華指着 利未人怎樣吩咐 摩西， 以色列人就怎樣向他們行了。', '雖是這樣，他們在仇敵之地，我卻不厭棄他們，也不厭惡他們，將他們盡行滅絕，也不背棄我與他們所立的約，因為我是耶和華－他們的上帝。', '「你們曉諭 以色列人說：人若身患漏症，他因這漏症就不潔淨了。', 1, '正確內容記載於 民數記 8:22。', '民數記 8:22', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-08_1-4', '08-1', '民數記(一)1~18 章', 'NUM', '民數記', '舊約', 'pentateuch', 1, 18, '出處辨識', '「屬 迦得支派的有 瑪基的兒子 臼利。」的經文出處是哪裡？', '民數記 13:15', '民數記 1:2', '民數記 3:18', '民數記 6:10', 0, '正確內容記載於 民數記 13:15。', '民數記 13:15', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-08_1-5', '08-1', '民數記(一)1~18 章', 'NUM', '民數記', '舊約', 'pentateuch', 1, 18, '經文辨識', '根據《民數記(一)1~18 章》的內容，以下哪一句經文出自這個範圍？', '為甚麼說她是你的妹子，以致我把她取來要作我的妻子？現在你的妻子在這裏，可以帶她走吧。」', '要將這兩塊寶石安在以弗得的兩條肩帶上，為 以色列人做紀念石。 亞倫要在兩肩上擔他們的名字，在耶和華面前作為紀念。', '他喝了園中的酒便醉了，在帳棚裏赤着身子。', '摩西說：「我行的這一切事本不是憑我自己心意行的，乃是耶和華打發我行的，必有證據使你們知道。', 3, '正確內容記載於 民數記 16:28。', '民數記 16:28', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-08_2-1', '08-2', '民數記(二)19~36 章', 'NUM', '民數記', '舊約', 'pentateuch', 19, 36, '經文辨識', '根據《民數記(二)19~36 章》的內容，以下哪一句經文出自這個範圍？', '你向僕人所施的一切慈愛和誠實，我一點也不配得；我先前只拿着我的杖過這 約旦河，如今我卻成了兩隊了。', '你們一切男丁要一年三次朝見主耶和華－ 以色列的上帝。', '摩西便製造一條銅蛇，掛在杆子上；凡被蛇咬的，一望這銅蛇就活了。', '那地的主－ 希未人、 哈抹的兒子 示劍看見她，就拉住她，與她行淫，玷辱她。', 2, '正確內容記載於 民數記 21:9。', '民數記 21:9', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-08_2-2', '08-2', '民數記(二)19~36 章', 'NUM', '民數記', '舊約', 'pentateuch', 19, 36, '出處辨識', '「有一位出於 雅各的，必掌大權； 他要除滅城中的餘民。」的經文出處是哪裡？', '民數記 19:11', '民數記 24:19', '民數記 24:15', '民數記 21:7', 1, '正確內容記載於 民數記 24:19。', '民數記 24:19', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-08_2-3', '08-2', '民數記(二)19~36 章', 'NUM', '民數記', '舊約', 'pentateuch', 19, 36, '經文辨識', '根據《民數記(二)19~36 章》的內容，以下哪一句經文出自這個範圍？', '每隻羊羔要用調油的細麵 伊法十分之一作為素祭和馨香的燔祭，是獻給耶和華的火祭。', '「在耶和華－你上帝所賜你為業的地上，若遇見被殺的人倒在田野，不知道是誰殺的，', '以諾活到六十五歲，生了 瑪土撒拉。', '「若遇見你仇敵的牛或驢失迷了路，總要牽回來交給他。', 0, '正確內容記載於 民數記 28:13。', '民數記 28:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-08_2-4', '08-2', '民數記(二)19~36 章', 'NUM', '民數記', '舊約', 'pentateuch', 19, 36, '出處辨識', '「摩西和祭司 以利亞撒就收了他們的金子，都是打成的器皿。」的經文出處是哪裡？', '民數記 31:36', '民數記 29:39', '民數記 28:13', '民數記 31:51', 3, '正確內容記載於 民數記 31:51。', '民數記 31:51', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-08_2-5', '08-2', '民數記(二)19~36 章', 'NUM', '民數記', '舊約', 'pentateuch', 19, 36, '經文辨識', '根據《民數記(二)19~36 章》的內容，以下哪一句經文出自這個範圍？', '上帝說：「天下的水要聚在一處，使旱地露出來。」事就這樣成了。', '耶和華－你的上帝把城交付你手，你就要用刀殺盡這城的男丁。', '又要從每支派中選一個首領幫助他們。', '摩西手裏拿着兩塊法版下 西奈山的時候，不知道自己的面皮因耶和華和他說話就發了光。', 2, '正確內容記載於 民數記 34:18。', '民數記 34:18', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-09_1-1', '09-1', '申命記（一）1~11章', 'DEU', '申命記', '舊約', 'pentateuch', 1, 11, '經文辨識', '根據《申命記（一）1~11章》的內容，以下哪一句經文出自這個範圍？', '「耶和華聽見你們這話，就發怒，起誓說：', '隨後要脫去這衣服，穿上別的衣服，把灰拿到營外潔淨之處。', '上帝稱光為「晝」，稱暗為「夜」。有晚上，有早晨，這是頭一日。', '但各人用銀子買的奴僕，既受了割禮就可以吃。', 0, '正確內容記載於 申命記 1:34。', '申命記 1:34', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-09_1-2', '09-1', '申命記（一）1~11章', 'DEU', '申命記', '舊約', 'pentateuch', 1, 11, '出處辨識', '「你不要怕他們，因那為你爭戰的是耶和華－你的上帝。』」的經文出處是哪裡？', '申命記 1:21', '申命記 10:7', '申命記 3:22', '申命記 3:26', 2, '正確內容記載於 申命記 3:22。', '申命記 3:22', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-09_1-3', '09-1', '申命記（一）1~11章', 'DEU', '申命記', '舊約', 'pentateuch', 1, 11, '經文辨識', '根據《申命記（一）1~11章》的內容，以下哪一句經文出自這個範圍？', '你也要記念你在 埃及地作過奴僕；耶和華－你上帝用大能的手和伸出來的膀臂將你從那裏領出來。因此，耶和華－你的上帝吩咐你守安息日。', '亞革波的兒子 巴勒‧哈南死了， 哈達接續他作王，他的 京城名叫 巴烏；他的妻子名叫 米希她別，是 米‧薩合的孫女， 瑪特列的女兒。', '在 以色列營前行走上帝的使者，轉到他們後邊去；雲柱也從他們前邊轉到他們後邊立住。', '人多的，你要把產業多分給他們；人少的，你要把產業少分給他們；要照被數的人數，把產業分給各人。', 0, '正確內容記載於 申命記 5:15。', '申命記 5:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-09_1-4', '09-1', '申命記（一）1~11章', 'DEU', '申命記', '舊約', 'pentateuch', 1, 11, '出處辨識', '「你也要記念耶和華－你的上帝在曠野引導你這四十年，是要苦煉你，試驗你，要知道你心內如何，肯守他的誡命不肯。」的經文出處是哪裡？', '申命記 4:40', '申命記 3:14', '申命記 1:27', '申命記 8:2', 3, '正確內容記載於 申命記 8:2。', '申命記 8:2', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-09_1-5', '09-1', '申命記（一）1~11章', 'DEU', '申命記', '舊約', 'pentateuch', 1, 11, '經文辨識', '根據《申命記（一）1~11章》的內容，以下哪一句經文出自這個範圍？', '他們要抬帳幕的幔子和會幕，並會幕的蓋與其上的海狗皮，和會幕的門簾，', '那與 雅各同到 埃及的，除了他兒婦之外，凡從他所生的，共有六十六人。', '他是你所讚美的，是你的上帝，為你做了那大而可畏的事，是你親眼所看見的。', '他用皂莢木做香壇，是四方的，長一肘，寬一肘，高二肘，壇的四角與壇接連一塊；', 2, '正確內容記載於 申命記 10:21。', '申命記 10:21', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-09_2-1', '09-2', '申命記(二)12~34 章', 'DEU', '申命記', '舊約', 'pentateuch', 12, 34, '經文辨識', '根據《申命記(二)12~34 章》的內容，以下哪一句經文出自這個範圍？', '創造天地的來歷，在耶和華上帝造天地的日子，乃是這樣，', '耶和華說：「我若在 所多瑪城裏見有五十個義人，我就為他們的緣故饒恕那地方的眾人。」', '鴕鳥、夜鷹、魚鷹、鷹與其類，', '對他們說：「你們要存留這一切婦女的活命嗎？', 2, '正確內容記載於 申命記 14:15。', '申命記 14:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-09_2-2', '09-2', '申命記(二)12~34 章', 'DEU', '申命記', '舊約', 'pentateuch', 12, 34, '出處辨識', '「你眼不可顧惜，要以命償命，以眼還眼，以牙還牙，以手還手，以腳還腳。」的經文出處是哪裡？', '申命記 19:21', '申命記 25:11', '申命記 17:12', '申命記 28:4', 0, '正確內容記載於 申命記 19:21。', '申命記 19:21', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-09_2-3', '09-2', '申命記(二)12~34 章', 'DEU', '申命記', '舊約', 'pentateuch', 12, 34, '經文辨識', '根據《申命記(二)12~34 章》的內容，以下哪一句經文出自這個範圍？', '法老說：「我容你們去，在曠野祭祀耶和華－你們的上帝；只是不要走得很遠。求你們為我祈禱。」', '上帝說：「地要發生青草和結種子的菜蔬，並結果子的樹木，各從其類，果子都包着核。」事就這樣成了。', '第三道河名叫 底格里斯，流在 亞述的東邊。第四道河就是 幼發拉底河。', '你也要記念你在 埃及地作過奴僕，所以我吩咐你這樣行。', 3, '正確內容記載於 申命記 24:22。', '申命記 24:22', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-09_2-4', '09-2', '申命記(二)12~34 章', 'DEU', '申命記', '舊約', 'pentateuch', 12, 34, '出處辨識', '「這書上所寫律法的一切話是叫你敬畏耶和華－你上帝可榮可畏的名。你若不謹守遵行，耶和華就必將奇災，就是至…」的經文出處是哪裡？', '申命記 23:1', '申命記 12:19', '申命記 28:58–59', '申命記 12:3', 2, '正確內容記載於 申命記 28:58–59。', '申命記 28:58–59', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-09_2-5', '09-2', '申命記(二)12~34 章', 'DEU', '申命記', '舊約', 'pentateuch', 12, 34, '經文辨識', '根據《申命記(二)12~34 章》的內容，以下哪一句經文出自這個範圍？', '那逃到逃城的人，你們不可為他收贖價，使他在大祭司未死以先再來住在本地。', '他們的酒是大蛇的毒氣， 是虺蛇殘害的惡毒。', '他軍隊被數的，共有四萬零五百名。', '你們的屍首必倒在這曠野，並且你們中間凡被數點、從二十歲以外、向我發怨言的，', 1, '正確內容記載於 申命記 32:33。', '申命記 32:33', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-10_1-1', '10-1', '約翰福音(一)1~10 章', 'JHN', '約翰福音', '新約', 'gospels', 1, 10, '經文辨識', '根據《約翰福音(一)1~10 章》的內容，以下哪一句經文出自這個範圍？', '然而，不要因鬼服了你們就歡喜，要因你們的名記錄在天上歡喜。」', '因為常有窮人和你們同在，要向他們行善隨時都可以；只是你們不常有我。', '拿但業說：「拉比，你是上帝的兒子，你是 以色列的王！」', '壓傷的蘆葦，他不折斷； 將殘的燈火，他不吹滅； 等他施行公理，叫公理得勝。', 2, '正確內容記載於 約翰福音 1:49。', '約翰福音 1:49', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-10_1-2', '10-1', '約翰福音(一)1~10 章', 'JHN', '約翰福音', '新約', 'gospels', 1, 10, '出處辨識', '「耶穌說：「我的食物就是遵行差我來者的旨意，做成他的工。」的經文出處是哪裡？', '約翰福音 1:6', '約翰福音 4:48', '約翰福音 6:49', '約翰福音 4:34', 3, '正確內容記載於 約翰福音 4:34。', '約翰福音 4:34', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-10_1-3', '10-1', '約翰福音(一)1~10 章', 'JHN', '約翰福音', '新約', 'gospels', 1, 10, '經文辨識', '根據《約翰福音(一)1~10 章》的內容，以下哪一句經文出自這個範圍？', '眾人問他說：「我們當行甚麼才算做上帝的工呢？」', '又對那門徒說：「看，你的母親！」從此，那門徒就接她到自己家裏去了。', '耶穌在教訓之間，說：「你們要防備文士；他們好穿長衣遊行，喜愛人在街市上問他們的安，', '只因聽見 亞基老接着他父親 希律作了 猶太王，就怕往那裏去，又在夢中被 主指示，便往 加利利境內去了，', 0, '正確內容記載於 約翰福音 6:28。', '約翰福音 6:28', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-10_1-4', '10-1', '約翰福音(一)1~10 章', 'JHN', '約翰福音', '新約', 'gospels', 1, 10, '出處辨識', '「他們回答說：「你也是出於 加利利嗎？你且去查考，就可知道 加利利沒有出過先知。」的經文出處是哪裡？', '約翰福音 1:8', '約翰福音 7:52', '約翰福音 8:38', '約翰福音 5:15', 1, '正確內容記載於 約翰福音 7:52。', '約翰福音 7:52', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-10_1-5', '10-1', '約翰福音(一)1~10 章', 'JHN', '約翰福音', '新約', 'gospels', 1, 10, '經文辨識', '根據《約翰福音(一)1~10 章》的內容，以下哪一句經文出自這個範圍？', '他們去了，所遇見的正如耶穌所說的；他們就預備了逾越 節的筵席。', '他就撇下所有的，起來，跟從了耶穌。', '這人若不是從上帝來的，甚麼也不能做。」', '約細是 以利以謝的兒子； 以利以謝是 約令的兒子； 約令是 瑪塔的兒子； 瑪塔是 利未的兒子；', 2, '正確內容記載於 約翰福音 9:33。', '約翰福音 9:33', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-10_2-1', '10-2', '約翰福音(二)11~21 章', 'JHN', '約翰福音', '新約', 'gospels', 11, 21, '經文辨識', '根據《約翰福音(二)11~21 章》的內容，以下哪一句經文出自這個範圍？', '你們要謹慎！若是你的弟兄得罪 你，就勸戒他；他若懊悔，就饒恕他。', '那領一千的也來，說：『主啊，我知道你是忍心的人，沒有種的地方要收割，沒有散的地方要聚斂，', '他們就吐唾沫在他臉上，用拳頭打他，也有用手掌打他的，說：', '他們就把石頭挪開。耶穌舉目 望天，說：「父啊，我感謝你，因為你已經聽我。', 3, '正確內容記載於 約翰福音 11:41。', '約翰福音 11:41', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-10_2-2', '10-2', '約翰福音(二)11~21 章', 'JHN', '約翰福音', '新約', 'gospels', 11, 21, '出處辨識', '「耶穌洗完了他們的腳，就穿上衣服，又坐下，對他們說：「我向你們所做的，你們明白嗎？」的經文出處是哪裡？', '約翰福音 13:12', '約翰福音 19:37', '約翰福音 21:21', '約翰福音 11:11', 0, '正確內容記載於 約翰福音 13:12。', '約翰福音 13:12', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-10_2-3', '10-2', '約翰福音(二)11~21 章', 'JHN', '約翰福音', '新約', 'gospels', 11, 21, '經文辨識', '根據《約翰福音(二)11~21 章》的內容，以下哪一句經文出自這個範圍？', '他禁食四十晝夜，後來就餓了。', '我若沒有來教訓他們，他們就沒有罪；但如今他們的罪無可推諉了。', '一個邪惡淫亂的世代求神蹟，除了 約拿的神蹟以外，再沒有神蹟給他看。」耶穌就離開他們去了。', '眾人一口同音地推辭。頭一個說：『我買了一塊地，必須去看看。請你准我辭了。』', 1, '正確內容記載於 約翰福音 15:22。', '約翰福音 15:22', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-10_2-4', '10-2', '約翰福音(二)11~21 章', 'JHN', '約翰福音', '新約', 'gospels', 11, 21, '出處辨識', '「僕人和差役因為天冷，就生了炭火，站在那裏烤火； 彼得也同他們站着烤火。」的經文出處是哪裡？', '約翰福音 11:15', '約翰福音 13:23', '約翰福音 18:18', '約翰福音 12:15', 2, '正確內容記載於 約翰福音 18:18。', '約翰福音 18:18', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-10_2-5', '10-2', '約翰福音(二)11~21 章', 'JHN', '約翰福音', '新約', 'gospels', 11, 21, '經文辨識', '根據《約翰福音(二)11~21 章》的內容，以下哪一句經文出自這個範圍？', '所以，不要憂慮說，吃甚麼？喝甚麼？穿甚麼？', '眾人卻一齊喊着說：「除掉這個人！釋放 巴拉巴給我們！」', '他對父親說：『我服事你這多年，從來沒有違背過你的命，你並沒有給我一隻山羊羔，叫我和朋友一同快樂。', '耶穌說：「 馬利亞。」 馬利亞就轉過來，用希伯來話對他說：「拉波尼！」（拉波尼就是夫子的意思。）', 3, '正確內容記載於 約翰福音 20:16。', '約翰福音 20:16', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-11-1', '11', '約書亞記', 'JOS', '約書亞記', '舊約', 'history', 1, 24, '經文辨識', '根據《約書亞記》的內容，以下哪一句經文出自這個範圍？', '上帝已將 米甸人的兩個首領 俄立和 西伊伯交在你們手中；我所行的豈能比你們所行的呢？」 基甸說了這話， 以法蓮人的怒氣就消了。', '亞多蘭掌管服苦的人； 亞希律的兒子 約沙法作史官；', '對 大衛說：「你比我公義；因為你以善待我，我卻以惡待你。', '你們就對他們說：『這是因為 約旦河的水在耶和華的約櫃前斷絕；約櫃過 約旦河的時候， 約旦河的水就斷絕了。這些石頭要作 以色列人永遠的紀念。』」', 3, '正確內容記載於 約書亞記 4:7。', '約書亞記 4:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-11-2', '11', '約書亞記', 'JOS', '約書亞記', '舊約', 'history', 1, 24, '出處辨識', '「他們回答說：「僕人從極遠之地而來，是因聽見耶和華－你上帝的名聲和他在 埃及所行的一切事，」的經文出處是哪裡？', '約書亞記 9:9', '約書亞記 3:1', '約書亞記 7:18', '約書亞記 11:22', 0, '正確內容記載於 約書亞記 9:9。', '約書亞記 9:9', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-11-3', '11', '約書亞記', 'JOS', '約書亞記', '舊約', 'history', 1, 24, '經文辨識', '根據《約書亞記》的內容，以下哪一句經文出自這個範圍？', '他們無論往何處去，耶和華都以災禍攻擊他們，正如耶和華所說的話，又如耶和華向他們所起的誓；他們便極其困苦。', '所羅門在世的日子，從 但到 別是巴的 猶大人和 以色列人都在自己的葡萄樹下和無花果樹下安然居住。', '伯‧毗珥、 毗斯迦山坡、 伯‧耶西末；', '基哈西告訴王 以利沙如何使死人復活，恰巧 以利沙所救活、她兒子的那婦人為自己的房屋田地來哀告王。 基哈西說：「我主我王，這就是那婦人，這是她的兒子，就…', 2, '正確內容記載於 約書亞記 13:20。', '約書亞記 13:20', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-11-4', '11', '約書亞記', 'JOS', '約書亞記', '舊約', 'history', 1, 24, '出處辨識', '「又接連到 亞拉巴對面，往北下到 亞拉巴；」的經文出處是哪裡？', '約書亞記 18:18', '約書亞記 1:5', '約書亞記 10:41', '約書亞記 10:21', 0, '正確內容記載於 約書亞記 18:18。', '約書亞記 18:18', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-11-5', '11', '約書亞記', 'JOS', '約書亞記', '舊約', 'history', 1, 24, '經文辨識', '根據《約書亞記》的內容，以下哪一句經文出自這個範圍？', '瑪挪亞就祈求耶和華說：「主啊，求你再差遣那神人到我們這裏來，好指教我們怎樣待這將要生的孩子。」', '瑪拿西沒有趕出 伯‧善和屬 伯‧善鄉村的 居民， 他納和屬 他納鄉村的 居民， 多珥和屬 多珥鄉村的居民， 以伯蓮和屬 以伯蓮鄉村的居民， 米吉多和屬…', '廊後院內有 所羅門住的宮室；工作與這工作相同。 所羅門又為所娶法老的女兒建造一宮，做法與這廊子一樣。', '從前 謝拉的曾孫 亞干豈不是在那當滅的物上犯了罪，就有忿怒臨到 以色列全會眾嗎？那人在所犯的罪中不獨一人死亡。」', 3, '正確內容記載於 約書亞記 22:20。', '約書亞記 22:20', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-12_1-1', '12-1', '士師記(一)1~10 章', 'JDG', '士師記', '舊約', 'history', 1, 10, '經文辨識', '根據《士師記(一)1~10 章》的內容，以下哪一句經文出自這個範圍？', '大衛聽見了，就說：「流 尼珥的兒子 押尼珥的血，這罪在耶和華面前必永不歸我和我的國。', '亞設支派，能上陣打仗的有四萬人。', '於是， 亞設因為沒有趕出那地的 迦南人，就住在他們中間。', '他行耶和華眼中看為惡的事，不離開 尼八的兒子 耶羅波安使 以色列人陷在罪裏的一切罪。', 2, '正確內容記載於 士師記 1:32。', '士師記 1:32', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
