INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-12_1-3', '12-1', '士師記(一)1~10 章', 'JDG', '士師記', '舊約', 'history', 1, 10, '經文辨識', '根據《士師記(一)1~10 章》的內容，以下哪一句經文出自這個範圍？', '基甸說：「主啊，我有何能拯救 以色列人呢？我家在 瑪拿西支派中是至貧窮的。我在我父家是至微小的。」', '基遍的居民聽見 約書亞向 耶利哥和 艾城所行的事，', '城內的眾民都被招聚，追趕他們； 艾城人追趕的時候，就被引誘離開城。', '亞哈將他的家宰 俄巴底召了來。（ 俄巴底甚是敬畏耶和華，', 0, '正確內容記載於 士師記 6:15。', '士師記 6:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-12_1-4', '12-1', '士師記(一)1~10 章', 'JDG', '士師記', '舊約', 'history', 1, 10, '出處辨識', '「捉住 疏割的一個少年人，問他：「 疏割的首領長老是誰？」他就將首領長老七十七個人的名字寫出來。」的經文出處是哪裡？', '士師記 9:14', '士師記 10:9', '士師記 9:16', '士師記 8:14', 3, '正確內容記載於 士師記 8:14。', '士師記 8:14', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-12_1-5', '12-1', '士師記(一)1~10 章', 'JDG', '士師記', '舊約', 'history', 1, 10, '經文辨識', '根據《士師記(一)1~10 章》的內容，以下哪一句經文出自這個範圍？', '他就把他的人分作三隊，埋伏在田間，看見 示劍人從城裏出來，就起來擊殺他們。', '又接連到 亞拉巴對面，往北下到 亞拉巴；', '非利士人將上帝的 約櫃從 以便以謝抬到 亞實突。', '你們現在要從 以色列支派中揀選十二個人，每支派一人，', 0, '正確內容記載於 士師記 9:43。', '士師記 9:43', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-12_2-1', '12-2', '士師記(二)11~21 章', 'JDG', '士師記', '舊約', 'history', 11, 21, '經文辨識', '根據《士師記(二)11~21 章》的內容，以下哪一句經文出自這個範圍？', '掃羅聽了 約拿單的話，就指着永生的耶和華起誓說：「我必不殺他。」', '耶弗他就向耶和華許願，說：「你若將 亞捫人交在我手中，', '王又對 示每說：「你向我父親 大衛所行的一切惡事，你自己心裏也知道，所以耶和華必使你的罪惡歸到自己的頭上；', '你若洩漏我們這件事，你叫我們所起的誓就與我們無干了。」', 1, '正確內容記載於 士師記 11:30。', '士師記 11:30', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-12_2-2', '12-2', '士師記(二)11~21 章', 'JDG', '士師記', '舊約', 'history', 11, 21, '出處辨識', '「他父親下去見女子。 參孫在那裏設擺筵宴，因為向來少年人都有這個規矩。」的經文出處是哪裡？', '士師記 14:10', '士師記 11:20', '士師記 15:16', '士師記 21:2', 0, '正確內容記載於 士師記 14:10。', '士師記 14:10', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-12_2-3', '12-2', '士師記(二)11~21 章', 'JDG', '士師記', '舊約', 'history', 11, 21, '經文辨識', '根據《士師記(二)11~21 章》的內容，以下哪一句經文出自這個範圍？', '你竟行惡，比那在你以先的更甚，為自己立了別神，鑄了偶像，惹我發怒，將我丟在背後。', '無論甚麼人違背你的命令，不聽從你所吩咐他的一切話，就必治死他。你只要剛強壯膽！」', '二人還沒有躺臥，女人就上房頂，到他們那裏，', '說：「我情願與 非利士人同死！」就盡力屈身，房子倒塌，壓住首領和房內的眾人。這樣， 參孫死時所殺的人比活着所殺的還多。', 3, '正確內容記載於 士師記 16:30。', '士師記 16:30', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-12_2-4', '12-2', '士師記(二)11~21 章', 'JDG', '士師記', '舊約', 'history', 11, 21, '出處辨識', '「他們就往前走。將到 便雅憫的 基比亞，日頭已經落了；」的經文出處是哪裡？', '士師記 19:14', '士師記 11:10', '士師記 11:36', '士師記 12:9', 0, '正確內容記載於 士師記 19:14。', '士師記 19:14', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
