INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_1-1', '13-1', '使徒行傳(一)1~14 章', 'ACT', '使徒行傳', '新約', 'acts', 1, 14, '經文辨識', '根據《使徒行傳(一)1~14 章》的內容，以下哪一句經文出自這個範圍？', '只是我們必要撞在一個島上。」', '所以他們中間多有相信的，又有 希臘尊貴的婦女，男子也不少。', '因你必不將我的靈魂撇在陰間， 也不叫你的聖者見朽壞。', '那七日將完，從 亞細亞來的 猶太人看見 保羅在殿裏，就聳動了眾人，下手拿他，', 2, '正確內容記載於 使徒行傳 2:27。', '使徒行傳 2:27', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_1-2', '13-1', '使徒行傳(一)1~14 章', 'ACT', '使徒行傳', '新約', 'acts', 1, 14, '出處辨識', '「但差役到了，不見他們在監裏，就回來稟報說：」的經文出處是哪裡？', '使徒行傳 5:22', '使徒行傳 14:1', '使徒行傳 3:10', '使徒行傳 7:2', 0, '正確內容記載於 使徒行傳 5:22。', '使徒行傳 5:22', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_1-3', '13-1', '使徒行傳(一)1~14 章', 'ACT', '使徒行傳', '新約', 'acts', 1, 14, '經文辨識', '根據《使徒行傳(一)1~14 章》的內容，以下哪一句經文出自這個範圍？', '他說：「 猶太人已經約定，要求你明天帶下 保羅到公會裏去，假作要詳細查問他的事。', '第二天，到了 西頓； 猶流寬待 保羅，准他往朋友那裏去，受他們的照應。', '打了許多棍，便將他們下在監裏，囑咐禁卒嚴緊看守。', '有一個人，名叫 西門，向來在那城裏行邪術，妄自尊大，使 撒馬利亞的百姓驚奇；', 3, '正確內容記載於 使徒行傳 8:9。', '使徒行傳 8:9', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_1-4', '13-1', '使徒行傳(一)1~14 章', 'ACT', '使徒行傳', '新約', 'acts', 1, 14, '出處辨識', '「所以我被請的時候，就不推辭而來。現在請問：你們叫我來有甚麼意思呢？」的經文出處是哪裡？', '使徒行傳 3:2', '使徒行傳 11:12', '使徒行傳 10:29', '使徒行傳 13:45', 2, '正確內容記載於 使徒行傳 10:29。', '使徒行傳 10:29', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_1-5', '13-1', '使徒行傳(一)1~14 章', 'ACT', '使徒行傳', '新約', 'acts', 1, 14, '經文辨識', '根據《使徒行傳(一)1~14 章》的內容，以下哪一句經文出自這個範圍？', '到了 耶路撒冷，教會和使徒並長老都接待他們，他們就述說上帝同他們所行的一切事。', '雖然查不出他有當死的罪來，還是求 彼拉多殺他；', '眾人都默默無聲，聽 巴拿巴和 保羅述說上帝藉他們在外邦人中所行的神蹟奇事。', '遇見一個 猶太人，名叫 亞居拉，他生在 本都；因為 克勞第命 猶太人都離開 羅馬，新近帶着妻 百基拉，從 意大利來。 保羅就投奔了他們。', 1, '正確內容記載於 使徒行傳 13:28。', '使徒行傳 13:28', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_2-1', '13-2', '使徒行傳(二)15~28 章', 'ACT', '使徒行傳', '新約', 'acts', 15, 28, '經文辨識', '根據《使徒行傳(二)15~28 章》的內容，以下哪一句經文出自這個範圍？', '保羅既看見這異象，我們隨即想要往 馬其頓去，以為上帝召我們傳福音給那裏的人聽。', '太監對 腓利說：「請問，先知說這話是指着誰？是指着自己呢？是指着別人呢？」', '但聖靈降臨在你們身上，你們就必得着能力，並要在 耶路撒冷、 猶太全地，和 撒馬利亞，直到地極，作我的見證。」', '那欺負鄰舍的把他推開，說：『誰立你作我們的首領和審判官呢？', 0, '正確內容記載於 使徒行傳 16:10。', '使徒行傳 16:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_2-2', '13-2', '使徒行傳(二)15~28 章', 'ACT', '使徒行傳', '新約', 'acts', 15, 28, '出處辨識', '「他們聽見這話，就奉主耶穌的名受洗。」的經文出處是哪裡？', '使徒行傳 17:31', '使徒行傳 21:15', '使徒行傳 15:27', '使徒行傳 19:5', 3, '正確內容記載於 使徒行傳 19:5。', '使徒行傳 19:5', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_2-3', '13-2', '使徒行傳(二)15~28 章', 'ACT', '使徒行傳', '新約', 'acts', 15, 28, '經文辨識', '根據《使徒行傳(二)15~28 章》的內容，以下哪一句經文出自這個範圍？', '又次日，他們進入 凱撒利亞， 哥尼流已經請了他的親屬密友等候他們。', '彼得說：「 亞拿尼亞！為甚麼撒但充滿了你的心，叫你欺哄聖靈，把田地的價銀私自留下幾分呢？', '你帶他們去，與他們一同行潔淨的禮，替他們拿出規費，叫他們得以剃頭。這樣，眾人就可知道，先前所聽見你的事都是虛的；並可知道，你自己為人，循規蹈矩，遵行律…', '那時，門徒增多，有說希臘話的 猶太人向 希伯來人發怨言，因為在天天的供給上忽略了他們的寡婦。', 2, '正確內容記載於 使徒行傳 21:24。', '使徒行傳 21:24', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_2-4', '13-2', '使徒行傳(二)15~28 章', 'ACT', '使徒行傳', '新約', 'acts', 15, 28, '出處辨識', '「過了幾年，我帶着賙濟本國的捐項和供獻的物上去。」的經文出處是哪裡？', '使徒行傳 15:27', '使徒行傳 24:17', '使徒行傳 16:19', '使徒行傳 15:17', 1, '正確內容記載於 使徒行傳 24:17。', '使徒行傳 24:17', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_2-5', '13-2', '使徒行傳(二)15~28 章', 'ACT', '使徒行傳', '新約', 'acts', 15, 28, '經文辨識', '根據《使徒行傳(二)15~28 章》的內容，以下哪一句經文出自這個範圍？', '到了第十四天夜間，船在 亞得里亞海飄來飄去。約到半夜，水手以為漸近旱地，', '克里特和 阿拉伯人，都聽見他們用我們的鄉談，講說上帝的大作為。」', '五旬節到了，門徒都聚集在一處。', '於是 彼得被囚在監裏；教會卻為他切切地禱告上帝。', 0, '正確內容記載於 使徒行傳 27:27。', '使徒行傳 27:27', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_3-1', '13-3', '路得記', 'RUT', '路得記', '舊約', 'history', 1, 4, '經文辨識', '根據《路得記》的內容，以下哪一句經文出自這個範圍？', '你僕人曾打死獅子和熊，這未受割禮的 非利士人向永生上帝的軍隊罵陣，也必像獅子和熊一般。」', '米迦說：「你們將我所做的神像和祭司都帶了去，我還有所剩的嗎？怎麼還問我說『做甚麼』呢？」', '抬 約櫃的祭司站在 約旦河中，等到耶和華曉諭 約書亞吩咐百姓的事辦完了，是照 摩西所吩咐 約書亞的一切話。', '願耶和華使你們各在新夫家中得平安！」於是 拿俄米與她們親嘴。她們就放聲而哭，', 3, '正確內容記載於 路得記 1:9。', '路得記 1:9', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_3-2', '13-3', '路得記', 'RUT', '路得記', '舊約', 'history', 1, 4, '出處辨識', '「波阿斯正從 伯利恆來，對收割的人說：「願耶和華與你們同在！」他們回答說：「願耶和華賜福與你！」的經文出處是哪裡？', '路得記 1:9', '路得記 2:3', '路得記 2:4', '路得記 2:1', 2, '正確內容記載於 路得記 2:4。', '路得記 2:4', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_3-3', '13-3', '路得記', 'RUT', '路得記', '舊約', 'history', 1, 4, '經文辨識', '根據《路得記》的內容，以下哪一句經文出自這個範圍？', '但我在 以色列人中 為自己留下七千人，是未曾向 巴力屈膝的，未曾與 巴力親嘴的。」', '摩押女子 路得說：「他對我說：『你要緊隨我的僕人 拾取麥穗，直等他們收完了我的莊稼。』」', '當時， 約書亞轉回奪了 夏瑣，用刀擊殺 夏瑣王。（素來 夏瑣在這諸國中是為首的。）', '以利亞薩生 西斯買； 西斯買生 沙龍；', 1, '正確內容記載於 路得記 2:21。', '路得記 2:21', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_3-4', '13-3', '路得記', 'RUT', '路得記', '舊約', 'history', 1, 4, '出處辨識', '「又對 路得說：「打開你所披的外衣。」她打開了， 波阿斯就撮了六 簸箕大麥，幫她扛在肩上，她便進城去了。」的經文出處是哪裡？', '路得記 3:15', '路得記 1:5', '路得記 1:19', '路得記 1:14', 0, '正確內容記載於 路得記 3:15。', '路得記 3:15', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-13_3-5', '13-3', '路得記', 'RUT', '路得記', '舊約', 'history', 1, 4, '經文辨識', '根據《路得記》的內容，以下哪一句經文出自這個範圍？', '耶和華的僕人 摩西死了以後，耶和華曉諭 摩西的幫手， 嫩的兒子 約書亞，說：', '凡天上之上帝所吩咐的，當為天上上帝的殿詳細辦理。為何使忿怒臨到王和王眾子的國呢？', '耶路‧巴力就是 基甸，他和一切跟隨的人早晨起來，在 哈律泉旁安營。 米甸營在他們北邊的平原，靠近 摩利岡。', '婦人們對 拿俄米說：「耶和華是應當稱頌的！因為今日沒有撇下你，使你無至近的親屬。願這孩子在 以色列中得名聲。', 3, '正確內容記載於 路得記 4:14。', '路得記 4:14', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-14_1-1', '14-1', '撒母耳記上(一)1~15 章', '1SA', '撒母耳記上', '舊約', 'history', 1, 15, '經文辨識', '根據《撒母耳記上(一)1~15 章》的內容，以下哪一句經文出自這個範圍？', '耶和華曉諭 約書亞說：「看哪，我已經把 耶利哥和 耶利哥的王，並大能的勇士，都交在你手中。', '從那裏往東，接連到 迦特‧希弗，至 以特‧加汛，通到 臨門， 臨門延到 尼亞；', '以利加拿往 拉瑪回家去了。那孩子在祭司 以利面前事奉耶和華。', '在 便雅憫有 以拉的兒子 示每；', 2, '正確內容記載於 撒母耳記上 2:11。', '撒母耳記上 2:11', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-14_1-2', '14-1', '撒母耳記上(一)1~15 章', '1SA', '撒母耳記上', '舊約', 'history', 1, 15, '出處辨識', '「就打發人去請 非利士的眾首領來聚集，問他們說：「我們向 以色列上帝的 約櫃應當怎樣行呢？」他們回答說：…」的經文出處是哪裡？', '撒母耳記上 2:29', '撒母耳記上 10:3', '撒母耳記上 9:10', '撒母耳記上 5:8', 3, '正確內容記載於 撒母耳記上 5:8。', '撒母耳記上 5:8', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-14_1-3', '14-1', '撒母耳記上(一)1~15 章', '1SA', '撒母耳記上', '舊約', 'history', 1, 15, '經文辨識', '根據《撒母耳記上(一)1~15 章》的內容，以下哪一句經文出自這個範圍？', '在他還沒有上邱壇吃祭物之先，你們一進城必遇見他；因他未到，百姓不能吃，必等他先祝祭，然後請的客才吃。現在你們上去，這時候必遇見他。」', '謝拉的兒子是 心利、 以探、 希幔、 甲各、 大拉，共五人。', '又往北通到 隱‧示麥，達到 亞都冥坡對面的 基利綠；又下到 呂便之子 波罕的磐石；', '大衛王年紀老邁，雖用被遮蓋，仍不覺暖。', 0, '正確內容記載於 撒母耳記上 9:13。', '撒母耳記上 9:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-14_1-4', '14-1', '撒母耳記上(一)1~15 章', '1SA', '撒母耳記上', '舊約', 'history', 1, 15, '出處辨識', '「撒母耳對百姓說：「不要懼怕！你們雖然行了這惡，卻不要偏離耶和華，只要盡心事奉他。」的經文出處是哪裡？', '撒母耳記上 13:22', '撒母耳記上 14:5', '撒母耳記上 12:20', '撒母耳記上 1:3', 2, '正確內容記載於 撒母耳記上 12:20。', '撒母耳記上 12:20', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-14_1-5', '14-1', '撒母耳記上(一)1~15 章', '1SA', '撒母耳記上', '舊約', 'history', 1, 15, '經文辨識', '根據《撒母耳記上(一)1~15 章》的內容，以下哪一句經文出自這個範圍？', '掃羅奮勇攻擊 亞瑪力人，救了 以色列人脫離搶掠他們之人的手。', '耶戶對他的軍長 畢甲說：「你把他拋在 耶斯列人 拿伯的田間。你當追想，你我一同坐車跟隨他父 亞哈的時候，耶和華對 亞哈所說的預言，', '雅比斯比他眾弟兄更尊貴，他母親給他起名叫 雅比斯，意思說：我生他甚是痛苦。', '我豈沒有吩咐你嗎？你當剛強壯膽！不要懼怕，也不要驚惶；因為你無論往哪裏去，耶和華－你的上帝必與你同在。」', 0, '正確內容記載於 撒母耳記上 14:48。', '撒母耳記上 14:48', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-14_2-1', '14-2', '撒母耳記上(二)16~31 章', '1SA', '撒母耳記上', '舊約', 'history', 16, 31, '經文辨識', '根據《撒母耳記上(二)16~31 章》的內容，以下哪一句經文出自這個範圍？', '有人告訴 耶利哥王說：「今夜有 以色列人來到這裏窺探此地。」', '大衛說：「好！我與你立約。但有一件，你來見我面的時候，若不將 掃羅的女兒 米甲帶來，必不得見我的面。」', '王對 亞勞拿說：「不然。我必要按着價值向你買；我不肯用白得之物作燔祭獻給耶和華－我的上帝。」 大衛就用五十舍客勒銀子買了那禾場與牛。', '大衛早晨起來，將羊交託一個看守的人，照着他父親所吩咐的話，帶着食物去了。到了輜重營，軍兵剛出到戰場，吶喊要戰。', 3, '正確內容記載於 撒母耳記上 17:20。', '撒母耳記上 17:20', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-14_2-2', '14-2', '撒母耳記上(二)16~31 章', '1SA', '撒母耳記上', '舊約', 'history', 16, 31, '出處辨識', '「掃羅對 米甲說：「你為甚麼這樣欺哄我，放我仇敵逃走呢？」 米甲回答說：「他對我說：『你放我走，不然我要…」的經文出處是哪裡？', '撒母耳記上 19:17', '撒母耳記上 26:16', '撒母耳記上 21:14', '撒母耳記上 29:5', 0, '正確內容記載於 撒母耳記上 19:17。', '撒母耳記上 19:17', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-14_2-3', '14-2', '撒母耳記上(二)16~31 章', '1SA', '撒母耳記上', '舊約', 'history', 16, 31, '經文辨識', '根據《撒母耳記上(二)16~31 章》的內容，以下哪一句經文出自這個範圍？', '次子 基利押是作過 迦密人 拿八的妻 亞比該所生的；三子 押沙龍是 基述王 達買的女兒 瑪迦所生的；', '海周圍有野瓜的樣式，每肘十瓜，共有兩行，是鑄海的時候鑄上的；', '大衛對 亞比亞他說：「那日我見 以東人 多益在那裏，就知道他必告訴 掃羅。你父的全家 喪命，都是因我的緣故。', '基大利向他們和屬他們的人起誓說：「你們不必懼怕 迦勒底臣僕，只管住在這地服事 巴比倫王，就可以得福。」', 2, '正確內容記載於 撒母耳記上 22:22。', '撒母耳記上 22:22', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-14_2-4', '14-2', '撒母耳記上(二)16~31 章', '1SA', '撒母耳記上', '舊約', 'history', 16, 31, '出處辨識', '「我指着阻止我加害於你的耶和華－ 以色列永生的上帝起誓，你若不速速地來迎接我，到明日早晨，凡屬 拿八的男…」的經文出處是哪裡？', '撒母耳記上 25:34', '撒母耳記上 25:42', '撒母耳記上 22:2', '撒母耳記上 16:8', 0, '正確內容記載於 撒母耳記上 25:34。', '撒母耳記上 25:34', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-14_2-5', '14-2', '撒母耳記上(二)16~31 章', '1SA', '撒母耳記上', '舊約', 'history', 16, 31, '經文辨識', '根據《撒母耳記上(二)16~31 章》的內容，以下哪一句經文出自這個範圍？', '從前 謝拉的曾孫 亞干豈不是在那當滅的物上犯了罪，就有忿怒臨到 以色列全會眾嗎？那人在所犯的罪中不獨一人死亡。」', '以色列人在田間和曠野殺盡所追趕一切 艾城的居民。 艾城人倒在刀下，直到滅盡； 以色列眾人就回到 艾城，用刀殺了城中的人。', '然而，因你父親 大衛的緣故，我不在你活着的日子行這事，必從你兒子的手中將國奪回。', '擄了城內的婦女和其中的大小人口，卻沒有殺一個，都帶着走了。', 3, '正確內容記載於 撒母耳記上 30:2。', '撒母耳記上 30:2', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-15_1-1', '15-1', '撒母耳記下(一)1~12 章', '2SA', '撒母耳記下', '舊約', 'history', 1, 12, '經文辨識', '根據《撒母耳記下(一)1~12 章》的內容，以下哪一句經文出自這個範圍？', '西布倫人是拚命敢死的； 拿弗他利人在田野的高處也是如此。', '以色列人又轉身回來， 便雅憫人就甚驚惶，因為看見災禍臨到自己了。', '以斯帖說：「王若以為美，就請王帶着 哈曼今日赴我所預備的筵席。」', '大衛也將跟隨他的人和他們各人的眷屬一同帶上去，住在 希伯崙的城邑中。', 3, '正確內容記載於 撒母耳記下 2:3。', '撒母耳記下 2:3', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-15_1-2', '15-1', '撒母耳記下(一)1~12 章', '2SA', '撒母耳記下', '舊約', 'history', 1, 12, '出處辨識', '「約押和他兄弟 亞比篩殺了 押尼珥，是因 押尼珥在 基遍爭戰的時候殺了他們的兄弟 亞撒黑。」的經文出處是哪裡？', '撒母耳記下 3:30', '撒母耳記下 1:2', '撒母耳記下 10:17', '撒母耳記下 5:5', 0, '正確內容記載於 撒母耳記下 3:30。', '撒母耳記下 3:30', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-15_1-3', '15-1', '撒母耳記下(一)1~12 章', '2SA', '撒母耳記下', '舊約', 'history', 1, 12, '經文辨識', '根據《撒母耳記下(一)1~12 章》的內容，以下哪一句經文出自這個範圍？', '現在你們是被咒詛的！你們中間的人必斷不了作奴僕，為我上帝的殿作劈柴挑水的人。」', '抬耶和華 約櫃的人走了六步， 大衛就獻牛與肥羊為祭。', '「我－ 亞達薛西王又降旨與 河西的一切庫官，說：『通達天上上帝律法的文士祭司 以斯拉，無論向你們要甚麼，你們要速速地備辦，', '羅波安來到 耶路撒冷，招聚 猶大全家和 便雅憫支派的人共十八萬，都是挑選的戰士，要與 以色列家爭戰，好將國奪回，再歸 所羅門的兒子 羅波安。', 1, '正確內容記載於 撒母耳記下 6:13。', '撒母耳記下 6:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-15_1-4', '15-1', '撒母耳記下(一)1~12 章', '2SA', '撒母耳記下', '舊約', 'history', 1, 12, '出處辨識', '「大衛問說：「 掃羅家還有剩下的人沒有？我要因 約拿單的緣故向他施恩。」的經文出處是哪裡？', '撒母耳記下 6:8', '撒母耳記下 1:24', '撒母耳記下 9:1', '撒母耳記下 5:14', 2, '正確內容記載於 撒母耳記下 9:1。', '撒母耳記下 9:1', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-15_1-5', '15-1', '撒母耳記下(一)1~12 章', '2SA', '撒母耳記下', '舊約', 'history', 1, 12, '經文辨識', '根據《撒母耳記下(一)1~12 章》的內容，以下哪一句經文出自這個範圍？', '婦人說：「願王記念耶和華－你的上帝，不許報血仇的人施行滅絕，恐怕他們滅絕我的兒子。」王說：「我指着永生的耶和華起誓：你的兒子連一根頭髮也不致落在地上。」', '王就吩咐 哈薛說：「你帶着禮物去見神人，託他求問耶和華，我這病能好不能好？」', '惟有金子、銀子，和銅鐵的器皿都要歸耶和華為聖，必入耶和華的庫中。」', '哀哭的日子過了， 大衛差人將她接到宮裏，她就作了 大衛的妻，給 大衛生了一個兒子。但 大衛所行的這事，耶和華甚不喜悅。', 3, '正確內容記載於 撒母耳記下 11:27。', '撒母耳記下 11:27', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-15_2-1', '15-2', '撒母耳記下(二)13~24 章', '2SA', '撒母耳記下', '舊約', 'history', 13, 24, '經文辨識', '根據《撒母耳記下(二)13~24 章》的內容，以下哪一句經文出自這個範圍？', '進去見王，對王如此如此說。」於是 約押將當說的話教導了婦人。', '又從 呂便支派的地業中給了他們 比悉和屬城的郊野， 雅雜和屬城的郊野，', '妾行淫離開丈夫，回 猶大的 伯利恆，到了父家，在那裏住了四個月。', '以色列眾人必為他哀哭，將他葬埋。凡屬 耶羅波安的人，惟有他得入墳墓；因為在 耶羅波安的家中，只有他向耶和華－ 以色列的上帝顯出善行。', 0, '正確內容記載於 撒母耳記下 14:3。', '撒母耳記下 14:3', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-15_2-2', '15-2', '撒母耳記下(二)13~24 章', '2SA', '撒母耳記下', '舊約', 'history', 13, 24, '出處辨識', '「於是 大衛和跟隨他的人往前行走。 示每在 大衛對面山坡，一面行走一面咒罵，又拿石頭砍他，拿土揚他。」的經文出處是哪裡？', '撒母耳記下 13:31', '撒母耳記下 16:13', '撒母耳記下 14:15', '撒母耳記下 24:2', 1, '正確內容記載於 撒母耳記下 16:13。', '撒母耳記下 16:13', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-15_2-3', '15-2', '撒母耳記下(二)13~24 章', '2SA', '撒母耳記下', '舊約', 'history', 13, 24, '經文辨識', '根據《撒母耳記下(二)13~24 章》的內容，以下哪一句經文出自這個範圍？', '還有 米拉利族的人在 西布倫支派的地中得了 臨摩挪與其郊野， 他泊與其郊野；', '就求告耶和華說：「耶和華－我的上帝啊，我寄居在這寡婦的家裏，你就降禍與她，使她的兒子死了嗎？」', '現在你當出去，安慰你僕人的心。我指着耶和華起誓：你若不出去，今夜必無一人與你同在一處；這禍患就比你從幼年到如今所遭的更甚！」', '約雅敬登基的時候年二十五歲，在 耶路撒冷作王十一年。他母親名叫 西布大，是 魯瑪人 毗大雅的女兒。', 2, '正確內容記載於 撒母耳記下 19:7。', '撒母耳記下 19:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-15_2-4', '15-2', '撒母耳記下(二)13~24 章', '2SA', '撒母耳記下', '舊約', 'history', 13, 24, '出處辨識', '「但 洗魯雅的兒子 亞比篩幫助 大衛，攻打 非利士人，將他殺死。當日，跟隨 大衛的人向 大衛起誓說：「以…」的經文出處是哪裡？', '撒母耳記下 14:24', '撒母耳記下 22:49', '撒母耳記下 13:5', '撒母耳記下 21:17', 3, '正確內容記載於 撒母耳記下 21:17。', '撒母耳記下 21:17', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-15_2-5', '15-2', '撒母耳記下(二)13~24 章', '2SA', '撒母耳記下', '舊約', 'history', 13, 24, '經文辨識', '根據《撒母耳記下(二)13~24 章》的內容，以下哪一句經文出自這個範圍？', '哈律人 沙瑪， 哈律人 以利加，', '大衛對 以色列全會眾說：「你們若以為美，見這事是出於耶和華－我們的上帝，我們就差遣人走遍 以色列地，見我們未來的弟兄，又見住在有郊野之城的祭司 利未人…', '婆婆問她說：「你今日在哪裏拾取麥穗，在哪裏做工呢？願那顧恤你的得福。」 路得就告訴婆婆說：「我今日在一個名叫 波阿斯的人那裏做工。」', '不要聽 希西家的話！因 亞述王如此說：『你們要與我和好，出來投降我，各人就可以吃自己葡萄樹和無花果樹的果子，喝自己井裏的水。', 0, '正確內容記載於 撒母耳記下 23:25。', '撒母耳記下 23:25', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-16_1-1', '16-1', '羅馬書 1~8 章', 'ROM', '羅馬書', '新約', 'pauline', 1, 8, '經文辨識', '根據《羅馬書 1~8 章》的內容，以下哪一句經文出自這個範圍？', '將不能朽壞之上帝的榮耀變為偶像，彷彿必朽壞的人和飛禽、走獸、昆蟲的樣式。', '為我弟兄，我骨肉之親，就是自己被咒詛，與基督分離，我也願意。', '你們死在過犯罪惡之中， 他叫你們活過來。', '我因多次被攔阻，總不得到你們那裏去。', 0, '正確內容記載於 羅馬書 1:23。', '羅馬書 1:23', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-16_1-2', '16-1', '羅馬書 1~8 章', 'ROM', '羅馬書', '新約', 'pauline', 1, 8, '出處辨識', '「若上帝的真實，因我的虛謊越發顯出他的榮耀，為甚麼我還受審判，好像罪人呢？」的經文出處是哪裡？', '羅馬書 2:17', '羅馬書 3:7', '羅馬書 5:12', '羅馬書 6:22', 1, '正確內容記載於 羅馬書 3:7。', '羅馬書 3:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-16_1-3', '16-1', '羅馬書 1~8 章', 'ROM', '羅馬書', '新約', 'pauline', 1, 8, '經文辨識', '根據《羅馬書 1~8 章》的內容，以下哪一句經文出自這個範圍？', '所以，你們當用這些話彼此勸慰。', '你們中間有彼此相爭的事，怎敢在不義的人面前求審，不在聖徒面前求審呢？', '也是為我們將來得算為義之人寫的，就是我們這信上帝使我們的主耶穌從死裏復活的人。', '愛人不可虛假。惡，要厭惡；善，要親近。', 2, '正確內容記載於 羅馬書 4:24。', '羅馬書 4:24', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-16_1-4', '16-1', '羅馬書 1~8 章', 'ROM', '羅馬書', '新約', 'pauline', 1, 8, '出處辨識', '「因為罪的工價乃是死；惟有上帝的恩賜，在我們的主基督耶穌裏，乃是永生。」的經文出處是哪裡？', '羅馬書 1:27', '羅馬書 1:4', '羅馬書 7:13', '羅馬書 6:23', 3, '正確內容記載於 羅馬書 6:23。', '羅馬書 6:23', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-16_1-5', '16-1', '羅馬書 1~8 章', 'ROM', '羅馬書', '新約', 'pauline', 1, 8, '經文辨識', '根據《羅馬書 1~8 章》的內容，以下哪一句經文出自這個範圍？', '我想，現在的苦楚若比起將來要顯於我們的榮耀就不足介意了。', '但我說，人沒有聽見嗎？誠然聽見了。 他們的聲音傳遍天下； 他們的言語傳到地極。', '這 夏甲二字是指着 阿拉伯的 西奈山，與現在的 耶路撒冷同類，因 耶路撒冷和她的兒女都是為奴的。', '然而照主的安排，女也不是無男，男也不是無女。', 0, '正確內容記載於 羅馬書 8:18。', '羅馬書 8:18', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-16_2-1', '16-2', '羅馬書 9~16 章', 'ROM', '羅馬書', '新約', 'pauline', 9, 16, '經文辨識', '根據《羅馬書 9~16 章》的內容，以下哪一句經文出自這個範圍？', '這福音是上帝從前藉眾先知在聖經上所應許的，', '窯匠難道沒有權柄從一團泥裏拿一塊做成貴重的器皿，又拿一塊做成卑賤的器皿嗎？', '我原是使徒中最小的，不配稱為使徒，因為我從前逼迫上帝的教會。', '弟兄們，你們記念我們的辛苦勞碌，晝夜做工，傳上帝的福音給你們，免得叫你們一人受累。', 1, '正確內容記載於 羅馬書 9:21。', '羅馬書 9:21', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-16_2-2', '16-2', '羅馬書 9~16 章', 'ROM', '羅馬書', '新約', 'pauline', 9, 16, '出處辨識', '「大衛也說： 願他們的筵席變為網羅，變為機檻， 變為絆腳石，作他們的報應。」的經文出處是哪裡？', '羅馬書 11:31', '羅馬書 12:9', '羅馬書 11:9', '羅馬書 9:23', 2, '正確內容記載於 羅馬書 11:9。', '羅馬書 11:9', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-16_2-3', '16-2', '羅馬書 9~16 章', 'ROM', '羅馬書', '新約', 'pauline', 9, 16, '經文辨識', '根據《羅馬書 9~16 章》的內容，以下哪一句經文出自這個範圍？', '所以我們看定了：人稱義是因着信，不在乎遵行律法。', '你該知道，末世必有危險的日子來到。', '與眾弟兄親嘴問安，務要聖潔。', '逼迫你們的，要給他們祝福；只要祝福，不可咒詛。', 3, '正確內容記載於 羅馬書 12:14。', '羅馬書 12:14', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-16_2-4', '16-2', '羅馬書 9~16 章', 'ROM', '羅馬書', '新約', 'pauline', 9, 16, '出處辨識', '「無論是吃肉是喝酒，是甚麼別的事，叫弟兄跌倒，一概不做才好。」的經文出處是哪裡？', '羅馬書 14:21', '羅馬書 10:2', '羅馬書 15:18', '羅馬書 9:3', 0, '正確內容記載於 羅馬書 14:21。', '羅馬書 14:21', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-16_2-5', '16-2', '羅馬書 9~16 章', 'ROM', '羅馬書', '新約', 'pauline', 9, 16, '經文辨識', '根據《羅馬書 9~16 章》的內容，以下哪一句經文出自這個範圍？', '他將近百歲的時候，雖然想到自己的身體如同已死， 撒拉的生育已經斷絕，他的信心還是不軟弱；', '又問我親屬與我一同坐監的 安多尼古和 猶尼亞安；他們在使徒中是有名望的，也是比我先在基督裏。', '原來，上帝的忿怒從天上顯明在一切不虔不義的人身上，就是那些行不義阻擋真理的人。', '所以，上帝將他升為至高， 又賜給他那超乎萬名之上的名，', 1, '正確內容記載於 羅馬書 16:7。', '羅馬書 16:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-17_1-1', '17-1', '列王紀上', '1KI', '列王紀上', '舊約', 'history', 1, 22, '經文辨識', '根據《列王紀上》的內容，以下哪一句經文出自這個範圍？', '於是 以色列王 約阿施上來，在 猶大的 伯‧示麥與 猶大王 亞瑪謝相見 於戰場。', '有人告訴 所羅門王說：「 約押逃到耶和華的帳幕，現今在祭壇的旁邊。」 所羅門就差遣 耶何耶大的兒子 比拿雅，說：「你去將他殺死。」', '耶和華的使者向 以色列眾人說這話的時候，百姓就放聲而哭；', '只是你們和約櫃相離要量二千肘，不可與約櫃相近，使你們知道所當走的路，因為這條路你們向來沒有走過。」', 1, '正確內容記載於 列王紀上 2:29。', '列王紀上 2:29', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-17_1-2', '17-1', '列王紀上', '1KI', '列王紀上', '舊約', 'history', 1, 22, '出處辨識', '「四個輪子在心子以下，輪軸與座相連，每輪高一肘半。」的經文出處是哪裡？', '列王紀上 7:32', '列王紀上 1:27', '列王紀上 9:7', '列王紀上 16:15', 0, '正確內容記載於 列王紀上 7:32。', '列王紀上 7:32', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-17_1-3', '17-1', '列王紀上', '1KI', '列王紀上', '舊約', 'history', 1, 22, '經文辨識', '根據《列王紀上》的內容，以下哪一句經文出自這個範圍？', '他們若在擄到之地盡心盡性歸服你，又向自己的地，就是你賜給他們列祖之地和你所選擇的城，並我為你名所建造的殿禱告，', '這樣，在 耶路撒冷大有喜樂，自從 以色列王 大衛兒子 所羅門的時候，在 耶路撒冷沒有這樣的喜樂。', '你平生的日子，必無一人能在你面前站立得住。我怎樣與 摩西同在，也必照樣與你同在；我必不撇下你，也不丟棄你。', '哈達在 埃及聽見 大衛與他列祖同睡，元帥 約押也死了，就對法老說：「求王容我回本國去。」', 3, '正確內容記載於 列王紀上 11:21。', '列王紀上 11:21', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-17_1-4', '17-1', '列王紀上', '1KI', '列王紀上', '舊約', 'history', 1, 22, '出處辨識', '「耶和華的話臨到 哈拿尼的兒子先知 耶戶，責備 巴沙和他的家，因他行耶和華眼中看為惡的一切事，以他手所做…」的經文出處是哪裡？', '列王紀上 16:7', '列王紀上 18:41', '列王紀上 15:25', '列王紀上 1:27', 0, '正確內容記載於 列王紀上 16:7。', '列王紀上 16:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-17_1-5', '17-1', '列王紀上', '1KI', '列王紀上', '舊約', 'history', 1, 22, '經文辨識', '根據《列王紀上》的內容，以下哪一句經文出自這個範圍？', '因為那些人帶着牲畜帳棚來，像蝗蟲那樣多，人和駱駝無數，都進入國內，毀壞全地。', '這事以後，又有一事。 耶斯列人 拿伯在 耶斯列有一個葡萄園，靠近 撒馬利亞王 亞哈的宮。', '西布倫沒有趕出 基倫的居民和 拿哈拉的居民。於是 迦南人仍住在 西布倫中間，成了服苦的人。', '亞設的兒子是 音拿、 亦施瓦、 亦施韋、 比利亞，還有他們的妹子 西拉。', 1, '正確內容記載於 列王紀上 21:1。', '列王紀上 21:1', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-17_2-1', '17-2', '列王紀下', '2KI', '列王紀下', '舊約', 'history', 1, 25, '經文辨識', '根據《列王紀下》的內容，以下哪一句經文出自這個範圍？', '以利沙問她說：「我可以為你做甚麼呢？你告訴我，你家裏有甚麼？」她說：「婢女家中除了一瓶油之外，沒有甚麼。」', '瑪挪亞對耶和華的使者說：「求你容我們款留你，好為你預備一隻山羊羔。」', '掃羅對僕人說：「我們若去，有甚麼可以送那人呢？我們囊中的食物都吃盡了，也沒有禮物可以送那神人，我們還有甚麼沒有？」', '約書亞和 以色列人在 約旦河西擊殺了諸王。他們的地是從 黎巴嫩平原的 巴力‧迦得，直到上 西珥的 哈拉山。 約書亞就將那地按着 以色列支派的宗族分給他…', 0, '正確內容記載於 列王紀下 4:2。', '列王紀下 4:2', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-17_2-2', '17-2', '列王紀下', '2KI', '列王紀下', '舊約', 'history', 1, 25, '出處辨識', '「這樣， 以東人背叛 猶大，脫離他的權下，直到今日。那時 立拿人也背叛了。」的經文出處是哪裡？', '列王紀下 16:9', '列王紀下 10:32', '列王紀下 6:23', '列王紀下 8:22', 3, '正確內容記載於 列王紀下 8:22。', '列王紀下 8:22', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-17_2-3', '17-2', '列王紀下', '2KI', '列王紀下', '舊約', 'history', 1, 25, '經文辨識', '根據《列王紀下》的內容，以下哪一句經文出自這個範圍？', '耶和華卻因與 亞伯拉罕、 以撒、 雅各所立的約，仍施恩給 以色列人，憐恤他們，眷顧他們，不肯滅盡他們，尚未趕逐他們離開自己面前。', '大利拉對 參孫說：「求你告訴我，你因何有這麼大的力氣，當用何法捆綁剋制你。」', '約書亞就終夜從 吉甲上去，猛然臨到他們那裏。', '亞施他拉人 烏西亞， 亞羅珥人 何坦的兒子 沙瑪、 耶利，', 0, '正確內容記載於 列王紀下 13:23。', '列王紀下 13:23', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-17_2-4', '17-2', '列王紀下', '2KI', '列王紀下', '舊約', 'history', 1, 25, '出處辨識', '「希西家王十四年， 亞述王 西拿基立上來攻擊 猶大的一切堅固城，將城攻取。」的經文出處是哪裡？', '列王紀下 14:2', '列王紀下 18:13', '列王紀下 6:29', '列王紀下 4:42', 1, '正確內容記載於 列王紀下 18:13。', '列王紀下 18:13', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-17_2-5', '17-2', '列王紀下', '2KI', '列王紀下', '舊約', 'history', 1, 25, '經文辨識', '根據《列王紀下》的內容，以下哪一句經文出自這個範圍？', '約西亞回頭，看見山上的墳墓，就打發人將墳墓裏的骸骨取出來，燒在壇上，污穢了壇，正如從前神人宣傳耶和華的話。', '雅比斯比他眾弟兄更尊貴，他母親給他起名叫 雅比斯，意思說：我生他甚是痛苦。', '尼陀法人 瑪哈萊， 尼陀法人 巴拿的兒子 希立，', '第五是 瑪基雅，第六是 米雅民，', 0, '正確內容記載於 列王紀下 23:16。', '列王紀下 23:16', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-18_1-1', '18-1', '哥林多前書(一)1~8 章', '1CO', '哥林多前書', '新約', 'pauline', 1, 8, '經文辨識', '根據《哥林多前書(一)1~8 章》的內容，以下哪一句經文出自這個範圍？', '因為十字架的道理，在那滅亡的人為愚拙；在我們得救的人，卻為上帝的大能。', '原來在上帝面前，不是聽律法的為義，乃是行律法的稱義。', '所以，我不在你們那裏的時候，把這話寫給你們，好叫我見你們的時候，不用照主所給我的權柄嚴厲地待你們。這權柄原是為造就人，並不是為敗壞人。', '求我們主耶穌基督的上帝，榮耀的父，將那賜人智慧和啟示的靈賞給你們，使你們真知道他，', 0, '正確內容記載於 哥林多前書 1:18。', '哥林多前書 1:18', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-18_1-2', '18-1', '哥林多前書(一)1~8 章', '1CO', '哥林多前書', '新約', 'pauline', 1, 8, '出處辨識', '「我栽種了， 亞波羅澆灌了，惟有上帝叫他生長。」的經文出處是哪裡？', '哥林多前書 1:19', '哥林多前書 1:3', '哥林多前書 1:31', '哥林多前書 3:6', 3, '正確內容記載於 哥林多前書 3:6。', '哥林多前書 3:6', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-18_1-3', '18-1', '哥林多前書(一)1~8 章', '1CO', '哥林多前書', '新約', 'pauline', 1, 8, '經文辨識', '根據《哥林多前書(一)1~8 章》的內容，以下哪一句經文出自這個範圍？', '因為 經上記着： 不懷孕、不生養的，你要歡樂； 未曾經過產難的，你要高聲歡呼； 因為沒有丈夫的，比有丈夫的兒女更多。', '按聖善的靈說，因從死裏復活，以大能顯明是上帝的兒子。', '因為上帝的國不在乎言語，乃在乎權能。', '黑夜已深，白晝將近。我們就當脫去暗昧的行為，帶上光明的兵器。', 2, '正確內容記載於 哥林多前書 4:20。', '哥林多前書 4:20', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-18_1-4', '18-1', '哥林多前書(一)1~8 章', '1CO', '哥林多前書', '新約', 'pauline', 1, 8, '出處辨識', '「論到你們信上所提的事， 我說男不近女倒好。」的經文出處是哪裡？', '哥林多前書 3:8', '哥林多前書 7:1', '哥林多前書 1:7', '哥林多前書 3:2', 1, '正確內容記載於 哥林多前書 7:1。', '哥林多前書 7:1', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-18_1-5', '18-1', '哥林多前書(一)1~8 章', '1CO', '哥林多前書', '新約', 'pauline', 1, 8, '經文辨識', '根據《哥林多前書(一)1~8 章》的內容，以下哪一句經文出自這個範圍？', '若有人以為自己待他的女兒不合宜，女兒也過了年歲，事又當行，他就可隨意辦理，不算有罪，叫二人成親就是了。', '那行不義的必受不義的報應； 主並不偏待人。', '以及我在 安提阿、 以哥念、 路司得所遭遇的逼迫、苦難。我所忍受是何等的逼迫；但從這一切苦難中，主都把我救出來了。', '我不以福音為恥；這福音本是上帝的大能，要救一切相信的，先是 猶太人，後是 希臘人。', 0, '正確內容記載於 哥林多前書 7:36。', '哥林多前書 7:36', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-18_2-1', '18-2', '哥林多前書(二)9~16 章', '1CO', '哥林多前書', '新約', 'pauline', 9, 16, '經文辨識', '根據《哥林多前書(二)9~16 章》的內容，以下哪一句經文出自這個範圍？', '原來，上帝的忿怒從天上顯明在一切不虔不義的人身上，就是那些行不義阻擋真理的人。', '我們為基督的緣故算是愚拙的，你們在基督裏倒是聰明的；我們軟弱，你們倒強壯；你們有榮耀，我們倒被藐視。', '按聖善的靈說，因從死裏復活，以大能顯明是上帝的兒子。', '所以，我奔跑不像無定向的；我鬥拳不像打空氣的。', 3, '正確內容記載於 哥林多前書 9:26。', '哥林多前書 9:26', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-18_2-2', '18-2', '哥林多前書(二)9~16 章', '1CO', '哥林多前書', '新約', 'pauline', 9, 16, '出處辨識', '「我現今吩咐你們的話，不是稱讚你們；因為你們聚會不是受益，乃是招損。」的經文出處是哪裡？', '哥林多前書 9:3', '哥林多前書 11:2', '哥林多前書 11:17', '哥林多前書 14:8', 2, '正確內容記載於 哥林多前書 11:17。', '哥林多前書 11:17', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-18_2-3', '18-2', '哥林多前書(二)9~16 章', '1CO', '哥林多前書', '新約', 'pauline', 9, 16, '經文辨識', '根據《哥林多前書(二)9~16 章》的內容，以下哪一句經文出自這個範圍？', '但如今，在這裏再沒有 可傳的地方，而且這好幾年，我切心想望到 西班牙去的時候，可以到你們那裏，', '愛是恆久忍耐，又有恩慈；愛是不嫉妒；愛是不自誇，不張狂，', '免得有人說，你們是奉我的名受洗。', '求他按着他豐盛的榮耀，藉着他的靈，叫你們心裏的力量剛強起來，', 1, '正確內容記載於 哥林多前書 13:4。', '哥林多前書 13:4', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-18_2-4', '18-2', '哥林多前書(二)9~16 章', '1CO', '哥林多前書', '新約', 'pauline', 9, 16, '出處辨識', '「而且埋葬了；又照聖經所說，第三天復活了，」的經文出處是哪裡？', '哥林多前書 15:4', '哥林多前書 11:2', '哥林多前書 10:17', '哥林多前書 9:21', 0, '正確內容記載於 哥林多前書 15:4。', '哥林多前書 15:4', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-18_2-5', '18-2', '哥林多前書(二)9~16 章', '1CO', '哥林多前書', '新約', 'pauline', 9, 16, '經文辨識', '根據《哥林多前書(二)9~16 章》的內容，以下哪一句經文出自這個範圍？', '弟兄們，我們是憑着應許作兒女，如同 以撒一樣。', '預先所定下的人又召他們來；所召來的人又稱他們為義；所稱為義的人又叫他們得榮耀。', '這福音是上帝從前藉眾先知在聖經上所應許的，', '死的毒鉤就是罪，罪的權勢就是律法。', 3, '正確內容記載於 哥林多前書 15:56。', '哥林多前書 15:56', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-19-1', '19', '歷代志上', '1CH', '歷代志上', '舊約', 'history', 1, 29, '經文辨識', '根據《歷代志上》的內容，以下哪一句經文出自這個範圍？', '艾城的人擊殺了他們三十六人，從城門前追趕他們，直到 示巴琳，在下坡殺敗他們；眾民的心就消化如水。', '從前窺探 拉億地的五個人對他們的弟兄說：「這宅子裏有以弗得和家中的神像，並雕刻的像與鑄成的像，你們知道嗎？現在你們要想一想當怎樣行。」', '你們到了那裏，必看見安居無慮的民，地也寬闊。上帝已將那地交在你們手中；那地百物俱全，一無所缺。」', '希伯崙的兒子是 可拉、 他普亞、 利肯、 示瑪。', 3, '正確內容記載於 歷代志上 2:43。', '歷代志上 2:43', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-19-2', '19', '歷代志上', '1CH', '歷代志上', '舊約', 'history', 1, 29, '出處辨識', '「以薩迦的兒子是 陀拉、 普瓦、 雅述、 伸崙，共四人。」的經文出處是哪裡？', '歷代志上 4:32', '歷代志上 8:40', '歷代志上 7:1', '歷代志上 1:7', 2, '正確內容記載於 歷代志上 7:1。', '歷代志上 7:1', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-19-3', '19', '歷代志上', '1CH', '歷代志上', '舊約', 'history', 1, 29, '經文辨識', '根據《歷代志上》的內容，以下哪一句經文出自這個範圍？', '伯‧示麥人正在平原收割麥子，舉目看見 約櫃，就歡喜了。', '迦得支派中有人到曠野的山寨投奔 大衛，都是大能的勇士，能拿盾牌和槍的戰士。他們的面貌好像獅子，快跑如同山上的鹿。', '亞哈問 約沙法說：「你肯同我去攻取 基列的 拉末嗎？」 約沙法對 以色列王說：「你我不分彼此，我的民與你的民一樣，我的馬與你的馬一樣。」', '「你父親使我們負重軛 做苦工，現在求你使我們做的苦工負的重軛輕鬆些，我們就事奉你。」', 1, '正確內容記載於 歷代志上 12:8。', '歷代志上 12:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-19-4', '19', '歷代志上', '1CH', '歷代志上', '舊約', 'history', 1, 29, '出處辨識', '「亞捫人出來在城門前擺陣，所來的諸王另在郊野擺陣。」的經文出處是哪裡？', '歷代志上 19:9', '歷代志上 1:1', '歷代志上 11:7', '歷代志上 12:8', 0, '正確內容記載於 歷代志上 19:9。', '歷代志上 19:9', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-19-5', '19', '歷代志上', '1CH', '歷代志上', '舊約', 'history', 1, 29, '經文辨識', '根據《歷代志上》的內容，以下哪一句經文出自這個範圍？', '米示薩別、 撒督、 押杜亞、', '約書亞和 以色列眾人從 立拿往 拉吉去，對着 拉吉安營，攻打這城。', '他們回到 約書亞那裏，對他說：「眾民不必都上去，只要二三千人上去就能攻取 艾城；不必勞累眾民都去，因為那裏的人少。」', '這 示羅密和他的弟兄掌管府庫的聖物，就是 大衛王和眾族長、千夫長、百夫長，並軍長所分別為聖的物。', 3, '正確內容記載於 歷代志上 26:26。', '歷代志上 26:26', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-20-1', '20', '歷代志下', '2CH', '歷代志下', '舊約', 'history', 1, 36, '經文辨識', '根據《歷代志下》的內容，以下哪一句經文出自這個範圍？', '抬耶和華約櫃的祭司從 約旦河裏上來，腳掌剛落旱地， 約旦河的水就流到原處，仍舊漲過兩岸。', '約櫃裏惟有兩塊石版，就是 以色列人出 埃及後，耶和華與他們立約的時候， 摩西在 何烈山所放的。除此以外，並無別物。', '約押圍城的時候，知道敵人那裏有勇士，便將 烏利亞派在那裏。', '掃羅對 撒母耳說：「我有罪了，我因懼怕百姓，聽從他們的話，就違背了耶和華的命令和你的言語。', 1, '正確內容記載於 歷代志下 5:10。', '歷代志下 5:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-20-2', '20', '歷代志下', '2CH', '歷代志下', '舊約', 'history', 1, 36, '出處辨識', '「耶和華見他們自卑，耶和華的話就臨到 示瑪雅說：「他們既自卑，我必不滅絕他們；必使他們略得拯救，我不藉着…」的經文出處是哪裡？', '歷代志下 7:13', '歷代志下 5:12', '歷代志下 12:7', '歷代志下 25:16', 2, '正確內容記載於 歷代志下 12:7。', '歷代志下 12:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-20-3', '20', '歷代志下', '2CH', '歷代志下', '舊約', 'history', 1, 36, '經文辨識', '根據《歷代志下》的內容，以下哪一句經文出自這個範圍？', '我女兒們哪，回去吧！我年紀老邁，不能再有丈夫；即或說，我還有指望，今夜有丈夫可以生子，', '伊施波設懼怕 押尼珥，不敢回答一句。', '她對他們說：「你們且往山上去，恐怕追趕的人碰見你們；要在那裏隱藏三天，等追趕的人回來，然後才可以走你們的路。」', '次日清早，眾人起來往 提哥亞的曠野去。出去的時候， 約沙法站着說：「 猶大人和 耶路撒冷的居民哪，要聽我說：信耶和華－你們的上帝就必立穩；信他的先知就…', 3, '正確內容記載於 歷代志下 20:20。', '歷代志下 20:20', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-20-4', '20', '歷代志下', '2CH', '歷代志下', '舊約', 'history', 1, 36, '出處辨識', '「所以，耶和華－他的上帝將他交在 亞蘭王手裏。 亞蘭王打敗他，擄了他許多的民，帶到 大馬士革去。上帝又將…」的經文出處是哪裡？', '歷代志下 28:5', '歷代志下 1:4', '歷代志下 26:2', '歷代志下 20:14', 0, '正確內容記載於 歷代志下 28:5。', '歷代志下 28:5', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-20-5', '20', '歷代志下', '2CH', '歷代志下', '舊約', 'history', 1, 36, '經文辨識', '根據《歷代志下》的內容，以下哪一句經文出自這個範圍？', '心利這樣滅絕 巴沙的全家，正如耶和華藉先知 耶戶責備 巴沙的話。', '約押雖然沒有歸從 押沙龍，卻歸從了 亞多尼雅。他聽見這風聲，就逃到耶和華的帳幕，抓住祭壇的角。', '他行耶和華眼中看為正的事，效法他祖 大衛所行的，不偏左右。', '無論男女， 大衛沒有留下一個帶到 迦特來。他說：「恐怕他們將我們的事告訴人，說 大衛住在 非利士地的時候常常這樣行。」', 2, '正確內容記載於 歷代志下 34:2。', '歷代志下 34:2', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-21-1', '21', '哥林多後書', '2CO', '哥林多後書', '新約', 'pauline', 1, 13, '經文辨識', '根據《哥林多後書》的內容，以下哪一句經文出自這個範圍？', '應當一無掛慮，只要凡事藉着禱告、祈求，和感謝，將你們所要的告訴上帝。', '卻將榮耀、尊貴、平安加給一切行善的人，先是 猶太人，後是 希臘人。', '倘若我叫你們憂愁，除了我叫那憂愁的人以外，誰能叫我快樂呢？', '我只要問你們這一件：你們受了 聖靈，是因行律法呢？是因聽信 福音呢？', 2, '正確內容記載於 哥林多後書 2:2。', '哥林多後書 2:2', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-21-2', '21', '哥林多後書', '2CO', '哥林多後書', '新約', 'pauline', 1, 13, '出處辨識', '「原來我們不是顧念所見的，乃是顧念所不見的；因為所見的是暫時的，所不見的是永遠的。」的經文出處是哪裡？', '哥林多後書 5:20', '哥林多後書 1:9', '哥林多後書 1:7', '哥林多後書 4:18', 3, '正確內容記載於 哥林多後書 4:18。', '哥林多後書 4:18', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-21-3', '21', '哥林多後書', '2CO', '哥林多後書', '新約', 'pauline', 1, 13, '經文辨識', '根據《哥林多後書》的內容，以下哪一句經文出自這個範圍？', '我雖然從前寫信給你們，卻不是為那虧負人的，也不是為那受人虧負的，乃要在上帝面前把你們顧念我們的熱心表明出來。', '就是我在 帖撒羅尼迦，你們也一次兩次地打發人供給我的需用。', '他們既然故意不認識上帝，上帝就任憑他們存邪僻的心，行那些不合理的事；', '智慧人在哪裏？文士在哪裏？這世上的辯士在哪裏？上帝豈不是叫這世上的智慧變成愚拙嗎？', 0, '正確內容記載於 哥林多後書 7:12。', '哥林多後書 7:12', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-21-4', '21', '哥林多後書', '2CO', '哥林多後書', '新約', 'pauline', 1, 13, '出處辨識', '「主賜給我們權柄，是要造就你們，並不是要敗壞你們；我就是為這權柄稍微誇口，也不至於慚愧。」的經文出處是哪裡？', '哥林多後書 1:9', '哥林多後書 1:23', '哥林多後書 10:8', '哥林多後書 1:13', 2, '正確內容記載於 哥林多後書 10:8。', '哥林多後書 10:8', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-21-5', '21', '哥林多後書', '2CO', '哥林多後書', '新約', 'pauline', 1, 13, '經文辨識', '根據《哥林多後書》的內容，以下哪一句經文出自這個範圍？', '他對我說：「我的恩典夠你用的，因為我的能力是在人的軟弱上顯得完全。」所以，我更喜歡誇自己的軟弱，好叫基督的能力覆庇我。', '栽種的和澆灌的，都是一樣，但將來各人要照自己的工夫得自己的賞賜。', '但我要仍舊住在 以弗所，直等到五旬節；', '（我為這福音的奧祕作了帶鎖鍊的使者，）並使我照着當盡的本分放膽講論。', 0, '正確內容記載於 哥林多後書 12:9。', '哥林多後書 12:9', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-22_1-1', '22-1', '以斯拉記', 'EZR', '以斯拉記', '舊約', 'history', 1, 10, '經文辨識', '根據《以斯拉記》的內容，以下哪一句經文出自這個範圍？', '拿單的兄弟 約珥， 哈基利的兒子 彌伯哈，', '所以其中的居民力量甚小， 驚惶羞愧。 他們像野草，像青菜， 如房頂上的草， 又如未長成而枯乾的禾稼。', '於是 參孫去捉了三百隻狐狸，將狐狸尾巴一對一對地捆上，將火把捆在兩條尾巴中間，', '羅德人、 哈第人、 阿挪人共七百二十五名；', 3, '正確內容記載於 以斯拉記 2:33。', '以斯拉記 2:33', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-22_1-2', '22-1', '以斯拉記', 'EZR', '以斯拉記', '舊約', 'history', 1, 10, '出處辨識', '「那地的民，就在 猶大人建造的時候，使他們的手發軟，擾亂他們；」的經文出處是哪裡？', '以斯拉記 3:7', '以斯拉記 2:58', '以斯拉記 4:4', '以斯拉記 5:13', 2, '正確內容記載於 以斯拉記 4:4。', '以斯拉記 4:4', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-22_1-3', '22-1', '以斯拉記', 'EZR', '以斯拉記', '舊約', 'history', 1, 10, '經文辨識', '根據《以斯拉記》的內容，以下哪一句經文出自這個範圍？', '那先知來見 以色列王，對他說：「你當自強，留心怎樣防備；因為到明年這時候， 亞蘭王必上來攻擊你。」', '猶大長老因先知 哈該和 易多的孫子 撒迦利亞所說勸勉的話就建造這殿，凡事亨通。他們遵着 以色列上帝的命令和 波斯王 塞魯士、 大流士、 亞達薛西的旨意…', '基甸從那裏上到 毗努伊勒，對那裏的人也是這樣說； 毗努伊勒人也與 疏割人回答他的話一樣。', '今日你親眼看見在洞中，耶和華將你交在我手裏；有人叫我殺你，我卻愛惜你，說：『我不敢伸手害我的主，因為他是耶和華的受膏者。』', 1, '正確內容記載於 以斯拉記 6:14。', '以斯拉記 6:14', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-22_1-4', '22-1', '以斯拉記', 'EZR', '以斯拉記', '舊約', 'history', 1, 10, '出處辨識', '「我招聚這些人在流入 亞哈瓦的河邊，我們在那裏住了三日。我查看百姓和祭司，見沒有 利未人在那裏，」的經文出處是哪裡？', '以斯拉記 8:15', '以斯拉記 4:1', '以斯拉記 6:8', '以斯拉記 2:26', 0, '正確內容記載於 以斯拉記 8:15。', '以斯拉記 8:15', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-22_1-5', '22-1', '以斯拉記', 'EZR', '以斯拉記', '舊約', 'history', 1, 10, '經文辨識', '根據《以斯拉記》的內容，以下哪一句經文出自這個範圍？', '以笏之後，有 亞拿的兒子 珊迦，他用趕牛的棍子打死六百 非利士人。他也救了 以色列人。', '和四百石榴，安在兩個網子上（每網兩行蓋着兩個柱上如球的頂）。', '暗利行耶和華眼中看為惡的事，比他以前的列王作惡更甚。', '不如為全會眾派首領辦理。凡我們城邑中娶外邦女子為妻的，當按所定的日期，同着本城的長老和士師而來，直到辦完這事，上帝的烈怒就轉離我們了。」', 3, '正確內容記載於 以斯拉記 10:14。', '以斯拉記 10:14', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-22_2-1', '22-2', '尼希米記', 'NEH', '尼希米記', '舊約', 'history', 1, 13, '經文辨識', '根據《尼希米記》的內容，以下哪一句經文出自這個範圍？', '他的眾母舅便將這一切話為他說給 示劍人聽， 示劍人的心就歸向 亞比米勒。他們說：「他原是我們的弟兄」；', '約押對報信的人說：「你既看見他，為甚麼不將他打死落在地上呢？ 你若打死他，我就賞你十 舍客勒銀子，一條帶子。」', '巴西亞的兒子 耶何耶大與 比所玳的兒子 米書蘭修造 古門，架橫樑，安門扇和閂鎖。', '大衛對祭司說：「實在約有三日我們沒有親近婦人；我出來的時候，雖是尋常行路，少年人的器皿還是潔淨的；何況今日不更是潔淨嗎？」', 2, '正確內容記載於 尼希米記 3:6。', '尼希米記 3:6', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-22_2-2', '22-2', '尼希米記', 'NEH', '尼希米記', '舊約', 'history', 1, 13, '出處辨識', '「參巴拉第五次打發僕人來見我，手裏拿着未封的信，」的經文出處是哪裡？', '尼希米記 3:27', '尼希米記 6:5', '尼希米記 7:45', '尼希米記 13:5', 1, '正確內容記載於 尼希米記 6:5。', '尼希米記 6:5', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-22_2-3', '22-2', '尼希米記', 'NEH', '尼希米記', '舊約', 'history', 1, 13, '經文辨識', '根據《尼希米記》的內容，以下哪一句經文出自這個範圍？', '文士 以斯拉站在為這事特備的木臺上。 瑪他提雅、 示瑪、 亞奈雅、 烏利亞、 希勒家，和 瑪西雅站在他的右邊； 毗大雅、 米沙利、 瑪基雅、 哈順、 …', '是 但 支派一個婦人的兒子。他父親是 泰爾人，他善用金、銀、銅、鐵、石、木，和紫色、藍色、朱紅色 線與細麻製造各物，並精於雕刻，又能想出各樣的巧工。請…', '就都聚集，同心合意地要與 約書亞和 以色列人爭戰。', '末底改叔叔 亞比孩的女兒，就是 末底改收為自己女兒的 以斯帖，按次序當進去見王的時候，除了掌管女子的太監 希該所派定給她的，她別無所求。凡看見 以斯帖…', 0, '正確內容記載於 尼希米記 8:4。', '尼希米記 8:4', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-22_2-4', '22-2', '尼希米記', 'NEH', '尼希米記', '舊約', 'history', 1, 13, '出處辨識', '「又定每年將我們地上初熟的土產和各樣樹上初熟的果子都奉到耶和華的殿裏。」的經文出處是哪裡？', '尼希米記 2:16', '尼希米記 13:8', '尼希米記 9:4', '尼希米記 10:35', 3, '正確內容記載於 尼希米記 10:35。', '尼希米記 10:35', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-22_2-5', '22-2', '尼希米記', 'NEH', '尼希米記', '舊約', 'history', 1, 13, '經文辨識', '根據《尼希米記》的內容，以下哪一句經文出自這個範圍？', '那日，眾人獻大祭而歡樂；因為上帝使他們大大歡樂，連婦女帶孩童也都歡樂，甚至 耶路撒冷中的歡聲聽到遠處。', '婦人急忙將家裏的一隻肥牛犢宰了，又拿麵摶成無酵餅烤了，', '七月第七班的班長是 以法蓮族 比倫人 希利斯；他班內有二萬四千人。', '非利士人聚集，來到 書念安營； 掃羅聚集 以色列眾人在 基利波安營。', 0, '正確內容記載於 尼希米記 12:43。', '尼希米記 12:43', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-23_1-1', '23-1', '以斯帖記', 'EST', '以斯帖記', '舊約', 'history', 1, 10, '經文辨識', '根據《以斯帖記》的內容，以下哪一句經文出自這個範圍？', '今日 波斯和 米底亞的眾夫人聽見王后這事，必向王的大臣 照樣行；從此必大開藐視和忿怒之端。', '我聽見這話，就坐下哭泣，悲哀幾日，在天上的上帝面前禁食祈禱，說：', '約旦河東的 呂便支派、 迦得支派、 瑪拿西半支派，拿着各樣兵器打仗的有十二萬人。', '大殿 的牆都用松木板遮蔽，又貼了精金，上面雕刻棕樹和鍊子；', 0, '正確內容記載於 以斯帖記 1:18。', '以斯帖記 1:18', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-23_1-2', '23-1', '以斯帖記', 'EST', '以斯帖記', '舊約', 'history', 1, 10, '出處辨識', '「他們已將 末底改的本族告訴 哈曼；他以為下手害 末底改一人是小事，就要滅絕 亞哈隨魯王通國所有的 猶大…」的經文出處是哪裡？', '以斯帖記 9:20', '以斯帖記 8:2', '以斯帖記 3:6', '以斯帖記 10:1', 2, '正確內容記載於 以斯帖記 3:6。', '以斯帖記 3:6', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-23_1-3', '23-1', '以斯帖記', 'EST', '以斯帖記', '舊約', 'history', 1, 10, '經文辨識', '根據《以斯帖記》的內容，以下哪一句經文出自這個範圍？', '以斯帖回答說：「我有所要，我有所求。', '那人名叫 拿八，是 迦勒族的人；他的妻名叫 亞比該，是聰明俊美的婦人。 拿八為人剛愎凶惡。', '非利士人將上帝的 約櫃抬進 大袞廟，放在 大袞的旁邊。', '於是民中約有三千人上那裏去，竟在 艾城人面前逃跑了。', 0, '正確內容記載於 以斯帖記 5:7。', '以斯帖記 5:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-23_1-4', '23-1', '以斯帖記', 'EST', '以斯帖記', '舊約', 'history', 1, 10, '出處辨識', '「王摘下自己的戒指，就是從 哈曼追回的，給了 末底改。 以斯帖派 末底改管理 哈曼的家產。」的經文出處是哪裡？', '以斯帖記 8:17', '以斯帖記 7:5', '以斯帖記 2:5', '以斯帖記 8:2', 3, '正確內容記載於 以斯帖記 8:2。', '以斯帖記 8:2', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-23_1-5', '23-1', '以斯帖記', 'EST', '以斯帖記', '舊約', 'history', 1, 10, '經文辨識', '根據《以斯帖記》的內容，以下哪一句經文出自這個範圍？', '住在 耶路撒冷、 法勒斯的子孫共四百六十八名，都是勇士。', '從曠野和這 黎巴嫩，直到 幼發拉底大河， 赫人的全地，又到大海日落之處，都要作你們的境界。', '所以住無城牆鄉村的 猶大人，如今都以亞達月十四日為設筵歡樂的吉日，彼此餽送禮物。', '大衛在 以東地設立防營， 以東人就都歸服他。 大衛無論往哪裏去，耶和華都使他得勝。', 2, '正確內容記載於 以斯帖記 9:19。', '以斯帖記 9:19', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-23_2-1', '23-2', '加拉太書', 'GAL', '加拉太書', '新約', 'pauline', 1, 6, '經文辨識', '根據《加拉太書》的內容，以下哪一句經文出自這個範圍？', '有誰當兵自備糧餉呢？有誰栽葡萄園不吃園裏的果子呢？有誰牧養牛羊不吃牛羊的奶呢？', '無論是 希臘人、化外人、聰明人、愚拙人，我都欠他們的債，', '然而，那把我從母腹裏分別出來、又施恩召我的上帝，', '無論做甚麼，或說話或行事，都要奉主耶穌的名，藉着他感謝父上帝。', 2, '正確內容記載於 加拉太書 1:15。', '加拉太書 1:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-23_2-2', '23-2', '加拉太書', 'GAL', '加拉太書', '新約', 'pauline', 1, 6, '出處辨識', '「我不廢掉上帝的恩；義若是藉着律法得的，基督就是徒然死了。」的經文出處是哪裡？', '加拉太書 2:21', '加拉太書 1:17', '加拉太書 5:25', '加拉太書 3:24', 0, '正確內容記載於 加拉太書 2:21。', '加拉太書 2:21', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-23_2-3', '23-2', '加拉太書', 'GAL', '加拉太書', '新約', 'pauline', 1, 6, '經文辨識', '根據《加拉太書》的內容，以下哪一句經文出自這個範圍？', '我可以證明，他們向上帝有熱心，但不是按着真知識；', '若沒有人翻，就當在會中閉口，只對自己和上帝說就是了。', '我也給 司提法那家施過洗，此外給別人施洗沒有，我卻記不清。', '你們既屬乎基督，就是 亞伯拉罕的後裔，是照着應許承受產業的了。', 3, '正確內容記載於 加拉太書 3:29。', '加拉太書 3:29', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-23_2-4', '23-2', '加拉太書', 'GAL', '加拉太書', '新約', 'pauline', 1, 6, '出處辨識', '「當時，那按着血氣生的逼迫了那按着 聖靈生的，現在也是這樣。」的經文出處是哪裡？', '加拉太書 6:18', '加拉太書 2:9', '加拉太書 4:29', '加拉太書 1:3', 2, '正確內容記載於 加拉太書 4:29。', '加拉太書 4:29', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-23_2-5', '23-2', '加拉太書', 'GAL', '加拉太書', '新約', 'pauline', 1, 6, '經文辨識', '根據《加拉太書》的內容，以下哪一句經文出自這個範圍？', '按我們所得的恩賜，各有不同。或說預言，就當照着信心的程度說 預言；', '人若無有，自己還以為有，就是自欺了。', '為這事，我三次求過主，叫這刺離開我。', '上帝藉我們所傳的福音召你們到這地步，好得着我們主耶穌基督的榮光。', 1, '正確內容記載於 加拉太書 6:3。', '加拉太書 6:3', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-24-1', '24', '約伯記(一)1~21 章', 'JOB', '約伯記', '舊約', 'poetry', 1, 21, '經文辨識', '根據《約伯記(一)1~21 章》的內容，以下哪一句經文出自這個範圍？', '你們當尊崇耶和華－我們的上帝， 在他腳凳前下拜。 他本為聖！', '上帝啊，你的慈愛何其寶貴！ 世人投靠在你翅膀的蔭下。', '被囚的人同得安逸， 不聽見督工的聲音。', '耶和華啊，求你不要遠離我！ 我的救主啊，求你快來幫助我！', 2, '正確內容記載於 約伯記 3:18。', '約伯記 3:18', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-24-2', '24', '約伯記(一)1~21 章', 'JOB', '約伯記', '舊約', 'poetry', 1, 21, '出處辨識', '「人算甚麼，你竟看他為大， 將他放在心上？」的經文出處是哪裡？', '約伯記 7:17', '約伯記 1:16', '約伯記 2:2', '約伯記 3:23', 0, '正確內容記載於 約伯記 7:17。', '約伯記 7:17', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-24-3', '24', '約伯記(一)1~21 章', 'JOB', '約伯記', '舊約', 'poetry', 1, 21, '經文辨識', '根據《約伯記(一)1~21 章》的內容，以下哪一句經文出自這個範圍？', '亮光不照惡人； 強橫的膀臂也必折斷。', '牠頸項中存着勁力； 在牠面前的都恐嚇蹦跳。', '求你除掉我所受的羞辱和藐視， 因我遵守你的法度。', '我這求告上帝、蒙他應允的人 竟成了朋友所譏笑的； 公義完全人竟受了人的譏笑。', 3, '正確內容記載於 約伯記 12:4。', '約伯記 12:4', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-24-4', '24', '約伯記(一)1~21 章', 'JOB', '約伯記', '舊約', 'poetry', 1, 21, '出處辨識', '「他不用倚靠虛假欺哄自己， 因虛假必成為他的報應。」的經文出處是哪裡？', '約伯記 15:31', '約伯記 21:24', '約伯記 12:25', '約伯記 1:1', 0, '正確內容記載於 約伯記 15:31。', '約伯記 15:31', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-24-5', '24', '約伯記(一)1~21 章', 'JOB', '約伯記', '舊約', 'poetry', 1, 21, '經文辨識', '根據《約伯記(一)1~21 章》的內容，以下哪一句經文出自這個範圍？', '他的兩手 好像金管， 鑲嵌水蒼玉； 他的身體 如同雕刻的象牙， 周圍鑲嵌藍寶石。', '你要依從上古的道嗎？ 這道是惡人所行的。', '他口內雖以惡為甘甜， 藏在舌頭底下，', '他們向上帝說：離開我們吧！ 又 說：全能者能把我們怎麼樣呢？', 2, '正確內容記載於 約伯記 20:12。', '約伯記 20:12', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-25_1-1', '25-1', '約伯記(二)22~42 章', 'JOB', '約伯記', '舊約', 'poetry', 22, 42, '經文辨識', '根據《約伯記(二)22~42 章》的內容，以下哪一句經文出自這個範圍？', '惡人臉無羞恥； 正直人行事堅定。', '你的國是永遠的國！ 你執掌的權柄存到萬代！', '在山上被大雨淋濕， 因沒有避身之處就挨近磐石。', '耶和華啊，求你轉回搭救我！ 因你的慈愛拯救我。', 2, '正確內容記載於 約伯記 24:8。', '約伯記 24:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-25_1-2', '25-1', '約伯記(二)22~42 章', 'JOB', '約伯記', '舊約', 'poetry', 22, 42, '出處辨識', '「他們不敢自信，我就向他們含笑； 他們不使我臉上的光改變。」的經文出處是哪裡？', '約伯記 28:17', '約伯記 41:2', '約伯記 36:22', '約伯記 29:24', 3, '正確內容記載於 約伯記 29:24。', '約伯記 29:24', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-25_1-3', '25-1', '約伯記(二)22~42 章', 'JOB', '約伯記', '舊約', 'poetry', 22, 42, '經文辨識', '根據《約伯記(二)22~42 章》的內容，以下哪一句經文出自這個範圍？', '你為何與他爭論呢？ 因他的事都不對人解說？', '你已將我的哀哭變為跳舞， 將我的麻衣脫去，給我披上喜樂，', '彎曲的心思，我必遠離； 一切的惡人，我不認識。', '願他親眼看見自己敗亡， 親自飲全能者的忿怒。', 0, '正確內容記載於 約伯記 33:13。', '約伯記 33:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-25_1-4', '25-1', '約伯記(二)22~42 章', 'JOB', '約伯記', '舊約', 'poetry', 22, 42, '出處辨識', '「他發響聲震遍天下， 發電光閃到地極。」的經文出處是哪裡？', '約伯記 22:28', '約伯記 34:19', '約伯記 37:3', '約伯記 28:7', 2, '正確內容記載於 約伯記 37:3。', '約伯記 37:3', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-25_1-5', '25-1', '約伯記(二)22~42 章', 'JOB', '約伯記', '舊約', 'poetry', 22, 42, '經文辨識', '根據《約伯記(二)22~42 章》的內容，以下哪一句經文出自這個範圍？', '因他們的心向他不正， 在他的約上也不忠心。', '求你掩面不看我的罪， 塗抹我一切的罪孽。', '牠伏在蓮葉之下， 臥在蘆葦隱密處和水窪子裏。', '轎柱是用銀做的， 轎底是用金做的； 坐墊是紫色的， 其中所鋪的乃 耶路撒冷眾女子的愛情。', 2, '正確內容記載於 約伯記 40:21。', '約伯記 40:21', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-25_2-1', '25-2', '以弗所書', 'EPH', '以弗所書', '新約', 'pauline', 1, 6, '經文辨識', '根據《以弗所書》的內容，以下哪一句經文出自這個範圍？', '經上說：「凡信他的人必不至於羞愧。」', '你有信心，就當在上帝面前守着。人在自己以為可行的事上能不自責，就有福了。', '上帝是信實的，你們原是被他所召，好與他兒子－我們的主耶穌基督一同得分。', '因此，我既聽見你們信從主耶穌，親愛眾聖徒，', 3, '正確內容記載於 以弗所書 1:15。', '以弗所書 1:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-25_2-2', '25-2', '以弗所書', 'EPH', '以弗所書', '新約', 'pauline', 1, 6, '出處辨識', '「各房靠他聯絡得合式，漸漸成為主的聖殿。」的經文出處是哪裡？', '以弗所書 2:21', '以弗所書 5:32', '以弗所書 1:4', '以弗所書 1:3', 0, '正確內容記載於 以弗所書 2:21。', '以弗所書 2:21', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-25_2-3', '25-2', '以弗所書', 'EPH', '以弗所書', '新約', 'pauline', 1, 6, '經文辨識', '根據《以弗所書》的內容，以下哪一句經文出自這個範圍？', '既是兒女，便是後嗣，就是上帝的後嗣，和基督同作後嗣。如果我們和他一同受苦，也必和他一同得榮耀。', '那降下的，就是遠升諸天之上要充滿萬有的。）', '凡恆心行善、尋求榮耀、尊貴和不能朽壞 之福的，就以永生報應他們；', '還是你藐視他豐富的恩慈、寬容、忍耐，不曉得他的恩慈是領你悔改呢？', 1, '正確內容記載於 以弗所書 4:10。', '以弗所書 4:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-25_2-4', '25-2', '以弗所書', 'EPH', '以弗所書', '新約', 'pauline', 1, 6, '出處辨識', '「因為他們暗中所行的，就是提起來也是可恥的。」的經文出處是哪裡？', '以弗所書 2:22', '以弗所書 4:16', '以弗所書 5:12', '以弗所書 2:6', 2, '正確內容記載於 以弗所書 5:12。', '以弗所書 5:12', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-25_2-5', '25-2', '以弗所書', 'EPH', '以弗所書', '新約', 'pauline', 1, 6, '經文辨識', '根據《以弗所書》的內容，以下哪一句經文出自這個範圍？', '也把你們因 聖靈所存的愛心告訴了我們。', '也要從你們那裏經過，往 馬其頓去，再從 馬其頓回到你們那裏，叫你們給我送行往 猶太去。', '我們在愛子裏得蒙救贖，罪過得以赦免。', '我還有末了的話：你們要靠着主，倚賴他的大能大力作剛強的人。', 3, '正確內容記載於 以弗所書 6:10。', '以弗所書 6:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-26-1', '26', '詩篇(一)1~21 篇', 'PSA', '詩篇', '舊約', 'poetry', 1, 21, '經文辨識', '根據《詩篇(一)1~21 篇》的內容，以下哪一句經文出自這個範圍？', '耶和華啊，我真是你的僕人； 我是你的僕人，是你婢女的兒子。 你已經解開我的綁索。', '上帝啊，求你為我造清潔的心， 使我裏面重新有正直的靈。', '願我的仇敵如惡人一樣； 願那起來攻擊我的，如不義之人一般。', '顯我為義的上帝啊， 我呼籲的時候，求你應允我！ 我在困苦中，你曾使我寬廣； 現在求你憐恤我，聽我的禱告！', 3, '正確內容記載於 詩篇 4:1。', '詩篇 4:1', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-26-2', '26', '詩篇(一)1~21 篇', 'PSA', '詩篇', '舊約', 'poetry', 1, 21, '出處辨識', '「你派他管理你手所造的， 使萬物，就是一切的牛羊、 田野的獸、空中的鳥、海裏的魚， 凡經行海道的，都服在…」的經文出處是哪裡？', '詩篇 8:6–8', '詩篇 11:6', '詩篇 7:13', '詩篇 19:1', 0, '正確內容記載於 詩篇 8:6–8。', '詩篇 8:6–8', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-26-3', '26', '詩篇(一)1~21 篇', 'PSA', '詩篇', '舊約', 'poetry', 1, 21, '經文辨識', '根據《詩篇(一)1~21 篇》的內容，以下哪一句經文出自這個範圍？', '約伯就坐在爐灰中，拿瓦片刮身體。', '他們拉去孤兒的驢， 強取寡婦的牛為當頭。', '耶和華啊，你必保護他們； 你必保佑他們永遠脫離這世代的人。', '他用這些審判眾民， 且賜豐富的糧食。', 2, '正確內容記載於 詩篇 12:7。', '詩篇 12:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-26-4', '26', '詩篇(一)1~21 篇', 'PSA', '詩篇', '舊約', 'poetry', 1, 21, '出處辨識', '「那時，因他發怒，地就搖撼戰抖； 山的根基也震動搖撼。」的經文出處是哪裡？', '詩篇 18:7', '詩篇 20:5', '詩篇 18:12', '詩篇 12:5', 0, '正確內容記載於 詩篇 18:7。', '詩篇 18:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-26-5', '26', '詩篇(一)1~21 篇', 'PSA', '詩篇', '舊約', 'poetry', 1, 21, '經文辨識', '根據《詩篇(一)1~21 篇》的內容，以下哪一句經文出自這個範圍？', '願你使他們滿面羞恥， 好叫他們尋求你－耶和華的名！', '你知道我受的辱罵、欺凌、羞辱； 我的敵人都在你面前。', '願他親眼看見自己敗亡， 親自飲全能者的忿怒。', '都比金子可羨慕，且比極多的精金可羨慕； 比蜜甘甜，且比蜂房下滴的蜜甘甜。', 3, '正確內容記載於 詩篇 19:10。', '詩篇 19:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-27-1', '27', '詩篇(二)22~41 篇', 'PSA', '詩篇', '舊約', 'poetry', 22, 41, '經文辨識', '根據《詩篇(二)22~41 篇》的內容，以下哪一句經文出自這個範圍？', '我雖然行過死蔭的 幽谷， 也不怕遭害， 因為你與我同在； 你的杖，你的竿，都安慰我。', '帝王榮耀在乎民多； 君王衰敗在乎民少。', '不料，有狂風從曠野颳來，擊打房屋的四角，房屋倒塌在少年人身上，他們就都死了；惟有我一人逃脫，來報信給你。」', '他們豈不指教你，告訴你， 從心裏發出言語來呢？', 0, '正確內容記載於 詩篇 23:4。', '詩篇 23:4', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-27-2', '27', '詩篇(二)22~41 篇', 'PSA', '詩篇', '舊約', 'poetry', 22, 41, '出處辨識', '「要將耶和華的名所當得的榮耀歸給他， 以聖潔的妝飾敬拜耶和華。」的經文出處是哪裡？', '詩篇 37:23', '詩篇 26:11', '詩篇 29:2', '詩篇 23:4', 2, '正確內容記載於 詩篇 29:2。', '詩篇 29:2', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-27-3', '27', '詩篇(二)22~41 篇', 'PSA', '詩篇', '舊約', 'poetry', 22, 41, '經文辨識', '根據《詩篇(二)22~41 篇》的內容，以下哪一句經文出自這個範圍？', '他是那造成他們眾人心的， 留意他們一切作為的。', '那時，我在他那裏為工師， 日日為他所喜愛， 常常在他面前踴躍，', '願他從聖所救助你， 從 錫安堅固你，', '求你應允我們，用右手拯救我們， 好叫你所親愛的人得救。', 0, '正確內容記載於 詩篇 33:15。', '詩篇 33:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-27-4', '27', '詩篇(二)22~41 篇', 'PSA', '詩篇', '舊約', 'poetry', 22, 41, '出處辨識', '「在那裏，作孽的人已經仆倒； 他們被推倒，不能再起來。」的經文出處是哪裡？', '詩篇 24:2', '詩篇 31:18', '詩篇 36:2', '詩篇 36:12', 3, '正確內容記載於 詩篇 36:12。', '詩篇 36:12', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-27-5', '27', '詩篇(二)22~41 篇', 'PSA', '詩篇', '舊約', 'poetry', 22, 41, '經文辨識', '根據《詩篇(二)22~41 篇》的內容，以下哪一句經文出自這個範圍？', '除去王面前的惡人， 國位就靠公義堅立。', '他若從本地被拔出， 那地就不認識他， 說： 我沒有見過你。', '因我所遭遇的是出於你， 我就默然不語。', '傳道者專心尋求可喜悅的言語，是憑正直寫的誠實話。', 2, '正確內容記載於 詩篇 39:9。', '詩篇 39:9', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-28-1', '28', '詩篇(三)42~72 篇', 'PSA', '詩篇', '舊約', 'poetry', 42, 72, '經文辨識', '根據《詩篇(三)42~72 篇》的內容，以下哪一句經文出自這個範圍？', '我又轉念，見日光之下有一件虛空的事：', '才德的婦人誰能得着呢？ 她的價值遠勝過珍珠。', '你的箭鋒快，射中王敵之心； 萬民仆倒在你以下。', '筵宴的日子過了， 約伯打發人去叫他們自潔。他清早起來，按着他們眾人的數目獻燔祭；因為他說：「恐怕我兒子犯了罪，心中棄掉上帝。」 約伯常常這樣行。', 2, '正確內容記載於 詩篇 45:5。', '詩篇 45:5', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-28-2', '28', '詩篇(三)42~72 篇', 'PSA', '詩篇', '舊約', 'poetry', 42, 72, '出處辨識', '「我向你犯罪，惟獨得罪了你； 在你眼前行了這惡， 以致你責備我的時候顯為公義， 判斷我的時候顯為清正。」的經文出處是哪裡？', '詩篇 51:4', '詩篇 67:1', '詩篇 62:9', '詩篇 44:21', 0, '正確內容記載於 詩篇 51:4。', '詩篇 51:4', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-28-3', '28', '詩篇(三)42~72 篇', 'PSA', '詩篇', '舊約', 'poetry', 42, 72, '經文辨識', '根據《詩篇(三)42~72 篇》的內容，以下哪一句經文出自這個範圍？', '耶和華問撒但說：「你曾用心察看我的僕人 約伯沒有？地上再沒有人像他完全正直，敬畏上帝，遠離惡事。你雖激動我攻擊他，無故地毀滅他，他仍然持守他的純正。」', '豈有一件事人能指着說這是新的？ 哪知，在我們以前的世代早已有了。', '他想到他們不過是血氣， 是一陣去而不返的風。', '你們用荊棘燒火，鍋還未熱， 他要用旋風把青的和燒着的一齊颳去。', 3, '正確內容記載於 詩篇 58:9。', '詩篇 58:9', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-28-4', '28', '詩篇(三)42~72 篇', 'PSA', '詩篇', '舊約', 'poetry', 42, 72, '出處辨識', '「他使我們的性命存活， 也不叫我們的腳搖動。」的經文出處是哪裡？', '詩篇 61:1', '詩篇 59:6', '詩篇 66:9', '詩篇 50:3', 2, '正確內容記載於 詩篇 66:9。', '詩篇 66:9', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-28-5', '28', '詩篇(三)42~72 篇', 'PSA', '詩篇', '舊約', 'poetry', 42, 72, '經文辨識', '根據《詩篇(三)42~72 篇》的內容，以下哪一句經文出自這個範圍？', '上帝啊，求你不要靜默！ 上帝啊，求你不要閉口，也不要不作聲！', '願那些對我說阿哈、阿哈的， 因羞愧退後。', '請你追想：無辜的人有誰滅亡？ 正直的人在何處剪除？', '你們就當懼怕刀劍； 因為忿怒 惹動刀劍的刑罰， 使你們知道有報應。', 1, '正確內容記載於 詩篇 70:3。', '詩篇 70:3', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-29-1', '29', '詩篇(四)73~89 篇', 'PSA', '詩篇', '舊約', 'poetry', 73, 89, '經文辨識', '根據《詩篇(四)73~89 篇》的內容，以下哪一句經文出自這個範圍？', '他們心裏說：我們要盡行毀滅； 他們就在遍地把上帝的會所都燒毀了。', '他們向我以惡報善， 使我的靈魂孤苦。', '只是上帝必救贖我的靈魂脫離陰間的權柄， 因他必收納我。 （細拉）', '又有一天，上帝的眾子來侍立在耶和華面前，撒但也來在其中。', 0, '正確內容記載於 詩篇 74:8。', '詩篇 74:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-29-2', '29', '詩篇(四)73~89 篇', 'PSA', '詩篇', '舊約', 'poetry', 73, 89, '出處辨識', '「他在曠野分裂磐石， 多多地給他們水喝，如從深淵而出。」的經文出處是哪裡？', '詩篇 86:10', '詩篇 86:4', '詩篇 83:17', '詩篇 78:15', 3, '正確內容記載於 詩篇 78:15。', '詩篇 78:15', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-29-3', '29', '詩篇(四)73~89 篇', 'PSA', '詩篇', '舊約', 'poetry', 73, 89, '經文辨識', '根據《詩篇(四)73~89 篇》的內容，以下哪一句經文出自這個範圍？', '耶和華的眼目看顧敬畏他的人 和仰望他慈愛的人，', '因為我困苦窮乏， 內心受傷。', '在 以法蓮、 便雅憫、 瑪拿西前面 施展你的大能，來救我們。', '她右手有長壽， 左手有富貴。', 2, '正確內容記載於 詩篇 80:2。', '詩篇 80:2', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-29-4', '29', '詩篇(四)73~89 篇', 'PSA', '詩篇', '舊約', 'poetry', 73, 89, '出處辨識', '「萬軍之耶和華啊， 倚靠你的人便為有福！」的經文出處是哪裡？', '詩篇 73:21', '詩篇 84:12', '詩篇 81:15', '詩篇 74:1', 1, '正確內容記載於 詩篇 84:12。', '詩篇 84:12', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-29-5', '29', '詩篇(四)73~89 篇', 'PSA', '詩篇', '舊約', 'poetry', 73, 89, '經文辨識', '根據《詩篇(四)73~89 篇》的內容，以下哪一句經文出自這個範圍？', '你是他們力量的榮耀； 因為你喜悅我們，我們的角必被高舉。', '他又賜福給他們，叫他們生養眾多， 也不叫他們的牲畜減少。', '我腳追隨他的步履； 我謹守他的道，並不偏離。', '耶和華問撒但說：「你從哪裏來？」撒但回答說：「我從地上走來走去，往返而來。」', 0, '正確內容記載於 詩篇 89:17。', '詩篇 89:17', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-30-1', '30', '詩篇(五)90~106 篇', 'PSA', '詩篇', '舊約', 'poetry', 90, 106, '經文辨識', '根據《詩篇(五)90~106 篇》的內容，以下哪一句經文出自這個範圍？', '他若求告我，我就應允他； 他在急難中，我要與他同在； 我要搭救他，使他尊貴。', '示巴人忽然闖來，把牲畜擄去，並用刀殺了僕人；惟有我一人逃脫，來報信給你。」', '好叫世界得知你的道路， 萬國得知你的救恩。', '上帝的言語句句都是煉淨的； 投靠他的，他便作他們的盾牌。', 0, '正確內容記載於 詩篇 91:15。', '詩篇 91:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-30-2', '30', '詩篇(五)90~106 篇', 'PSA', '詩篇', '舊約', 'poetry', 90, 106, '出處辨識', '「當以聖潔的妝飾敬拜耶和華； 全地要在他面前戰抖！」的經文出處是哪裡？', '詩篇 91:4', '詩篇 96:9', '詩篇 104:12', '詩篇 90:4', 1, '正確內容記載於 詩篇 96:9。', '詩篇 96:9', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-30-3', '30', '詩篇(五)90~106 篇', 'PSA', '詩篇', '舊約', 'poetry', 90, 106, '經文辨識', '根據《詩篇(五)90~106 篇》的內容，以下哪一句經文出自這個範圍？', '不可使慈愛、誠實離開你， 要繫在你頸項上，刻在你心版上。', '我口中的言語都是公義， 並無彎曲乖僻。', '這必為後代的人記下， 將來受造的民要讚美耶和華。', '羊羔 之毛是為你作衣服； 山羊是為作田地的價值，', 2, '正確內容記載於 詩篇 102:18。', '詩篇 102:18', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-30-4', '30', '詩篇(五)90~106 篇', 'PSA', '詩篇', '舊約', 'poetry', 90, 106, '出處辨識', '「他看地，地便震動； 他摸山，山就冒煙。」的經文出處是哪裡？', '詩篇 91:6', '詩篇 90:3', '詩篇 96:13', '詩篇 104:32', 3, '正確內容記載於 詩篇 104:32。', '詩篇 104:32', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-30-5', '30', '詩篇(五)90~106 篇', 'PSA', '詩篇', '舊約', 'poetry', 90, 106, '經文辨識', '根據《詩篇(五)90~106 篇》的內容，以下哪一句經文出自這個範圍？', '他們又在營中嫉妒 摩西 和耶和華的聖者 亞倫。', '在大水和水族以下的陰魂戰兢。', '主－耶和華啊，你是我所盼望的； 從我年幼，你是我所倚靠的。', '有一天， 約伯的兒女正在他們長兄的家裏吃飯喝酒，', 0, '正確內容記載於 詩篇 106:16。', '詩篇 106:16', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-31-1', '31', '詩篇(六)107~123 篇', 'PSA', '詩篇', '舊約', 'poetry', 107, 123, '經文辨識', '根據《詩篇(六)107~123 篇》的內容，以下哪一句經文出自這個範圍？', '你還要扔我在坑裏， 我的衣服都憎惡我。', '他卻將窮乏人安置在高處，脫離苦難， 使他的家屬多如羊群。', '君王憑誠實判斷窮人； 他的國位必永遠堅立。', '你豈能用套繩將野牛籠在犂溝之間？ 牠豈肯隨你耙山谷之地？', 1, '正確內容記載於 詩篇 107:41。', '詩篇 107:41', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-31-2', '31', '詩篇(六)107~123 篇', 'PSA', '詩篇', '舊約', 'poetry', 107, 123, '出處辨識', '「他從灰塵裏抬舉貧寒人， 從糞堆中提拔窮乏人，」的經文出處是哪裡？', '詩篇 107:28', '詩篇 109:12', '詩篇 113:7', '詩篇 107:1', 2, '正確內容記載於 詩篇 113:7。', '詩篇 113:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-31-3', '31', '詩篇(六)107~123 篇', 'PSA', '詩篇', '舊約', 'poetry', 107, 123, '經文辨識', '根據《詩篇(六)107~123 篇》的內容，以下哪一句經文出自這個範圍？', '惡人的燈何嘗熄滅？ 患難何嘗臨到他們呢？ 上帝何嘗發怒， 向他們分散災禍呢？', '他為雨露定命令， 為雷電定道路。', '惡人卻要滅亡。 耶和華的仇敵要像羊羔的脂油； 他們要消滅，要如煙消滅。', '但願我行事堅定， 得以遵守你的律例。', 3, '正確內容記載於 詩篇 119:5。', '詩篇 119:5', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
