INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-31-5', '31', '詩篇(六)107~123 篇', 'PSA', '詩篇', '舊約', 'poetry', 107, 123, '經文辨識', '根據《詩篇(六)107~123 篇》的內容，以下哪一句經文出自這個範圍？', '造他的要和他一樣， 凡靠他的也要如此。', '尚青的時候，還沒有割下， 比百樣的草先枯槁。', '愛你律法的人有大平安， 甚麼都不能使他們絆腳。', '你們敬畏耶和華的人要讚美他！ 雅各的後裔都要榮耀他！ 以色列的後裔都要懼怕他！', 2, '正確內容記載於 詩篇 119:165。', '詩篇 119:165', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-32-1', '32', '詩篇(七)124~150 篇', 'PSA', '詩篇', '舊約', 'poetry', 124, 150, '經文辨識', '根據《詩篇(七)124~150 篇》的內容，以下哪一句經文出自這個範圍？', '求你扶持我，我便得救， 時常看重你的律例。', '羊羔 之毛是為你作衣服； 山羊是為作田地的價值，', '從我幼年以來，敵人屢次苦害我， 卻沒有勝了我。', '心中的苦楚，自己知道； 心裏的喜樂，外人無干。', 2, '正確內容記載於 詩篇 129:2。', '詩篇 129:2', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-32-2', '32', '詩篇(七)124~150 篇', 'PSA', '詩篇', '舊約', 'poetry', 124, 150, '出處辨識', '「以色列家啊，你們要稱頌耶和華！ 亞倫家啊，你們要稱頌耶和華！」的經文出處是哪裡？', '詩篇 128:1', '詩篇 124:1', '詩篇 142:6', '詩篇 135:19', 3, '正確內容記載於 詩篇 135:19。', '詩篇 135:19', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-32-3', '32', '詩篇(七)124~150 篇', 'PSA', '詩篇', '舊約', 'poetry', 124, 150, '經文辨識', '根據《詩篇(七)124~150 篇》的內容，以下哪一句經文出自這個範圍？', '我在暗中受造，在地的深處被聯絡； 那時，我的形體並不向你隱藏。', '人有疾病，心能忍耐； 心靈憂傷，誰能承當呢？', '你不要說，我要以惡報惡； 要等候耶和華，他必拯救你。', '這等下流人在我右邊起來， 推開我的腳，築成戰路來攻擊我。', 0, '正確內容記載於 詩篇 139:15。', '詩篇 139:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-32-4', '32', '詩篇(七)124~150 篇', 'PSA', '詩篇', '舊約', 'poetry', 124, 150, '出處辨識', '「求你從上伸手救拔我， 救我出離大水， 救我脫離外邦人的手。」的經文出處是哪裡？', '詩篇 124:6', '詩篇 127:2', '詩篇 144:7', '詩篇 136:7', 2, '正確內容記載於 詩篇 144:7。', '詩篇 144:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-32-5', '32', '詩篇(七)124~150 篇', 'PSA', '詩篇', '舊約', 'poetry', 124, 150, '經文辨識', '根據《詩篇(七)124~150 篇》的內容，以下哪一句經文出自這個範圍？', '他將他的道指示 雅各， 將他的律例典章指示 以色列。', '求你想念，我的生命不過是一口氣； 我的眼睛必不再見福樂。', '因為惡人的嘴和詭詐人的口已經張開攻擊我； 他們用撒謊的舌頭對我說話。', '那時他看見智慧，而且述說； 他堅定，並且查究。', 0, '正確內容記載於 詩篇 147:19。', '詩篇 147:19', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-33_1-1', '33-1', '腓利比書', 'PHP', '腓立比書', '新約', 'pauline', 1, 4, '經文辨識', '根據《腓利比書》的內容，以下哪一句經文出自這個範圍？', '娶了妻的，是為世上的事掛慮，想怎樣叫妻子喜悅。', '我說的話不是奉主命說的，乃是像愚妄人放膽自誇；', '可見栽種的，算不得甚麼，澆灌的，也算不得甚麼；只在那叫他生長的上帝。', '並靠着耶穌基督結滿了仁義的果子，叫榮耀稱讚歸與上帝。', 3, '正確內容記載於 腓立比書 1:11。', '腓立比書 1:11', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-33_1-2', '33-1', '腓利比書', 'PHP', '腓立比書', '新約', 'pauline', 1, 4, '出處辨識', '「所以，在基督裏若有甚麼勸勉，愛心有甚麼安慰， 聖靈有甚麼交通， 心中有甚麼慈悲憐憫，」的經文出處是哪裡？', '腓立比書 4:15', '腓立比書 2:6', '腓立比書 2:1', '腓立比書 4:23', 2, '正確內容記載於 腓立比書 2:1。', '腓立比書 2:1', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-33_1-3', '33-1', '腓利比書', 'PHP', '腓立比書', '新約', 'pauline', 1, 4, '經文辨識', '根據《腓利比書》的內容，以下哪一句經文出自這個範圍？', '但我稍微放膽寫信給你們，是要提醒你們的記性，特因上帝所給我的恩典，', '但你們知道 提摩太的明證；他興旺福音，與我同勞，待我像兒子待父親一樣。', '到了日期，那可稱頌、獨有權能的萬王之王、萬主之主，', '以賽亞指着 以色列人喊着說：「 以色列人雖多如海沙，得救的不過是剩下的餘數；', 1, '正確內容記載於 腓立比書 2:22。', '腓立比書 2:22', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-33_1-4', '33-1', '腓利比書', 'PHP', '腓立比書', '新約', 'pauline', 1, 4, '出處辨識', '「向着標竿直跑，要得上帝在基督耶穌裏從上面召我來得的獎賞。」的經文出處是哪裡？', '腓立比書 3:14', '腓立比書 1:2', '腓立比書 4:19', '腓立比書 1:1', 0, '正確內容記載於 腓立比書 3:14。', '腓立比書 3:14', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-33_1-5', '33-1', '腓利比書', 'PHP', '腓立比書', '新約', 'pauline', 1, 4, '經文辨識', '根據《腓利比書》的內容，以下哪一句經文出自這個範圍？', '這些事，你要吩咐人，也要教導人。', '你們也是如此。舌頭若不說容易明白的話，怎能知道所說的是甚麼呢？這就是向空說話了。', '我們受審的時候，乃是被主懲治，免得我們和世人一同定罪。', '我靠着那加給我力量的，凡事都能做。', 3, '正確內容記載於 腓立比書 4:13。', '腓立比書 4:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-33_2-1', '33-2', '箴言(一)1~12 章', 'PRO', '箴言', '舊約', 'poetry', 1, 12, '經文辨識', '根據《箴言(一)1~12 章》的內容，以下哪一句經文出自這個範圍？', '洪水泛濫之時，耶和華坐着 為王； 耶和華坐着為王，直到永遠。', '耶和華問撒但說：「你曾用心察看我的僕人 約伯沒有？地上再沒有人像他完全正直，敬畏上帝，遠離惡事。你雖激動我攻擊他，無故地毀滅他，他仍然持守他的純正。」', '尋找它，如尋找銀子， 搜求它，如搜求隱藏的珍寶，', '你們不要作聲，任憑我吧！ 讓我說話，無論如何我都承當。', 2, '正確內容記載於 箴言 2:4。', '箴言 2:4', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-33_2-2', '33-2', '箴言(一)1~12 章', 'PRO', '箴言', '舊約', 'poetry', 1, 12, '出處辨識', '「因為他們以奸惡吃餅， 以強暴喝酒。」的經文出處是哪裡？', '箴言 3:31', '箴言 12:9', '箴言 4:17', '箴言 5:23', 2, '正確內容記載於 箴言 4:17。', '箴言 4:17', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-33_2-3', '33-2', '箴言(一)1~12 章', 'PRO', '箴言', '舊約', 'poetry', 1, 12, '經文辨識', '根據《箴言(一)1~12 章》的內容，以下哪一句經文出自這個範圍？', '我兒，你要遵守我的言語， 將我的命令存記在心。', '因為耳朵試驗話語， 好像上膛嘗食物。', '你重立見證攻擊我， 向我加增惱怒， 如軍兵更換着攻擊我。', '他正要充滿肚腹的時候， 上帝必將猛烈的忿怒降在他身上； 正在他吃飯的時候， 要將這忿怒像雨降在他身上。', 0, '正確內容記載於 箴言 7:1。', '箴言 7:1', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-33_2-4', '33-2', '箴言(一)1~12 章', 'PRO', '箴言', '舊約', 'poetry', 1, 12, '出處辨識', '「你們愚蒙人，要捨棄 愚蒙， 就得存活，並要走光明的道。」的經文出處是哪裡？', '箴言 4:8', '箴言 8:20', '箴言 10:16', '箴言 9:6', 3, '正確內容記載於 箴言 9:6。', '箴言 9:6', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-33_2-5', '33-2', '箴言(一)1~12 章', 'PRO', '箴言', '舊約', 'poetry', 1, 12, '經文辨識', '根據《箴言(一)1~12 章》的內容，以下哪一句經文出自這個範圍？', '約伯卻對她說：「你說話像愚頑的婦人一樣。噯！難道我們從上帝手裏得福，不也受禍嗎？」在這一切的事上 約伯並不以口犯罪。', '這都因你的惱恨和忿怒； 你把我拾起來，又把我摔下去。', '好施捨的，必得豐裕； 滋潤人的，必得滋潤。', '他們就同他七天七夜坐在地上，一個人也不向他說句話，因為他極其痛苦。', 2, '正確內容記載於 箴言 11:25。', '箴言 11:25', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-34-1', '34', '箴言(二)', 'PRO', '箴言', '舊約', 'poetry', 13, 31, '經文辨識', '根據《箴言(二)》的內容，以下哪一句經文出自這個範圍？', '欺壓貧寒的，是辱沒造他的主； 憐憫窮乏的，乃是尊敬主。', '哪知上帝以美物充滿他們的房屋； 但惡人所謀定的離我好遠。', '和地上為自己重造荒邱的君王、謀士，', '因為他們如草快被割下， 又如青菜快要枯乾。', 0, '正確內容記載於 箴言 14:31。', '箴言 14:31', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-34-2', '34', '箴言(二)', 'PRO', '箴言', '舊約', 'poetry', 13, 31, '出處辨識', '「人有疾病，心能忍耐； 心靈憂傷，誰能承當呢？」的經文出處是哪裡？', '箴言 15:19', '箴言 18:14', '箴言 19:27', '箴言 13:5', 1, '正確內容記載於 箴言 18:14。', '箴言 18:14', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-34-3', '34', '箴言(二)', 'PRO', '箴言', '舊約', 'poetry', 13, 31, '經文辨識', '根據《箴言(二)》的內容，以下哪一句經文出自這個範圍？', '現今，在天有我的見證， 在上有我的中保。', '那時我說：看哪，我來了！ 我的事在經卷上已經記載了。', '耶和華的眼目眷顧聰明人， 卻傾敗奸詐人的言語。', '雖是這樣，他們仍舊犯罪， 不信他奇妙的作為。', 2, '正確內容記載於 箴言 22:12。', '箴言 22:12', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-34-4', '34', '箴言(二)', 'PRO', '箴言', '舊約', 'poetry', 13, 31, '出處辨識', '「夏天落雪，收割時下雨，都不相宜； 愚昧人得尊榮也是如此。」的經文出處是哪裡？', '箴言 14:34', '箴言 14:26', '箴言 22:17', '箴言 26:1', 3, '正確內容記載於 箴言 26:1。', '箴言 26:1', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-34-5', '34', '箴言(二)', 'PRO', '箴言', '舊約', 'poetry', 13, 31, '經文辨識', '根據《箴言(二)》的內容，以下哪一句經文出自這個範圍？', '上帝的言語句句都是煉淨的； 投靠他的，他便作他們的盾牌。', '將要滅亡的為我祝福； 我也使寡婦心中歡樂。', '你將生命和慈愛賜給我； 你也眷顧保全我的心靈。', '地的一切疆界是你所立的； 夏天和冬天是你所定的。', 0, '正確內容記載於 箴言 30:5。', '箴言 30:5', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-35_1-1', '35-1', '歌羅西書', 'COL', '歌羅西書', '新約', 'pauline', 1, 4, '經文辨識', '根據《歌羅西書》的內容，以下哪一句經文出自這個範圍？', '我在他兒子福音上，用心靈所事奉的上帝可以見證，我怎樣不住地提到你們；', '好叫你們行事為人對得起主，凡事蒙他喜悅，在一切善事上結果子，漸漸地多知道上帝；', '不錯！他們因為不信，所以被折下來；你因為信，所以立得住；你不可自高，反要懼怕。', '我－ 保羅親筆問你們安。凡我的信都以此為記，我的筆跡就是這樣。', 1, '正確內容記載於 歌羅西書 1:10。', '歌羅西書 1:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-35_1-2', '35-1', '歌羅西書', 'COL', '歌羅西書', '新約', 'pauline', 1, 4, '出處辨識', '「我也為此勞苦，照着他在我裏面運用的大能盡心竭力。」的經文出處是哪裡？', '歌羅西書 3:16', '歌羅西書 2:9', '歌羅西書 1:29', '歌羅西書 1:6', 2, '正確內容記載於 歌羅西書 1:29。', '歌羅西書 1:29', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-35_1-3', '35-1', '歌羅西書', 'COL', '歌羅西書', '新約', 'pauline', 1, 4, '經文辨識', '根據《歌羅西書》的內容，以下哪一句經文出自這個範圍？', '這固然是他們樂意的，其實也算是所欠的債；因外邦人既然在他們屬靈的好處上有分，就當把養身之物供給他們。', '那說方言的，原不是對人說，乃是對上帝說，因為沒有人聽出來。然而，他在心靈裏卻是講說各樣的奧祕。', '或作勸化的，就當 專一勸化；施捨的，就當誠實；治理的，就當殷勤；憐憫人的，就當甘心。', '不持定元首。全身既然靠着他，筋節得以相助聯絡，就因上帝大得長進。', 3, '正確內容記載於 歌羅西書 2:19。', '歌羅西書 2:19', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-35_1-4', '35-1', '歌羅西書', 'COL', '歌羅西書', '新約', 'pauline', 1, 4, '出處辨識', '「又要叫基督的平安在你們心裏作主；你們也為此蒙召，歸為一體；且要存感謝的心。」的經文出處是哪裡？', '歌羅西書 3:15', '歌羅西書 2:5', '歌羅西書 3:24', '歌羅西書 1:22', 0, '正確內容記載於 歌羅西書 3:15。', '歌羅西書 3:15', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-35_1-5', '35-1', '歌羅西書', 'COL', '歌羅西書', '新約', 'pauline', 1, 4, '經文辨識', '根據《歌羅西書》的內容，以下哪一句經文出自這個範圍？', '栽種的和澆灌的，都是一樣，但將來各人要照自己的工夫得自己的賞賜。', '耶穌被交給人，是為我們的過犯；復活，是為叫我們稱義。', '我又打發一位親愛忠心的兄弟 阿尼西謀同去；他也是你們那裏的人。他們要把這裏一切的事都告訴你們。', '若我所做的，是我所不願意的，我就應承律法是善的。', 2, '正確內容記載於 歌羅西書 4:9。', '歌羅西書 4:9', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-35_2-1', '35-2', '傳道書', 'ECC', '傳道書', '舊約', 'poetry', 1, 12, '經文辨識', '根據《傳道書》的內容，以下哪一句經文出自這個範圍？', '我若像 亞當 遮掩我的過犯， 將罪孽藏在懷中；', '野牛豈肯服事你？ 豈肯住在你的槽旁？', '我為自己動大工程，建造房屋，栽種葡萄園，', '絕望人的講論既然如風， 你們還想要駁正言語嗎？', 2, '正確內容記載於 傳道書 2:4。', '傳道書 2:4', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-35_2-2', '35-2', '傳道書', 'ECC', '傳道書', '舊約', 'poetry', 1, 12, '出處辨識', '「故此，我見人莫強如在他經營的事上喜樂，因為這是他的分。他身後的事誰能使他回來得見呢？」的經文出處是哪裡？', '傳道書 5:8', '傳道書 2:24', '傳道書 9:6', '傳道書 3:22', 3, '正確內容記載於 傳道書 3:22。', '傳道書 3:22', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-35_2-3', '35-2', '傳道書', 'ECC', '傳道書', '舊約', 'poetry', 1, 12, '經文辨識', '根據《傳道書》的內容，以下哪一句經文出自這個範圍？', '先前所有的，早已起了名，並知道何為人，他也不能與那比自己力大的相爭。', '他們看早晨如幽暗， 因為他們曉得幽暗的驚駭。', '現在 有雲遮蔽，人不得見穹蒼的光亮； 但風吹過，天又發晴。', '那將要灰心、離棄全能者、 不敬畏上帝的人， 他的朋友當以慈愛待他。', 0, '正確內容記載於 傳道書 6:10。', '傳道書 6:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-35_2-4', '35-2', '傳道書', 'ECC', '傳道書', '舊約', 'poetry', 1, 12, '出處辨識', '「世上有一件虛空的事，就是義人所遭遇的，反照惡人所行的；又有惡人所遭遇的，反照義人所行的。我說，這也是虛…」的經文出處是哪裡？', '傳道書 3:21', '傳道書 3:18', '傳道書 8:14', '傳道書 3:10', 2, '正確內容記載於 傳道書 8:14。', '傳道書 8:14', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-35_2-5', '35-2', '傳道書', 'ECC', '傳道書', '舊約', 'poetry', 1, 12, '經文辨識', '根據《傳道書》的內容，以下哪一句經文出自這個範圍？', '你叫你的民遇見艱難； 你叫我們喝那使人東倒西歪的酒。', '義人哪，你們應當靠耶和華歡樂； 正直人的讚美是合宜的。', '雲若滿了雨，就必傾倒在地上。 樹若向南倒，或向北倒， 樹倒在何處，就存在何處。', '你必知道你帳棚平安， 要查看你的羊圈，一無所失；', 2, '正確內容記載於 傳道書 11:3。', '傳道書 11:3', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-36_1-1', '36-1', '雅歌', 'SNG', '雅歌', '舊約', 'poetry', 1, 8, '經文辨識', '根據《雅歌》的內容，以下哪一句經文出自這個範圍？', '我以我的良人為一袋沒藥， 常在我懷中。', '已過的 世代，無人記念； 將來的 世代，後來的人也不記念。', '他們的愛，他們的恨，他們的嫉妒，早都消滅了。在日光之下所行的一切事上，他們永不再有分了。', '他的家產有七千羊，三千駱駝，五百對牛，五百母驢，並有許多僕婢。這人在東方人中就為至大。', 0, '正確內容記載於 雅歌 1:13。', '雅歌 1:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-36_1-2', '36-1', '雅歌', 'SNG', '雅歌', '舊約', 'poetry', 1, 8, '出處辨識', '「我說：我要起來，遊行城中， 在街市上，在寬闊處， 尋找我心所愛的。 我尋找他，卻尋不見。」的經文出處是哪裡？', '雅歌 3:8', '雅歌 7:4', '雅歌 1:16', '雅歌 3:2', 3, '正確內容記載於 雅歌 3:2。', '雅歌 3:2', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-36_1-3', '36-1', '雅歌', 'SNG', '雅歌', '舊約', 'poetry', 1, 8, '經文辨識', '根據《雅歌》的內容，以下哪一句經文出自這個範圍？', '你是園中的泉，活水的井， 從 黎巴嫩流下來的溪水。', '在城門旁，在城門口， 在城門洞，大聲說：', '他吩咐日頭不出來，就不出來， 又封閉眾星。', '我的拯救、我的榮耀都在乎上帝； 我力量的磐石、我的避難所都在乎上帝。', 0, '正確內容記載於 雅歌 4:15。', '雅歌 4:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-36_1-4', '36-1', '雅歌', 'SNG', '雅歌', '舊約', 'poetry', 1, 8, '出處辨識', '「你的牙齒如一群母羊 洗淨上來，個個都有雙生， 沒有一隻喪掉子的。」的經文出處是哪裡？', '雅歌 6:13', '雅歌 6:6', '雅歌 1:8', '雅歌 6:9', 1, '正確內容記載於 雅歌 6:6。', '雅歌 6:6', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-36_1-5', '36-1', '雅歌', 'SNG', '雅歌', '舊約', 'poetry', 1, 8, '經文辨識', '根據《雅歌》的內容，以下哪一句經文出自這個範圍？', '我厭棄 性命，不願永活。 你任憑我吧，因我的日子都是虛空。', '你且伸手毀他一切所有的；他必當面棄掉你。」', '他的左手必在我頭下； 他的右手必將我抱住。', '你們一切被他造的， 在他所治理的各處， 都要稱頌耶和華！ 我的心哪，你要稱頌耶和華！', 2, '正確內容記載於 雅歌 8:3。', '雅歌 8:3', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-36_2-1', '36-2', '帖撒羅尼迦前書', '1TH', '帖撒羅尼迦前書', '新約', 'pauline', 1, 5, '經文辨識', '根據《帖撒羅尼迦前書》的內容，以下哪一句經文出自這個範圍？', '我們現在所知道的有限，先知所講的也有限，', '凡事大有好處：第一是上帝的聖言交託他們。', '又問 馬利亞安；她為你們多受勞苦。', '因為他們自己已經報明我們是怎樣進到你們那裏，你們是怎樣離棄偶像，歸向上帝，要服事那又真又活的上帝，', 3, '正確內容記載於 帖撒羅尼迦前書 1:9。', '帖撒羅尼迦前書 1:9', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-36_2-2', '36-2', '帖撒羅尼迦前書', '1TH', '帖撒羅尼迦前書', '新約', 'pauline', 1, 5, '出處辨識', '「這 猶太人殺了主耶穌和先知，又把我們趕出去。他們不得上帝的喜悅，且與眾人為敵，」的經文出處是哪裡？', '帖撒羅尼迦前書 2:15', '帖撒羅尼迦前書 2:9', '帖撒羅尼迦前書 3:9', '帖撒羅尼迦前書 1:9', 0, '正確內容記載於 帖撒羅尼迦前書 2:15。', '帖撒羅尼迦前書 2:15', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-36_2-3', '36-2', '帖撒羅尼迦前書', '1TH', '帖撒羅尼迦前書', '新約', 'pauline', 1, 5, '經文辨識', '根據《帖撒羅尼迦前書》的內容，以下哪一句經文出自這個範圍？', '似乎憂愁，卻是常常快樂的；似乎貧窮，卻是叫許多人富足的；似乎一無所有，卻是樣樣都有的。', '又願主叫你們彼此相愛的心，並愛眾人的心都能增長，充足，如同我們愛你們一樣，', '我對那盤問我的人就是這樣分訴：', '這是極大的奧祕，但我是指着基督和教會說的。', 1, '正確內容記載於 帖撒羅尼迦前書 3:12。', '帖撒羅尼迦前書 3:12', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-36_2-4', '36-2', '帖撒羅尼迦前書', '1TH', '帖撒羅尼迦前書', '新約', 'pauline', 1, 5, '出處辨識', '「因為主必親自從天降臨，有呼叫的聲音和天使長的聲音，又有上帝的號 吹響；那在基督裏死了的人必先復活。」的經文出處是哪裡？', '帖撒羅尼迦前書 2:1', '帖撒羅尼迦前書 1:9', '帖撒羅尼迦前書 4:16', '帖撒羅尼迦前書 5:6', 2, '正確內容記載於 帖撒羅尼迦前書 4:16。', '帖撒羅尼迦前書 4:16', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-36_2-5', '36-2', '帖撒羅尼迦前書', '1TH', '帖撒羅尼迦前書', '新約', 'pauline', 1, 5, '經文辨識', '根據《帖撒羅尼迦前書》的內容，以下哪一句經文出自這個範圍？', '況且，我們的軟弱有 聖靈幫助；我們本不曉得當怎樣禱告，只是 聖靈親自用說不出來的歎息替我們禱告。', '所以，不要容罪在你們必死的身上作王，使你們順從身子的私慾。', '除了我不累着你們這一件事，你們還有甚麼事不及別的教會呢？這不公之處，求你們饒恕我吧。', '我們又勸弟兄們，要警戒不守規矩的人，勉勵灰心的人，扶助軟弱的人，也要向眾人忍耐。', 3, '正確內容記載於 帖撒羅尼迦前書 5:14。', '帖撒羅尼迦前書 5:14', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-37-1', '37', '以賽亞書(一)1~23 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 1, 23, '經文辨識', '根據《以賽亞書(一)1~23 章》的內容，以下哪一句經文出自這個範圍？', '將來 雅各要扎根， 以色列要發芽開花； 他們的果實必充滿世界。', '他使住高處的與高城一併敗落， 將城拆毀，拆平，直到塵埃，', '你們看見，就心中快樂； 你們的骨頭必得滋潤像嫩草一樣； 而且耶和華的手向他僕人所行的必被人知道； 他也要向仇敵發惱恨。', '又臨到 黎巴嫩高大的香柏樹和 巴珊的橡樹；', 3, '正確內容記載於 以賽亞書 2:13。', '以賽亞書 2:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-37-2', '37', '以賽亞書(一)1~23 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 1, 23, '出處辨識', '「以法蓮的首城是 撒馬利亞； 撒馬利亞的首領是 利瑪利的兒子。 你們若是不信， 定然不得立穩。』」的經文出處是哪裡？', '以賽亞書 7:9', '以賽亞書 1:9', '以賽亞書 9:21', '以賽亞書 11:2', 0, '正確內容記載於 以賽亞書 7:9。', '以賽亞書 7:9', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-37-3', '37', '以賽亞書(一)1~23 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 1, 23, '經文辨識', '根據《以賽亞書(一)1~23 章》的內容，以下哪一句經文出自這個範圍？', '我必叫 埃及被擄的人回來，使他們歸回本地 巴忒羅。在那裏必成為低微的國，', '因為各席上滿了嘔吐的污穢， 無一處 乾淨。', '他們過了隘口， 在 迦巴住宿。 拉瑪人戰兢； 掃羅的 基比亞人逃跑。', '用 巴珊的橡樹做你的槳， 用象牙鑲嵌 基提海島的黃楊木為坐板。', 2, '正確內容記載於 以賽亞書 10:29。', '以賽亞書 10:29', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-37-4', '37', '以賽亞書(一)1~23 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 1, 23, '出處辨識', '「我心為 摩押悲哀； 他的貴冑 逃到 瑣珥， 到 伊基拉‧施利施亞。 他們上 魯希坡，隨走隨哭； 在 何…」的經文出處是哪裡？', '以賽亞書 15:5', '以賽亞書 3:9', '以賽亞書 1:1', '以賽亞書 21:7', 0, '正確內容記載於 以賽亞書 15:5。', '以賽亞書 15:5', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-37-5', '37', '以賽亞書(一)1~23 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 1, 23, '經文辨識', '根據《以賽亞書(一)1~23 章》的內容，以下哪一句經文出自這個範圍？', '耶和華說：「我必在你們眼前報復 巴比倫人和 迦勒底居民在 錫安所行的諸惡。」', '他們要建造房屋，自己居住； 栽種葡萄園，吃其中的果子。', '窯匠用泥做的器皿，在他手中做壞了，他又用這泥另做別的器皿；窯匠看怎樣好，就怎樣做。', '主對我這樣說：「一年之內，照雇工的年數， 基達的一切榮耀必歸於無有。', 3, '正確內容記載於 以賽亞書 21:16。', '以賽亞書 21:16', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-38-1', '38', '以賽亞書(二)24~39 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 24, 39, '經文辨識', '根據《以賽亞書(二)24~39 章》的內容，以下哪一句經文出自這個範圍？', '耶和華的手必按在這山上； 摩押人在所居之地必被踐踏，好像乾草被踐踏在糞池的水中。', '這是 尼利亞的兒子 巴錄挑唆你害我們，要將我們交在 迦勒底人的手中，使我們有被殺的，有被擄到 巴比倫去的。」', '耶和華說：「我必在 摩押地使那在邱壇獻祭的，和那向他的神燒香的都斷絕了。', '他們必為你作起哀歌說： 你這有名之城， 素為航海之人居住， 在海上為最堅固的； 平日你和居民使一切住在那裏的人無不驚恐； 現在何竟毀滅了？', 0, '正確內容記載於 以賽亞書 25:10。', '以賽亞書 25:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-38-2', '38', '以賽亞書(二)24~39 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 24, 39, '出處辨識', '「做餅的 糧食是用磨磨碎， 因它不必常打； 雖用碌碡和馬打散， 卻不磨它。」的經文出處是哪裡？', '以賽亞書 37:8', '以賽亞書 24:16', '以賽亞書 28:28', '以賽亞書 30:5', 2, '正確內容記載於 以賽亞書 28:28。', '以賽亞書 28:28', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-38-3', '38', '以賽亞書(二)24~39 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 24, 39, '經文辨識', '根據《以賽亞書(二)24~39 章》的內容，以下哪一句經文出自這個範圍？', '到那日，各人必將他金偶像銀偶像，就是親手所造、陷自己在罪中的，都拋棄了。', '眾海島必等候我， 首先是 他施的船隻， 將你的眾子連他們的金銀從遠方一同帶來， 都為耶和華－你上帝的名， 又為 以色列的聖者， 因為他已經榮耀了你。', '我卻使 以掃赤露， 顯出他的隱密處； 他不能自藏。 他的後裔、弟兄、鄰舍盡都滅絕； 他也歸於無有。', '耶和華說：「 猶大人行我眼中看為惡的事，將可憎之物設立在稱為我名下的殿中，污穢這殿。', 0, '正確內容記載於 以賽亞書 31:7。', '以賽亞書 31:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-38-4', '38', '以賽亞書(二)24~39 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 24, 39, '出處辨識', '「必開花繁盛， 樂上加樂，而且歡呼。 黎巴嫩的榮耀， 並 迦密與 沙崙的華美，必賜給它。 人必看見耶和華…」的經文出處是哪裡？', '以賽亞書 26:16', '以賽亞書 33:12', '以賽亞書 27:12', '以賽亞書 35:2', 3, '正確內容記載於 以賽亞書 35:2。', '以賽亞書 35:2', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-38-5', '38', '以賽亞書(二)24~39 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 24, 39, '經文辨識', '根據《以賽亞書(二)24~39 章》的內容，以下哪一句經文出自這個範圍？', '原來 以色列家和 猶大家大行詭詐攻擊我。 這是耶和華說的。', '主耶和華說：「我指着我的永生起誓，因你用一切可憎的物、可厭的事玷污了我的聖所，故此，我定要使 你人數減少，我眼必不顧惜你，也不可憐你。', '因我為自己的緣故，又為我僕人 大衛的緣故，必保護拯救這城。」', '耶利米說：「 迦勒底人必不將你交出。求你聽從我對你所說耶和華的話，這樣你必得好處，你的命也必存活。', 2, '正確內容記載於 以賽亞書 37:35。', '以賽亞書 37:35', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-39_1-1', '39-1', '以賽亞書(三)40~66 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 40, 66, '經文辨識', '根據《以賽亞書(三)40~66 章》的內容，以下哪一句經文出自這個範圍？', '希西家從使者手裏接過書信來，看完了，就上耶和華的殿，將書信在耶和華面前展開。', '耶和華已經向海伸手， 震動列國。 至於 迦南， 他已經吩咐拆毀其中的保障。', '可以聲明，指示我們將來必遇的事， 說明先前的是甚麼事， 好叫我們思索，得知事的結局， 或者把將來的事指示我們。', '我使你不再聽見各國的羞辱，不再受萬民的辱罵，也不再使國民絆跌。這是主耶和華說的。」', 2, '正確內容記載於 以賽亞書 41:22。', '以賽亞書 41:22', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-39_1-2', '39-1', '以賽亞書(三)40~66 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 40, 66, '出處辨識', '「惟有 以色列必蒙耶和華的拯救， 得永遠的救恩。 你們必不蒙羞，也不抱愧， 直到永世無盡。」的經文出處是哪裡？', '以賽亞書 45:17', '以賽亞書 47:14', '以賽亞書 45:24', '以賽亞書 60:14', 0, '正確內容記載於 以賽亞書 45:17。', '以賽亞書 45:17', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-39_1-3', '39-1', '以賽亞書(三)40~66 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 40, 66, '經文辨識', '根據《以賽亞書(三)40~66 章》的內容，以下哪一句經文出自這個範圍？', '耶和華又說： 我必按你們做事的結果刑罰你們； 我也必使火在 耶路撒冷的林中着起， 將她四圍所有的盡行燒滅。」', '王下令，人就把那些控告 但以理的人，連他們的妻子兒女都帶來，扔在獅子坑中。他們還沒有到坑底，獅子就抓住他們，咬碎他們的骨頭。', '你們在這城中殺人增多，使被殺的人充滿街道。', '使海與深淵的水乾涸、 使海的深處變為贖民經過之路的， 不是你嗎？', 3, '正確內容記載於 以賽亞書 51:10。', '以賽亞書 51:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-39_1-4', '39-1', '以賽亞書(三)40~66 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 40, 66, '出處辨識', '「他們天天尋求我， 樂意明白我的道， 好像行義的國民， 不離棄他們上帝的典章， 向我求問公義的判語， 喜…」的經文出處是哪裡？', '以賽亞書 58:2', '以賽亞書 45:24', '以賽亞書 52:5', '以賽亞書 40:1', 0, '正確內容記載於 以賽亞書 58:2。', '以賽亞書 58:2', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-39_1-5', '39-1', '以賽亞書(三)40~66 章', 'ISA', '以賽亞書', '舊約', 'major_prophets', 40, 66, '經文辨識', '根據《以賽亞書(三)40~66 章》的內容，以下哪一句經文出自這個範圍？', '我必將 埃及人分散在列國，四散在列邦；他們就知道我是耶和華。」', '也不要在安息日從家中擔出擔子去。無論何工都不可做，只要以安息日為聖日，正如我所吩咐你們列祖的。』', '耶和華啊，現在你仍是我們的父！ 我們是泥，你是窯匠； 我們都是你手的工作。', '便雅憫地 亞拿突城的祭司中， 希勒家的兒子 耶利米的話記在下面。', 2, '正確內容記載於 以賽亞書 64:8。', '以賽亞書 64:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-39_2-1', '39-2', '帖撒羅尼迦後書', '2TH', '帖撒羅尼迦後書', '新約', 'pauline', 1, 3, '經文辨識', '根據《帖撒羅尼迦後書》的內容，以下哪一句經文出自這個範圍？', '這正是上帝公義判斷的明證，叫你們可算配得上帝的國；你們就是為這國受苦。', '似乎憂愁，卻是常常快樂的；似乎貧窮，卻是叫許多人富足的；似乎一無所有，卻是樣樣都有的。', '我們藉這愛子的血得蒙救贖，過犯得以赦免，乃是照他豐富的恩典。', '我們不願意分外誇口，只要照上帝所量給我們的界限搆到你們那裏。', 0, '正確內容記載於 帖撒羅尼迦後書 1:5。', '帖撒羅尼迦後書 1:5', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-39_2-2', '39-2', '帖撒羅尼迦後書', '2TH', '帖撒羅尼迦後書', '新約', 'pauline', 1, 3, '出處辨識', '「我勸你們：無論有靈、有言語、有冒我名的書信，說主的日子現在到了，不要輕易動心，也不要驚慌。」的經文出處是哪裡？', '帖撒羅尼迦後書 2:7', '帖撒羅尼迦後書 2:17', '帖撒羅尼迦後書 1:11', '帖撒羅尼迦後書 2:2', 3, '正確內容記載於 帖撒羅尼迦後書 2:2。', '帖撒羅尼迦後書 2:2', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-39_2-3', '39-2', '帖撒羅尼迦後書', '2TH', '帖撒羅尼迦後書', '新約', 'pauline', 1, 3, '經文辨識', '根據《帖撒羅尼迦後書》的內容，以下哪一句經文出自這個範圍？', '使一切不信真理、倒喜愛不義的人都被定罪。', '他們那些受割禮的，連自己也不守律法；他們願意你們受割禮，不過要藉着你們的肉體誇口。', '這是甚麼緣故呢？是因為他們不憑着信心求，只憑着行為求；他們正跌在那絆腳石上。', '而且那本來未受割禮的，若能全守律法，豈不是要審判你這有儀文和割禮竟犯律法的人嗎？', 0, '正確內容記載於 帖撒羅尼迦後書 2:12。', '帖撒羅尼迦後書 2:12', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-39_2-4', '39-2', '帖撒羅尼迦後書', '2TH', '帖撒羅尼迦後書', '新約', 'pauline', 1, 3, '出處辨識', '「我們靠主深信，你們現在是遵行我們所吩咐的，後來也必要遵行。」的經文出處是哪裡？', '帖撒羅尼迦後書 1:11', '帖撒羅尼迦後書 3:10', '帖撒羅尼迦後書 3:4', '帖撒羅尼迦後書 2:7', 2, '正確內容記載於 帖撒羅尼迦後書 3:4。', '帖撒羅尼迦後書 3:4', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-39_2-5', '39-2', '帖撒羅尼迦後書', '2TH', '帖撒羅尼迦後書', '新約', 'pauline', 1, 3, '經文辨識', '根據《帖撒羅尼迦後書》的內容，以下哪一句經文出自這個範圍？', '若有人不聽從我們這信上的話，要記下他，不和他交往，叫他自覺羞愧。', '飯後，也照樣拿起杯來，說：「這杯是用我的血所立的新約，你們每逢喝的時候，要如此行，為的是記念我。」', '自己知道那叫主耶穌復活的，也必叫我們與耶穌一同復活，並且叫我們與你們一同站在他面前。', '原來，上帝的忿怒從天上顯明在一切不虔不義的人身上，就是那些行不義阻擋真理的人。', 0, '正確內容記載於 帖撒羅尼迦後書 3:14。', '帖撒羅尼迦後書 3:14', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-40_1-1', '40-1', '耶利米書(一)1~13 章', 'JER', '耶利米書', '舊約', 'major_prophets', 1, 13, '經文辨識', '根據《耶利米書(一)1~13 章》的內容，以下哪一句經文出自這個範圍？', '那日我向他們起誓，必領他們出 埃及地，到我為他們察看的流奶與蜜之地；那地在萬國中是有榮耀的。', '有人聲喊着說： 在曠野預備耶和華的路， 在沙漠地修平我們上帝的道。', '主雖然以艱難給你當餅，以困苦給你當水，你的教師卻不再隱藏；你眼必看見你的教師。', '這事臨到你身上，不是你自招的嗎？ 不是因耶和華－你上帝引你行路的時候， 你離棄他嗎？', 3, '正確內容記載於 耶利米書 2:17。', '耶利米書 2:17', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-40_1-2', '40-1', '耶利米書(一)1~13 章', 'JER', '耶利米書', '舊約', 'major_prophets', 1, 13, '出處辨識', '「先知說：我觀看地， 不料，地是空虛混沌； 我觀看天，天也無光。」的經文出處是哪裡？', '耶利米書 4:23', '耶利米書 10:19', '耶利米書 1:11', '耶利米書 1:7', 0, '正確內容記載於 耶利米書 4:23。', '耶利米書 4:23', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-40_1-3', '40-1', '耶利米書(一)1~13 章', 'JER', '耶利米書', '舊約', 'major_prophets', 1, 13, '經文辨識', '根據《耶利米書(一)1~13 章》的內容，以下哪一句經文出自這個範圍？', '他的氣如漲溢的河水，直漲到頸項， 要用毀滅的篩籮篩淨列國， 並且在眾民的口中必有使人錯行的嚼環。', '人必稱他們為被棄的銀渣， 因為耶和華已經棄掉他們。', '從腳掌到頭頂， 沒有一處完全的， 盡是傷口、青腫，與新打的傷痕， 都沒有收口，沒有纏裹， 也沒有用膏滋潤。', '阿荷利巴啊，主耶和華如此說：「我必激動你先愛而後生疏的人來攻擊你。我必使他們來，在你四圍攻擊你。', 1, '正確內容記載於 耶利米書 6:30。', '耶利米書 6:30', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-40_1-4', '40-1', '耶利米書(一)1~13 章', 'JER', '耶利米書', '舊約', 'major_prophets', 1, 13, '出處辨識', '「耶和華說：「因為這百姓離棄我在他們面前所設立的律法，沒有遵行，也沒有聽從我的話；」的經文出處是哪裡？', '耶利米書 12:12', '耶利米書 5:16', '耶利米書 9:13', '耶利米書 4:25', 2, '正確內容記載於 耶利米書 9:13。', '耶利米書 9:13', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-40_1-5', '40-1', '耶利米書(一)1~13 章', 'JER', '耶利米書', '舊約', 'major_prophets', 1, 13, '經文辨識', '根據《耶利米書(一)1~13 章》的內容，以下哪一句經文出自這個範圍？', '靈就進入我裏面，使我站起來。耶和華對我說：「你進房屋去，將門關上。', '我必扶持 巴比倫王的膀臂，法老的膀臂卻要下垂；我將我的刀交在 巴比倫王手中，他必舉刀攻擊 埃及地，他們就知道我是耶和華。', '耶和華對 以賽亞說：「你和你的兒子 施亞雅述出去，到上池的水溝頭，在漂布地的大路上，去迎接 亞哈斯，', '我的產業向我如林中的獅子， 她發聲攻擊我， 因此我恨惡她。', 3, '正確內容記載於 耶利米書 12:8。', '耶利米書 12:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-40_2-1', '40-2', '耶利米書(二)14~25 章', 'JER', '耶利米書', '舊約', 'major_prophets', 14, 25, '經文辨識', '根據《耶利米書(二)14~25 章》的內容，以下哪一句經文出自這個範圍？', '耶和華說：你棄絕了我， 轉身退後； 因此我伸手攻擊你，毀壞你。 我後悔甚不耐煩。', '我們心中的快樂止息， 跳舞變為悲哀。', '當 烏西雅王崩的那年，我見主坐在高高的寶座上。他的衣裳垂下，遮滿聖殿。', '眾水流過我頭， 我說：我 命斷絕了！', 0, '正確內容記載於 耶利米書 15:6。', '耶利米書 15:6', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-40_2-2', '40-2', '耶利米書(二)14~25 章', 'JER', '耶利米書', '舊約', 'major_prophets', 14, 25, '出處辨識', '「對他們說：『你們這 猶大君王和 猶大眾人，並 耶路撒冷的一切居民，凡從這些門進入的都當聽耶和華的話。」的經文出處是哪裡？', '耶利米書 22:3', '耶利米書 17:20', '耶利米書 20:15', '耶利米書 17:19', 1, '正確內容記載於 耶利米書 17:20。', '耶利米書 17:20', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-40_2-3', '40-2', '耶利米書(二)14~25 章', 'JER', '耶利米書', '舊約', 'major_prophets', 14, 25, '經文辨識', '根據《耶利米書(二)14~25 章》的內容，以下哪一句經文出自這個範圍？', '那時，外人必起來牧放你們的羊群； 外邦人必作你們耕種田地的， 修理葡萄園的。', '並且耶和華救贖的民必歸回， 歌唱來到 錫安； 永樂必歸到他們的頭上； 他們必得着歡喜快樂， 憂愁歎息盡都逃避。', '試驗義人、察看人肺腑心腸的萬軍之耶和華啊， 求你容我見你在他們身上報仇， 因我將我的案件向你稟明了。', '他們對 尼布甲尼撒王說：「願王萬歲！', 2, '正確內容記載於 耶利米書 20:12。', '耶利米書 20:12', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-40_2-4', '40-2', '耶利米書(二)14~25 章', 'JER', '耶利米書', '舊約', 'major_prophets', 14, 25, '出處辨識', '「我必設立照管他們的牧人，牧養他們。他們不再懼怕，不再驚惶，也不缺少一個；這是耶和華說的。」的經文出處是哪裡？', '耶利米書 19:8', '耶利米書 25:6', '耶利米書 23:35', '耶利米書 23:4', 3, '正確內容記載於 耶利米書 23:4。', '耶利米書 23:4', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-40_2-5', '40-2', '耶利米書(二)14~25 章', 'JER', '耶利米書', '舊約', 'major_prophets', 14, 25, '經文辨識', '根據《耶利米書(二)14~25 章》的內容，以下哪一句經文出自這個範圍？', '我又要使歡喜和快樂的聲音，新郎和新婦的聲音，推磨的聲音和燈的亮光，從他們中間止息。', '你們奉上供物使你們兒子經火的時候，仍將一切偶像玷污自己，直到今日嗎？ 以色列家啊，我豈被你們求問嗎？主耶和華說：我指着我的永生起誓，我必不被你們求問。', '他的眾軍高傲，他的心也必自高；他雖使數萬人仆倒，卻不得 常勝。', '你的男丁必倒在刀下； 你的勇士必死在陣上。', 0, '正確內容記載於 耶利米書 25:10。', '耶利米書 25:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-41-1', '41', '耶利米書(三)26~45 章', 'JER', '耶利米書', '舊約', 'major_prophets', 26, 45, '經文辨識', '根據《耶利米書(三)26~45 章》的內容，以下哪一句經文出自這個範圍？', '當年，就是 猶大王 西底家登基第四年五月， 基遍人 押朔的兒子，先知 哈拿尼雅，在耶和華的殿中當着祭司和眾民對我說：', '主耶和華說：你們要知道，我這樣行不是為你們。 以色列家啊，當為自己的行為抱愧蒙羞。', '因為，你們必如葉子枯乾的橡樹， 好像無水 澆灌的園子。', '必有寶座因慈愛堅立； 必有一位誠誠實實坐在其上， 在 大衛帳幕中施行審判， 尋求公平，速行公義。', 0, '正確內容記載於 耶利米書 28:1。', '耶利米書 28:1', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-41-2', '41', '耶利米書(三)26~45 章', 'JER', '耶利米書', '舊約', 'major_prophets', 26, 45, '出處辨識', '「背道的民哪， 你反來覆去要到幾時呢？ 耶和華在地上造了一件新事， 就是女子護衛男子。」的經文出處是哪裡？', '耶利米書 26:7', '耶利米書 31:22', '耶利米書 26:17', '耶利米書 41:2', 1, '正確內容記載於 耶利米書 31:22。', '耶利米書 31:22', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-41-3', '41', '耶利米書(三)26~45 章', 'JER', '耶利米書', '舊約', 'major_prophets', 26, 45, '經文辨識', '根據《耶利米書(三)26~45 章》的內容，以下哪一句經文出自這個範圍？', '當那日，主必二次伸手救回自己百姓中所餘剩的，就是在 亞述、 埃及、 巴忒羅、 古實、 以攔、 示拿、 哈馬，並眾海島所剩下的。', '耶和華啊，求你醫治我，我便痊癒， 拯救我，我便得救； 因你是我所讚美的。', '西底家王與 耶路撒冷的眾民立約，要向他們宣告自由，叫各人任他 希伯來的僕人和婢女自由出去，誰也不可使他的一個 猶大弟兄作奴僕。（此後，有耶和華的話臨到…', '那時我觀看，見那獸因小角說誇大話的聲音被殺，身體損壞，扔在火中焚燒。', 2, '正確內容記載於 耶利米書 34:8–9。', '耶利米書 34:8–9', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-41-4', '41', '耶利米書(三)26~45 章', 'JER', '耶利米書', '舊約', 'major_prophets', 26, 45, '出處辨識', '「主－我的王啊，這些人向先知 耶利米一味地行惡，將他下在牢獄中；他在那裏必因飢餓而死，因為城中再沒有糧…」的經文出處是哪裡？', '耶利米書 41:10', '耶利米書 26:23', '耶利米書 32:40', '耶利米書 38:9', 3, '正確內容記載於 耶利米書 38:9。', '耶利米書 38:9', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-41-5', '41', '耶利米書(三)26~45 章', 'JER', '耶利米書', '舊約', 'major_prophets', 26, 45, '經文辨識', '根據《耶利米書(三)26~45 章》的內容，以下哪一句經文出自這個範圍？', '耶利米向眾百姓說完了耶和華－他們上帝的一切話，就是耶和華－他們上帝差遣他去所說的一切話。', '主輕棄我中間的一切勇士， 招聚多人攻擊我， 要壓碎我的少年人。 主將 猶大居民踹下， 像在酒醡中一樣。', '雖然如此，我卻為我名的緣故縮手沒有這樣行，免得我的名在我領他們出 埃及的列國人眼前被褻瀆。', '主使一言入於 雅各 家， 落於 以色列 家。', 0, '正確內容記載於 耶利米書 43:1。', '耶利米書 43:1', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_1-1', '42-1', '耶利米書(四)46~52 章', 'JER', '耶利米書', '舊約', 'major_prophets', 46, 52, '經文辨識', '根據《耶利米書(四)46~52 章》的內容，以下哪一句經文出自這個範圍？', '「那聚集到你這裏的各隊都當準備；你自己也要準備，作他們的大帥。', '我的僕人 雅各啊，不要懼怕！ 以色列啊，不要驚惶！ 因我要從遠方拯救你， 從被擄到之地拯救你的後裔。 雅各必回來，得享平靖安逸， 無人使他害怕。', '但以理在王面前回答說：「你的贈品可以歸你自己，你的賞賜可以歸給別人；我卻要為王讀這文字，把講解告訴王。', '主－我們的上帝啊，你曾用大能的手領你的子民出 埃及地，使自己得了名，正如今日一樣。我們犯了罪，作了惡。', 1, '正確內容記載於 耶利米書 46:27。', '耶利米書 46:27', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_1-2', '42-1', '耶利米書(四)46~52 章', 'JER', '耶利米書', '舊約', 'major_prophets', 46, 52, '出處辨識', '「躲避的人無力站在 希實本的影下； 因為有火從 希實本發出， 有火焰出於 西宏 的城， 燒盡 摩押的角和…」的經文出處是哪裡？', '耶利米書 48:45', '耶利米書 50:8', '耶利米書 51:56', '耶利米書 50:33', 0, '正確內容記載於 耶利米書 48:45。', '耶利米書 48:45', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_1-3', '42-1', '耶利米書(四)46~52 章', 'JER', '耶利米書', '舊約', 'major_prophets', 46, 52, '經文辨識', '根據《耶利米書(四)46~52 章》的內容，以下哪一句經文出自這個範圍？', '當 烏西雅、 約坦、 亞哈斯、 希西家作 猶大王的時候， 亞摩斯的兒子 以賽亞得默示，論到 猶大和 耶路撒冷。', '耶和華也必時常引導你， 在乾旱之地使你心滿意足， 骨頭強壯。 你必像澆灌的園子， 又像水流不絕的泉源。', '耶和華必然等候，要施恩給你們； 必然興起，好憐憫你們。 因為耶和華是公平的上帝； 凡等候他的都是有福的！', '你們的母 巴比倫就極其抱愧， 生你們的必然蒙羞。 她要列在諸國之末， 成為曠野、旱地、沙漠。', 3, '正確內容記載於 耶利米書 50:12。', '耶利米書 50:12', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_1-4', '42-1', '耶利米書(四)46~52 章', 'JER', '耶利米書', '舊約', 'major_prophets', 46, 52, '出處辨識', '「雅各的分不像這些， 因他是造作萬有的 主； 以色列也是他產業的支派。 萬軍之耶和華是他的名。」的經文出處是哪裡？', '耶利米書 46:6', '耶利米書 49:20', '耶利米書 51:19', '耶利米書 50:9', 2, '正確內容記載於 耶利米書 51:19。', '耶利米書 51:19', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_1-5', '42-1', '耶利米書(四)46~52 章', 'JER', '耶利米書', '舊約', 'major_prophets', 46, 52, '經文辨識', '根據《耶利米書(四)46~52 章》的內容，以下哪一句經文出自這個範圍？', '你們卻要事奉耶和華－你們的上帝和我為你們所要興起的王 大衛。」', '迦勒底的軍隊追趕 西底家王，在 耶利哥的平原追上他。他的全軍都離開他四散了。', '那時，你們必追想你們的惡行和你們不善的作為，就因你們的罪孽和可憎的事厭惡自己。', '但從東方和北方必有消息擾亂他，他就大發烈怒出去，要將多人殺滅淨盡。', 1, '正確內容記載於 耶利米書 52:8。', '耶利米書 52:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_2-1', '42-2', '耶利米哀歌', 'LAM', '耶利米哀歌', '舊約', 'major_prophets', 1, 5, '經文辨識', '根據《耶利米哀歌》的內容，以下哪一句經文出自這個範圍？', '主輕棄我中間的一切勇士， 招聚多人攻擊我， 要壓碎我的少年人。 主將 猶大居民踹下， 像在酒醡中一樣。', '吝嗇人所用的法子是惡的； 他圖謀惡計， 用謊言毀滅謙卑人； 窮乏人講公理的時候， 他也是這樣行。', '主耶和華如此說：「我將分散在萬民中的 以色列家招聚回來，向他們在列邦人眼前顯為聖的時候，他們就在我賜給我僕人 雅各之地，仍然居住。', '而且你們行惡比你們列祖更甚；因為各人隨從自己頑梗的惡心行事，甚至不聽從我，', 0, '正確內容記載於 耶利米哀歌 1:15。', '耶利米哀歌 1:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_2-2', '42-2', '耶利米哀歌', 'LAM', '耶利米哀歌', '舊約', 'major_prophets', 1, 5, '出處辨識', '「我是因耶和華忿怒的杖， 遭遇困苦的人。」的經文出處是哪裡？', '耶利米哀歌 3:51', '耶利米哀歌 3:29', '耶利米哀歌 1:2', '耶利米哀歌 3:1', 3, '正確內容記載於 耶利米哀歌 3:1。', '耶利米哀歌 3:1', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_2-3', '42-2', '耶利米哀歌', 'LAM', '耶利米哀歌', '舊約', 'major_prophets', 1, 5, '經文辨識', '根據《耶利米哀歌》的內容，以下哪一句經文出自這個範圍？', '他們各人欺哄鄰舍，不說真話； 他們教舌頭學習說謊， 勞勞碌碌地作孽。', '「我使你敗亡 的風聲傳到你所不認識的各國。那時，我必使多民的心因你愁煩。', '或在人的訟事上顛倒是非， 這都是主看不上的。', '磚 牆塌了，我們卻要鑿石頭建築； 桑樹砍了，我們卻要換香柏樹。', 2, '正確內容記載於 耶利米哀歌 3:36。', '耶利米哀歌 3:36', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_2-4', '42-2', '耶利米哀歌', 'LAM', '耶利米哀歌', '舊約', 'major_prophets', 1, 5, '出處辨識', '「你要發怒追趕他們， 從耶和華的天下除滅他們。」的經文出處是哪裡？', '耶利米哀歌 1:19', '耶利米哀歌 3:66', '耶利米哀歌 1:1', '耶利米哀歌 3:27', 1, '正確內容記載於 耶利米哀歌 3:66。', '耶利米哀歌 3:66', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_2-5', '42-2', '耶利米哀歌', 'LAM', '耶利米哀歌', '舊約', 'major_prophets', 1, 5, '經文辨識', '根據《耶利米哀歌》的內容，以下哪一句經文出自這個範圍？', '奴僕轄制我們， 無人救我們脫離他們的手。', '拉伯沙基對他們說：「你們去告訴 希西家說， 亞述大王如此說：『你所倚靠的有甚麼可仗賴的呢？', '這些人所見的是虛假，是謊詐的占卜。他們說是耶和華說的，其實耶和華並沒有差遣他們，他們倒使人指望那話必然立定。', '他身體如水蒼玉，面貌如閃電，眼目如火把，手和腳如光明的銅，說話的聲音如大眾的聲音。', 0, '正確內容記載於 耶利米哀歌 5:8。', '耶利米哀歌 5:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_3-1', '42-3', '提摩太前書', '1TI', '提摩太前書', '新約', 'pauline', 1, 6, '經文辨識', '根據《提摩太前書》的內容，以下哪一句經文出自這個範圍？', '所以 經上說： 他升上高天的時候，擄掠了仇敵， 將各樣的恩賜賞給人。 （', '我們可惹主的憤恨嗎？我們比他還有能力嗎？', '無知的人哪，你所種的，若不死就不能生。', '這是照着可稱頌之上帝交託我榮耀福音說的。', 3, '正確內容記載於 提摩太前書 1:11。', '提摩太前書 1:11', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_3-2', '42-3', '提摩太前書', '1TI', '提摩太前書', '新約', 'pauline', 1, 6, '出處辨識', '「且不是 亞當被引誘，乃是女人被引誘，陷在罪裏。」的經文出處是哪裡？', '提摩太前書 3:10', '提摩太前書 6:4', '提摩太前書 2:14', '提摩太前書 1:13', 2, '正確內容記載於 提摩太前書 2:14。', '提摩太前書 2:14', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_3-3', '42-3', '提摩太前書', '1TI', '提摩太前書', '新約', 'pauline', 1, 6, '經文辨識', '根據《提摩太前書》的內容，以下哪一句經文出自這個範圍？', '各人的工程必然顯露，因為那日子要將它表明出來，有火發現；這火要試驗各人的工程怎樣。', '都因上帝的道和人的祈求成為聖潔了。', '弟兄們，我不願意你們不曉得，我們的祖宗從前都在雲下，都從海中經過，', '智慧人在哪裏？文士在哪裏？這世上的辯士在哪裏？上帝豈不是叫這世上的智慧變成愚拙嗎？', 1, '正確內容記載於 提摩太前書 4:5。', '提摩太前書 4:5', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_3-4', '42-3', '提摩太前書', '1TI', '提摩太前書', '新約', 'pauline', 1, 6, '出處辨識', '「她們被定罪，是因廢棄了當初所許的願；」的經文出處是哪裡？', '提摩太前書 5:12', '提摩太前書 1:19', '提摩太前書 5:23', '提摩太前書 5:19', 0, '正確內容記載於 提摩太前書 5:12。', '提摩太前書 5:12', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-42_3-5', '42-3', '提摩太前書', '1TI', '提摩太前書', '新約', 'pauline', 1, 6, '經文辨識', '根據《提摩太前書》的內容，以下哪一句經文出自這個範圍？', '弟兄們，這卻怎麼樣呢？你們聚會的時候，各人或有詩歌，或有教訓，或有啟示，或有方言，或有翻出來的話，凡事都當造就人。', '我若用方言禱告，是我的靈禱告，但我的悟性沒有果效。', '你這人哪，你論斷行這樣事的人，自己所行的卻和別人一樣，你以為能逃脫上帝的審判嗎？', '但你這屬上帝的人要逃避這些事，追求公義、敬虔、信心、愛心、忍耐、溫柔。', 3, '正確內容記載於 提摩太前書 6:11。', '提摩太前書 6:11', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-43_1-1', '43-1', '以西結書(一)1~12 章', 'EZK', '以西結書', '舊約', 'major_prophets', 1, 12, '經文辨識', '根據《以西結書(一)1~12 章》的內容，以下哪一句經文出自這個範圍？', '在他們頭以上的穹蒼之上有聲音。他們站住的時候，便將翅膀垂下。', '耶和華說：「我指着自己起誓， 波斯拉必令人驚駭、羞辱、咒詛，並且荒涼。她的一切城邑必變為永遠的荒場。」', '因為 寧林的水成為乾涸， 青草枯乾，嫩草滅沒， 青綠之物，一無所有。', '當那日， 亞述王要在 挪伯歇兵， 向 錫安女子的山－ 就是 耶路撒冷的山－掄手 攻他。', 0, '正確內容記載於 以西結書 1:25。', '以西結書 1:25', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-43_1-2', '43-1', '以西結書(一)1~12 章', 'EZK', '以西結書', '舊約', 'major_prophets', 1, 12, '出處辨識', '「你要露出膀臂，面向被困的 耶路撒冷，說預言攻擊這城。」的經文出處是哪裡？', '以西結書 8:1', '以西結書 12:2', '以西結書 3:13', '以西結書 4:7', 3, '正確內容記載於 以西結書 4:7。', '以西結書 4:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-43_1-3', '43-1', '以西結書(一)1~12 章', 'EZK', '以西結書', '舊約', 'major_prophets', 1, 12, '經文辨識', '根據《以西結書(一)1~12 章》的內容，以下哪一句經文出自這個範圍？', '當那日，在 猶大地人必唱這歌 說： 我們有堅固的城。 耶和華要將救恩定為城牆，為外郭。', '我向耶和華－我的上帝祈禱、認罪，說：「主啊，大而可畏的上帝，向愛主、守主誡命的人守約施慈愛。', '我快要將我的忿怒傾在你身上，向你成就我怒中所定的，按你的行為審判你，照你一切可憎的事刑罰你。', '又將他樹林和肥田的榮耀全然燒盡， 好像拿軍旗的昏過去一樣。', 2, '正確內容記載於 以西結書 7:8。', '以西結書 7:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-43_1-4', '43-1', '以西結書(一)1~12 章', 'EZK', '以西結書', '舊約', 'major_prophets', 1, 12, '出處辨識', '「那穿細麻衣、腰間帶着墨盒子的人將這事回覆說：「我已經照你所吩咐的行了。」的經文出處是哪裡？', '以西結書 3:3', '以西結書 9:11', '以西結書 8:17', '以西結書 3:2', 1, '正確內容記載於 以西結書 9:11。', '以西結書 9:11', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-43_1-5', '43-1', '以西結書(一)1~12 章', 'EZK', '以西結書', '舊約', 'major_prophets', 1, 12, '經文辨識', '根據《以西結書(一)1~12 章》的內容，以下哪一句經文出自這個範圍？', '「人子啊，你住在悖逆的家中。他們有眼睛看不見，有耳朵聽不見，因為他們是悖逆之家。', '你們的罪孽使這些事轉離你們； 你們的罪惡使你們不能得福。', '至小的 族要加增千倍； 微弱的國必成為強盛。 我－耶和華要按定期速成這事。', '所以主耶和華如此說：我必使刀劍臨到你，從你中間將人與牲畜剪除。', 0, '正確內容記載於 以西結書 12:2。', '以西結書 12:2', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-43_2-1', '43-2', '以西結書(二)13~24 章', 'EZK', '以西結書', '舊約', 'major_prophets', 13, 24, '經文辨識', '根據《以西結書(二)13~24 章》的內容，以下哪一句經文出自這個範圍？', '譏誚先知的說： 他要將知識指教誰呢？ 要使誰明白傳言呢？ 是那剛斷奶離懷的嗎？', '他們必回答說：『是因離棄了耶和華－他們上帝的約，事奉敬拜別神。』」', '你們當就近我來； 側耳而聽，就必得活。 我必與你們立永約， 就是 應許 大衛那可靠的恩典。', '雖有這三人在其中，主耶和華說：我指着我的永生起誓，他們連兒帶女都不能得救，只能自己得救，那地仍然荒涼。', 3, '正確內容記載於 以西結書 14:16。', '以西結書 14:16', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-43_2-2', '43-2', '以西結書(二)13~24 章', 'EZK', '以西結書', '舊約', 'major_prophets', 13, 24, '出處辨識', '「主耶和華如此說：你這輕看誓言、背棄盟約的，我必照你所行的待你。」的經文出處是哪裡？', '以西結書 22:27', '以西結書 23:29', '以西結書 16:59', '以西結書 24:5', 2, '正確內容記載於 以西結書 16:59。', '以西結書 16:59', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-43_2-3', '43-2', '以西結書(二)13~24 章', 'EZK', '以西結書', '舊約', 'major_prophets', 13, 24, '經文辨識', '根據《以西結書(二)13~24 章》的內容，以下哪一句經文出自這個範圍？', '那時我說：「禍哉！我滅亡了！因為我是嘴唇不潔的人，又住在嘴唇不潔的民中，又因我眼見大君王－萬軍之耶和華。」', '「人子啊，你要告訴 以色列的長老說，主耶和華如此說：你們來是求問我嗎？主耶和華說：我指着我的永生起誓，我必不被你們求問。', '耶和華－你們的上帝未使黑暗來到， 你們的腳未在昏暗山上絆跌之先， 當將榮耀歸給他； 免得你們盼望光明， 他使光明變為死蔭， 成為幽暗。', '頭一個像獅子，有鷹的翅膀；我正觀看的時候，獸的翅膀被拔去，獸從地上得立起來，用兩腳站立，像人一樣，又得了人心。', 1, '正確內容記載於 以西結書 20:3。', '以西結書 20:3', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-43_2-4', '43-2', '以西結書(二)13~24 章', 'EZK', '以西結書', '舊約', 'major_prophets', 13, 24, '出處辨識', '「人子啊，要發預言說：主耶和華論到 亞捫人和他們的凌辱，吩咐我如此說：有刀，有拔出來的刀，已經擦亮，為…」的經文出處是哪裡？', '以西結書 21:28', '以西結書 21:6', '以西結書 13:10', '以西結書 20:44', 0, '正確內容記載於 以西結書 21:28。', '以西結書 21:28', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-43_2-5', '43-2', '以西結書(二)13~24 章', 'EZK', '以西結書', '舊約', 'major_prophets', 13, 24, '經文辨識', '根據《以西結書(二)13~24 章》的內容，以下哪一句經文出自這個範圍？', '以色列人哪，到那日，耶和華必從大河，直到 埃及小河，將你們一一地收集，如同人打樹拾果一樣。', '耶和華如此說： 在 拉瑪聽見號咷痛哭的聲音， 是 拉結哭她兒女，不肯受安慰， 因為他們都不在了。', '偶像是匠人鑄造， 銀匠用金包裹， 為它鑄造銀鍊。', '「況且你們二婦打發使者去請遠方人。使者到他們那裏，他們就來了。你們為他們沐浴己身，粉飾眼目，佩戴妝飾，', 3, '正確內容記載於 以西結書 23:40。', '以西結書 23:40', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-44_1-1', '44-1', '以西結書(三)25~36 章', 'EZK', '以西結書', '舊約', 'major_prophets', 25, 36, '經文辨識', '根據《以西結書(三)25~36 章》的內容，以下哪一句經文出自這個範圍？', '耶和華－我們的上帝啊， 在你以外曾有別的主管轄我們， 但我們專要倚靠你，提你的名。', '並且牠自高自大，以為高及天象之君；除掉常獻給君的 燔祭，毀壞君的聖所。', '於是我開口，他就使我吃這書卷，', '主耶和華對 泰爾如此說：「在你中間行殺戮，受傷之人唉哼的時候，因你傾倒的響聲，海島豈不都震動嗎？', 3, '正確內容記載於 以西結書 26:15。', '以西結書 26:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-44_1-2', '44-1', '以西結書(三)25~36 章', 'EZK', '以西結書', '舊約', 'major_prophets', 25, 36, '出處辨識', '「說主耶和華如此說： 西頓哪，我與你為敵， 我必在你中間得榮耀。 我在你中間施行審判、顯為聖的時候， 人…」的經文出處是哪裡？', '以西結書 28:22', '以西結書 27:17', '以西結書 29:14', '以西結書 27:33', 0, '正確內容記載於 以西結書 28:22。', '以西結書 28:22', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-44_1-3', '44-1', '以西結書(三)25~36 章', 'EZK', '以西結書', '舊約', 'major_prophets', 25, 36, '經文辨識', '根據《以西結書(三)25~36 章》的內容，以下哪一句經文出自這個範圍？', '耶和華如此說：「我必將 猶大王 西底家和他的首領，以及剩在這地 耶路撒冷的餘民，並住在 埃及地的 猶大人都交出來，好像那極壞、壞得不可吃的無花果。', '他必看見自己勞苦的功效， 便心滿意足。 有許多人因認識我的義僕得稱為義； 並且他要擔當他們的罪孽。', '我就必將它交給列國中大有威勢的人；他必定辦它。我因它的罪惡，已經驅逐它。', '你沒有用銀子為我買菖蒲， 也沒有用祭物的脂油使我飽足； 倒使我因你的罪惡服勞， 使我因你的罪孽厭煩。', 2, '正確內容記載於 以西結書 31:11。', '以西結書 31:11', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-44_1-4', '44-1', '以西結書(三)25~36 章', 'EZK', '以西結書', '舊約', 'major_prophets', 25, 36, '出處辨識', '「人子啊，住在 以色列荒廢之地的人說：『 亞伯拉罕獨自一人能得這地為業，我們人數眾多，這地 更是給我們…」的經文出處是哪裡？', '以西結書 33:24', '以西結書 32:18', '以西結書 32:4', '以西結書 28:17', 0, '正確內容記載於 以西結書 33:24。', '以西結書 33:24', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-44_1-5', '44-1', '以西結書(三)25~36 章', 'EZK', '以西結書', '舊約', 'major_prophets', 25, 36, '經文辨識', '根據《以西結書(三)25~36 章》的內容，以下哪一句經文出自這個範圍？', '禍哉！那些以房接房， 以地連地， 以致不留餘地的， 只顧自己獨居境內。', '他又說：「你還要看見他們另外行大可憎的事。」', '我要除淨他們的一切罪，就是向我所犯的罪；又要赦免他們的一切罪，就是干犯我、違背我的罪。', '所以我起誓說：你們四圍的外邦人總要擔當自己的羞辱。這是主耶和華說的。', 3, '正確內容記載於 以西結書 36:7。', '以西結書 36:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-44_2-1', '44-2', '以西結書(四)37~48 章', 'EZK', '以西結書', '舊約', 'major_prophets', 37, 48, '經文辨識', '根據《以西結書(四)37~48 章》的內容，以下哪一句經文出自這個範圍？', '過了多日，你必被差派。到末後之年，你必來到脫離刀劍從列國收回之地，到 以色列常久荒涼的山上；但那從列國中招聚出來的必在其上安然居住。', '當 烏西雅王崩的那年，我見主坐在高高的寶座上。他的衣裳垂下，遮滿聖殿。', '我手已經搆到有偶像的國； 這些國雕刻的偶像 過於 耶路撒冷和 撒馬利亞的偶像。', '你們要查考宣讀耶和華的書。 這都無一缺少， 無一沒有伴偶； 因為我的口已經吩咐， 他的靈將牠們聚集。', 0, '正確內容記載於 以西結書 38:8。', '以西結書 38:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-44_2-2', '44-2', '以西結書(四)37~48 章', 'EZK', '以西結書', '舊約', 'major_prophets', 37, 48, '出處辨識', '「內院有門與這門相對，北面東面都是如此。他從這門量到那門，共一百肘。」的經文出處是哪裡？', '以西結書 38:2', '以西結書 37:2', '以西結書 40:23', '以西結書 39:2', 2, '正確內容記載於 以西結書 40:23。', '以西結書 40:23', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-44_2-3', '44-2', '以西結書(四)37~48 章', 'EZK', '以西結書', '舊約', 'major_prophets', 37, 48, '經文辨識', '根據《以西結書(四)37~48 章》的內容，以下哪一句經文出自這個範圍？', '他用量度的竿量四圍，量東面五百肘，', '吃奶的孩子必玩耍在虺蛇的洞口； 斷奶的嬰兒必按手在毒蛇的穴上。', '那些人就紛紛聚集，見 但以理在他上帝面前祈禱懇求。', '夏瑣必成為野狗的住處， 永遠淒涼； 必無人住在那裏， 也無人在其中寄居。', 0, '正確內容記載於 以西結書 42:16。', '以西結書 42:16', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-44_2-4', '44-2', '以西結書(四)37~48 章', 'EZK', '以西結書', '舊約', 'major_prophets', 37, 48, '出處辨識', '「這地在 以色列中必歸王為業。我所立的王必不再欺壓我的民，卻要按支派將地分給 以色列家。」的經文出處是哪裡？', '以西結書 42:14', '以西結書 38:11', '以西結書 45:3', '以西結書 45:8', 3, '正確內容記載於 以西結書 45:8。', '以西結書 45:8', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-44_2-5', '44-2', '以西結書(四)37~48 章', 'EZK', '以西結書', '舊約', 'major_prophets', 37, 48, '經文辨識', '根據《以西結書(四)37~48 章》的內容，以下哪一句經文出自這個範圍？', '你要在他們眼前挖通了牆，從其中將 物件帶出去。', '我必反手加在你身上， 煉盡你的渣滓， 除淨你的雜質。', '挨着 但的地界，從東到西，是 亞設的一 分。', '如今你們回轉，行我眼中看為正的事，各人向鄰舍宣告自由，並且在稱為我名下的殿中、在我面前立約。', 2, '正確內容記載於 以西結書 48:2。', '以西結書 48:2', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-45_1-1', '45-1', '提摩太後書', '2TI', '提摩太後書', '新約', 'pauline', 1, 4, '經文辨識', '根據《提摩太後書》的內容，以下哪一句經文出自這個範圍？', '上帝救了我們，以聖召召我們，不是按我們的行為，乃是按他的旨意和恩典；這恩典是萬古之先，在基督耶穌裏賜給我們的，', '我在他兒子福音上，用心靈所事奉的上帝可以見證，我怎樣不住地提到你們；', '即便有不信的，這有何妨呢？難道他們的不信就廢掉上帝的信嗎？', '但我們若盼望那所不見的，就必忍耐等候。', 0, '正確內容記載於 提摩太後書 1:9。', '提摩太後書 1:9', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-45_1-2', '45-1', '提摩太後書', '2TI', '提摩太後書', '新約', 'pauline', 1, 4, '出處辨識', '「你要記念耶穌基督乃是 大衛的後裔，他從死裏復活，正合乎我所傳的福音。」的經文出處是哪裡？', '提摩太後書 1:2', '提摩太後書 2:8', '提摩太後書 2:4', '提摩太後書 2:19', 1, '正確內容記載於 提摩太後書 2:8。', '提摩太後書 2:8', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-45_1-3', '45-1', '提摩太後書', '2TI', '提摩太後書', '新約', 'pauline', 1, 4, '經文辨識', '根據《提摩太後書》的內容，以下哪一句經文出自這個範圍？', '我真是苦啊！誰能救我脫離這取死的身體呢？', '我要作你們的父； 你們要作我的兒女。 這是全能的主說的。', '然而主的僕人不可爭競，只要溫溫和和地待眾人，善於教導，存心忍耐，', '要遠避無知的辯論和家譜 的空談，以及紛爭，並因律法而起的爭競，因為這都是虛妄無益的。', 2, '正確內容記載於 提摩太後書 2:24。', '提摩太後書 2:24', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-45_1-4', '45-1', '提摩太後書', '2TI', '提摩太後書', '新約', 'pauline', 1, 4, '出處辨識', '「但你所學習的，所確信的，要存在心裏；因為你知道是跟誰學的，」的經文出處是哪裡？', '提摩太後書 1:8', '提摩太後書 1:4', '提摩太後書 4:10', '提摩太後書 3:14', 3, '正確內容記載於 提摩太後書 3:14。', '提摩太後書 3:14', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-45_1-5', '45-1', '提摩太後書', '2TI', '提摩太後書', '新約', 'pauline', 1, 4, '經文辨識', '根據《提摩太後書》的內容，以下哪一句經文出自這個範圍？', '銅匠 亞歷山大多多地害我；主必照他所行的報應他。', '我大大地放膽，向你們說話；我因你們多多誇口，滿得安慰；我們在一切患難中分外地快樂。', '不要效法這個世界，只要心意更新而變化，叫你們察驗何為上帝的善良、純全、可喜悅的旨意。', '可見，信道是從聽道來的，聽道是從基督的話來的。', 0, '正確內容記載於 提摩太後書 4:14。', '提摩太後書 4:14', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-45_2-1', '45-2', '但以理書(一)1~6 章', 'DAN', '但以理書', '舊約', 'major_prophets', 1, 6, '經文辨識', '根據《但以理書(一)1~6 章》的內容，以下哪一句經文出自這個範圍？', '在王宮的太監 古實人 以伯‧米勒，聽見他們將 耶利米下了牢獄（那時王坐在 便雅憫門口），', '王考問他們一切事，就見他們的智慧聰明比通國的術士和用法術的勝過十倍。', '我將他們四散在列國、分散在列邦的時候，他們就知道我是耶和華。', '他們要建造房屋，自己居住； 栽種葡萄園，吃其中的果子。', 1, '正確內容記載於 但以理書 1:20。', '但以理書 1:20', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-45_2-2', '45-2', '但以理書(一)1~6 章', 'DAN', '但以理書', '舊約', 'major_prophets', 1, 6, '出處辨識', '「凡世人所住之地的走獸，並天空的飛鳥，他都交付你手，使你掌管這一切。你就是那金頭。」的經文出處是哪裡？', '但以理書 1:9', '但以理書 2:28', '但以理書 2:38', '但以理書 2:17', 2, '正確內容記載於 但以理書 2:38。', '但以理書 2:38', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-45_2-3', '45-2', '但以理書(一)1~6 章', 'DAN', '但以理書', '舊約', 'major_prophets', 1, 6, '經文辨識', '根據《但以理書(一)1~6 章》的內容，以下哪一句經文出自這個範圍？', '一切山窪都要填滿， 大小山岡都要削平； 高高低低的要改為平坦， 崎崎嶇嶇的必成為平原。', '我就近一位侍立者，問他這一切的真情。他就告訴我，將那事的講解給我說明：', '王就打發 猶底去拿這書卷來，他便從文士 以利沙瑪的屋內取來，念給王和王左右侍立的眾首領聽。', '尼布甲尼撒說：「 沙得拉、 米煞、 亞伯尼歌的上帝是應當稱頌的！他差遣使者救護倚靠他的僕人，他們不遵王命，捨去己身，在他們上帝以外不肯事奉敬拜別神。', 3, '正確內容記載於 但以理書 3:28。', '但以理書 3:28', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-45_2-4', '45-2', '但以理書(一)1~6 章', 'DAN', '但以理書', '舊約', 'major_prophets', 1, 6, '出處辨識', '「伯沙撒王為他的一千大臣設擺盛筵，與這一千人對面飲酒。」的經文出處是哪裡？', '但以理書 5:1', '但以理書 1:5', '但以理書 3:8', '但以理書 2:43', 0, '正確內容記載於 但以理書 5:1。', '但以理書 5:1', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-45_2-5', '45-2', '但以理書(一)1~6 章', 'DAN', '但以理書', '舊約', 'major_prophets', 1, 6, '經文辨識', '根據《但以理書(一)1~6 章》的內容，以下哪一句經文出自這個範圍？', '主說：我必使孩童作他們的首領， 使嬰孩轄管他們。', '因我本城的眾民， 我的眼，使我的心傷痛。', '王啊，現在求你立這禁令，加蓋玉璽，使禁令決不更改；照 米底亞和 波斯人的例是不可更改的。」', '除非主命定， 誰能說成就成呢？', 2, '正確內容記載於 但以理書 6:8。', '但以理書 6:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_1-1', '46-1', '但以理書(二)7~12 章', 'DAN', '但以理書', '舊約', 'major_prophets', 7, 12, '經文辨識', '根據《但以理書(二)7~12 章》的內容，以下哪一句經文出自這個範圍？', '我必使 西珥山滿有被殺的人。被刀殺的，必倒在你小山和山谷，並一切的溪水中。', '這四個大獸就是四王將要在世上興起。', '到降罰的日子，有災禍從遠方臨到， 那時，你們怎樣行呢？ 你們向誰逃奔求救呢？ 你們的榮耀存留何處呢？', '但我對你說話的時候，必使你開口，你就要對他們說：『主耶和華如此說。』聽的可以聽，不聽的任他不聽，因為他們是悖逆之家。」', 1, '正確內容記載於 但以理書 7:17。', '但以理書 7:17', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_1-2', '46-1', '但以理書(二)7~12 章', 'DAN', '但以理書', '舊約', 'major_prophets', 7, 12, '出處辨識', '「那公山羊就是 希臘王；兩眼當中的大角就是頭一王。」的經文出處是哪裡？', '但以理書 8:21', '但以理書 7:10', '但以理書 11:4', '但以理書 10:8', 0, '正確內容記載於 但以理書 8:21。', '但以理書 8:21', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_1-3', '46-1', '但以理書(二)7~12 章', 'DAN', '但以理書', '舊約', 'major_prophets', 7, 12, '經文辨識', '根據《但以理書(二)7~12 章》的內容，以下哪一句經文出自這個範圍？', '所以，地被咒詛吞滅； 住在其上的顯為有罪。 地上的居民被火焚燒， 剩下的人稀少。', '論到那在耶和華殿中和 猶大王宮內，並 耶路撒冷剩下的器皿，萬軍之耶和華－ 以色列的上帝如此說：', '看哪，主－萬軍之耶和華 以驚嚇削去樹枝； 長高的必被砍下， 高大的必被伐倒。', '過了六十二個七，那受膏者必被剪除，一無所有；必有一王的民來毀滅這城和聖所，至終必如洪水沖沒。必有爭戰，一直到底，荒涼的事已經定了。', 3, '正確內容記載於 但以理書 9:26。', '但以理書 9:26', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_1-4', '46-1', '但以理書(二)7~12 章', 'DAN', '但以理書', '舊約', 'major_prophets', 7, 12, '出處辨識', '「南方王必發烈怒，出來與北方王爭戰，擺列大軍；北方王的軍兵必交付他手。」的經文出處是哪裡？', '但以理書 11:11', '但以理書 8:16', '但以理書 7:28', '但以理書 7:24', 0, '正確內容記載於 但以理書 11:11。', '但以理書 11:11', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_1-5', '46-1', '但以理書(二)7~12 章', 'DAN', '但以理書', '舊約', 'major_prophets', 7, 12, '經文辨識', '根據《但以理書(二)7~12 章》的內容，以下哪一句經文出自這個範圍？', '因此耶和華的話臨到 耶利米說：', '他必把持 埃及的金銀財寶和各樣的寶物。 利比亞人和 古實人都必跟從他。', '在他們頭以上的穹蒼之上有寶座的形像，彷彿藍寶石；在寶座形像以上有彷彿人的形狀。', '「這百姓既厭棄 西羅亞緩流的水，喜悅 利汛和 利瑪利的兒子；', 1, '正確內容記載於 但以理書 11:43。', '但以理書 11:43', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_2-1', '46-2', '何西亞書(一)1~7 章', 'HOS', '何西阿書', '舊約', 'minor_prophets', 1, 7, '經文辨識', '根據《何西亞書(一)1~7 章》的內容，以下哪一句經文出自這個範圍？', '猶大人和 以色列人必一同聚集，為自己立一個首領，從這地上去，因為 耶斯列的日子必為大日。', '我必使他們倚靠我，得以堅固； 一舉一動必奉我的名。 這是耶和華說的。', '以法蓮大大惹動 主怒， 所以他流血的罪必歸在他身上。 主必將那因 以法蓮所受的羞辱歸還他。', '伯‧亞文的邱壇－ 就是 以色列取罪 的地方必被毀滅； 荊棘和蒺藜必長在他們的祭壇上。 他們必對大山說：遮蓋我們！ 對小山說：倒在我們身上！', 0, '正確內容記載於 何西阿書 1:11。', '何西阿書 1:11', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_2-2', '46-2', '何西亞書(一)1~7 章', 'HOS', '何西阿書', '舊約', 'minor_prophets', 1, 7, '出處辨識', '「也以誠實聘你歸我，你就必認識 我－耶和華。」的經文出處是哪裡？', '何西阿書 2:14', '何西阿書 2:16', '何西阿書 7:1', '何西阿書 2:20', 3, '正確內容記載於 何西阿書 2:20。', '何西阿書 2:20', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_2-3', '46-2', '何西亞書(一)1~7 章', 'HOS', '何西阿書', '舊約', 'minor_prophets', 1, 7, '經文辨識', '根據《何西亞書(一)1~7 章》的內容，以下哪一句經文出自這個範圍？', '我的民求問木偶， 以為木杖能指示他們； 因為他們的淫心使他們失迷， 他們就行淫離棄上帝， 不守約束，', '但我必用感謝的聲音獻祭與你。 我所許的願，我必償還。 救恩出於耶和華。', '我必震動萬國；萬國的珍寶必都運來，我就使這殿滿了榮耀。這是萬軍之耶和華說的。」', '或者他轉意後悔，留下餘福， 就是留下獻給耶和華－你們上帝的素祭和奠祭， 也未可知。', 0, '正確內容記載於 何西阿書 4:12。', '何西阿書 4:12', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_2-4', '46-2', '何西亞書(一)1~7 章', 'HOS', '何西阿書', '舊約', 'minor_prophets', 1, 7, '出處辨識', '「以法蓮見自己有病， 猶大見自己有傷， 他們就打發人往 亞述去見 耶雷布王， 他卻不能醫治你們， 不能治…」的經文出處是哪裡？', '何西阿書 3:3', '何西阿書 5:13', '何西阿書 1:5', '何西阿書 1:4', 1, '正確內容記載於 何西阿書 5:13。', '何西阿書 5:13', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_2-5', '46-2', '何西亞書(一)1~7 章', 'HOS', '何西阿書', '舊約', 'minor_prophets', 1, 7, '經文辨識', '根據《何西亞書(一)1~7 章》的內容，以下哪一句經文出自這個範圍？', '以色列人必知道降罰的日子臨近， 報應的時候來到。 民說：作先知的是愚昧； 受靈感的是狂妄， 皆因他們多多作孽，大懷怨恨。', '主耶和華的眼目察看這有罪的國， 必將這國從地上滅絕， 卻不將 雅各家滅絕淨盡。 這是耶和華說的。', '眾民也熱如火爐， 燒滅他們的官長。 他們的君王都仆倒而死； 他們中間無一人求告我。', '我們不向 亞述求救， 不騎 埃及的馬， 也不再對我們手所造的說： 你是我們的上帝。 因為孤兒在你－ 耶和華那裏得蒙憐憫。', 2, '正確內容記載於 何西阿書 7:7。', '何西阿書 7:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_3-1', '46-3', '何西亞書(二)8~14 章', 'HOS', '何西阿書', '舊約', 'minor_prophets', 8, 14, '經文辨識', '根據《何西亞書(二)8~14 章》的內容，以下哪一句經文出自這個範圍？', '以法蓮見自己有病， 猶大見自己有傷， 他們就打發人往 亞述去見 耶雷布王， 他卻不能醫治你們， 不能治好你們的傷。', '四圍的列國啊， 你們要速速地來， 一同聚集。 耶和華啊， 求你使你的大能者降臨。', '日頭要變為黑暗，月亮要變為血，這都在耶和華大而可畏的日子未到以前。', '他們雖在列邦中賄買人， 現在我卻要聚集 懲罰他們； 他們因君王和首領所加的重擔日漸衰微。', 3, '正確內容記載於 何西阿書 8:10。', '何西阿書 8:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_3-2', '46-3', '何西亞書(二)8~14 章', 'HOS', '何西阿書', '舊約', 'minor_prophets', 8, 14, '出處辨識', '「耶和華說：他們一切的惡事都在 吉甲； 我在那裏憎惡他們。 因他們所行的惡， 我必從我地上趕出他們去， …」的經文出處是哪裡？', '何西阿書 9:15', '何西阿書 8:9', '何西阿書 12:8', '何西阿書 8:1', 0, '正確內容記載於 何西阿書 9:15。', '何西阿書 9:15', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_3-3', '46-3', '何西亞書(二)8~14 章', 'HOS', '何西阿書', '舊約', 'minor_prophets', 8, 14, '經文辨識', '根據《何西亞書(二)8~14 章》的內容，以下哪一句經文出自這個範圍？', '因你向兄弟 雅各行強暴， 羞愧必遮蓋你， 你也必永遠斷絕。', '先知越發招呼他們， 他們越發走開， 向諸 巴力獻祭， 給雕刻的偶像燒香。', '於是， 何西阿去娶了 滴拉音的女兒 歌篾。這婦人懷孕，給他生了一個兒子。', '我喜愛良善，不喜愛祭祀； 喜愛認識上帝，勝於燔祭。', 1, '正確內容記載於 何西阿書 11:2。', '何西阿書 11:2', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_3-4', '46-3', '何西亞書(二)8~14 章', 'HOS', '何西阿書', '舊約', 'minor_prophets', 8, 14, '出處辨識', '「我已曉諭眾先知， 並且加增默示， 藉先知設立比喻。」的經文出處是哪裡？', '何西阿書 13:2', '何西阿書 13:9', '何西阿書 12:10', '何西阿書 12:2', 2, '正確內容記載於 何西阿書 12:10。', '何西阿書 12:10', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-46_3-5', '46-3', '何西亞書(二)8~14 章', 'HOS', '何西阿書', '舊約', 'minor_prophets', 8, 14, '經文辨識', '根據《何西亞書(二)8~14 章》的內容，以下哪一句經文出自這個範圍？', '主必趕出她， 打敗她海上的權利； 她必被火燒滅。', '耶和華說：「給他起名叫 羅‧阿米；因為你們不作我的子民，我也不作你們的 上帝。」', '耶和華的話臨到 毗土珥的兒子 約珥。', '撒馬利亞必擔當自己的罪， 因為悖逆她的上帝。 她必倒在刀下； 嬰孩必被摔死； 孕婦必被剖開。', 3, '正確內容記載於 何西阿書 13:16。', '何西阿書 13:16', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_1-1', '47-1', '提多書', 'TIT', '提多書', '新約', 'pauline', 1, 3, '經文辨識', '根據《提多書》的內容，以下哪一句經文出自這個範圍？', '我從前留你在 克里特，是要你將那沒有辦完的事都辦整齊了，又照我所吩咐你的，在各城設立長老。', '那感動 彼得、叫他為受割禮之人作使徒的，也感動我，叫我為外邦人作使徒；）', '你稱為 猶太人，又倚靠律法，且指着上帝誇口；', '因為蒙悅納的，不是自己稱許的，乃是主所稱許的。', 0, '正確內容記載於 提多書 1:5。', '提多書 1:5', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_1-2', '47-1', '提多書', 'TIT', '提多書', '新約', 'pauline', 1, 3, '出處辨識', '「不聽 猶太人荒渺的言語和離棄真道之人的誡命。」的經文出處是哪裡？', '提多書 1:11', '提多書 1:2', '提多書 3:14', '提多書 1:14', 3, '正確內容記載於 提多書 1:14。', '提多書 1:14', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_1-3', '47-1', '提多書', 'TIT', '提多書', '新約', 'pauline', 1, 3, '經文辨識', '根據《提多書》的內容，以下哪一句經文出自這個範圍？', '因為死人若不復活，基督也就沒有復活了。', '他們是 希伯來人嗎？我也是。他們是 以色列人嗎？我也是。他們是 亞伯拉罕的後裔嗎？我也是。', '言語純全，無可指責，叫那反對的人，既無處可說我們的不是，便自覺羞愧。', '所經過的路便行殘害暴虐的事。', 2, '正確內容記載於 提多書 2:8。', '提多書 2:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_1-4', '47-1', '提多書', 'TIT', '提多書', '新約', 'pauline', 1, 3, '出處辨識', '「你要提醒眾人，叫他們順服作官的、掌權的，遵他的命，預備行各樣的善事。」的經文出處是哪裡？', '提多書 1:11', '提多書 3:1', '提多書 2:14', '提多書 2:1', 1, '正確內容記載於 提多書 3:1。', '提多書 3:1', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_1-5', '47-1', '提多書', 'TIT', '提多書', '新約', 'pauline', 1, 3, '經文辨識', '根據《提多書》的內容，以下哪一句經文出自這個範圍？', '因為知道這等人已經背道，犯了罪，自己明知不是，還是去做。', '你們這願意在律法以下的人，請告訴我，你們豈沒有聽見律法嗎？', '你們也曉得，我們怎樣勸勉你們，安慰你們，囑咐你們各人，好像父親待自己的兒女一樣，', '我若當日像尋常人，在 以弗所同野獸戰鬥，那於我有甚麼益處呢？若死人不復活， 我們就吃吃喝喝吧！ 因為明天要死了。', 0, '正確內容記載於 提多書 3:11。', '提多書 3:11', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_2-1', '47-2', '約珥書', 'JOL', '約珥書', '舊約', 'minor_prophets', 1, 3, '經文辨識', '根據《約珥書》的內容，以下哪一句經文出自這個範圍？', '大山哪，你算甚麼呢？在 所羅巴伯面前，你必成為平地。他必搬出一塊石頭，安在 殿頂上。人且大聲歡呼說：『願恩惠恩惠歸與這殿！』」', '他的輝煌如同日光； 從他手裏 射出光線， 在其中藏着他的能力。', '他對我說：「這是發出行在遍地上的咒詛。凡偷竊的必按卷上這面的話除滅；凡起 假誓的必按卷上那面的話除滅。', '我的民哪，你當哀號，像處女腰束麻布， 為幼年的丈夫哀號。', 3, '正確內容記載於 約珥書 1:8。', '約珥書 1:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_2-2', '47-2', '約珥書', 'JOL', '約珥書', '舊約', 'minor_prophets', 1, 3, '出處辨識', '「那日是黑暗、幽冥、 密雲、烏黑的日子， 好像晨光鋪滿山嶺。 有一隊蝗蟲又大又強； 從來沒有這樣的， 以…」的經文出處是哪裡？', '約珥書 3:3', '約珥書 3:16', '約珥書 2:2', '約珥書 1:4', 2, '正確內容記載於 約珥書 2:2。', '約珥書 2:2', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_2-3', '47-2', '約珥書', 'JOL', '約珥書', '舊約', 'minor_prophets', 1, 3, '經文辨識', '根據《約珥書》的內容，以下哪一句經文出自這個範圍？', '撒馬利亞必擔當自己的罪， 因為悖逆她的上帝。 她必倒在刀下； 嬰孩必被摔死； 孕婦必被剖開。', '事奉耶和華的祭司 要在廊子和祭壇中間哭泣，說： 耶和華啊，求你顧惜你的百姓， 不要使你的產業受羞辱， 列邦管轄他們。 為何容列國的人說： 「他們的上帝…', '然而，我要因耶和華歡欣， 因救我的上帝喜樂。', '眾山在他以下必消化， 諸谷必崩裂， 如蠟化在火中， 如水沖下山坡。', 1, '正確內容記載於 約珥書 2:17。', '約珥書 2:17', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_2-4', '47-2', '約珥書', 'JOL', '約珥書', '舊約', 'minor_prophets', 1, 3, '出處辨識', '「日頭要變為黑暗，月亮要變為血，這都在耶和華大而可畏的日子未到以前。」的經文出處是哪裡？', '約珥書 2:31', '約珥書 3:20', '約珥書 3:9', '約珥書 1:10', 0, '正確內容記載於 約珥書 2:31。', '約珥書 2:31', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_2-5', '47-2', '約珥書', 'JOL', '約珥書', '舊約', 'minor_prophets', 1, 3, '經文辨識', '根據《約珥書》的內容，以下哪一句經文出自這個範圍？', '因他們的大惡， 伯特利必使你們遭遇如此。 到了黎明， 以色列的王必全然滅絕。', '因為這默示有一定的日期， 快要應驗，並不虛謊。 雖然遲延，還要等候； 因為必然臨到，不再遲延。', '他們雖在列邦中賄買人， 現在我卻要聚集 懲罰他們； 他們因君王和首領所加的重擔日漸衰微。', '開鐮吧！因為莊稼熟了； 踐踏吧！因為酒醡滿了。 酒池盈溢； 他們的罪惡甚大。', 3, '正確內容記載於 約珥書 3:13。', '約珥書 3:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_3-1', '47-3', '阿摩司書', 'AMO', '阿摩司書', '舊約', 'minor_prophets', 1, 9, '經文辨識', '根據《阿摩司書》的內容，以下哪一句經文出自這個範圍？', '歌篾又懷孕生了一個女兒， 耶和華對 何西阿說：「給她起名叫 羅‧路哈瑪；因為我必不再憐憫 以色列家，決不赦免他們。', '在山頂蹦跳的響聲如車輛的響聲， 又如火焰燒碎稭的響聲， 好像強盛的民擺陣預備打仗。', '他們的王和首領必一同被擄去。 這是耶和華說的。', '先知越發招呼他們， 他們越發走開， 向諸 巴力獻祭， 給雕刻的偶像燒香。', 2, '正確內容記載於 阿摩司書 1:15。', '阿摩司書 1:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_3-2', '47-3', '阿摩司書', 'AMO', '阿摩司書', '舊約', 'minor_prophets', 1, 9, '出處辨識', '「我討 以色列罪的日子，也要討 伯特利祭壇的罪； 壇角必被砍下，墜落於地。」的經文出處是哪裡？', '阿摩司書 3:9', '阿摩司書 3:14', '阿摩司書 2:7', '阿摩司書 3:8', 1, '正確內容記載於 阿摩司書 3:14。', '阿摩司書 3:14', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_3-3', '47-3', '阿摩司書', 'AMO', '阿摩司書', '舊約', 'minor_prophets', 1, 9, '經文辨識', '根據《阿摩司書》的內容，以下哪一句經文出自這個範圍？', '要惡惡好善， 在城門口秉公行義； 或者耶和華－萬軍之上帝向 約瑟的餘民施恩。', '水手便懼怕，各人哀求自己的神。他們將船上的貨物拋在海中，為要使船輕些。 約拿已下到底艙，躺臥沉睡。', '他們就大大懼怕，對他說：「你做的是甚麼事呢？」他們已經知道他躲避耶和華，因為他告訴了他們。', '我的民因無知識而滅亡。 你棄掉知識， 我也必棄掉你， 使你不再給我作祭司。 你既忘了你上帝的律法， 我也必忘記你的兒女。', 0, '正確內容記載於 阿摩司書 5:15。', '阿摩司書 5:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_3-4', '47-3', '阿摩司書', 'AMO', '阿摩司書', '舊約', 'minor_prophets', 1, 9, '出處辨識', '「耶和華就後悔說：「這災可以免了。」的經文出處是哪裡？', '阿摩司書 1:14', '阿摩司書 8:9', '阿摩司書 7:4', '阿摩司書 7:3', 3, '正確內容記載於 阿摩司書 7:3。', '阿摩司書 7:3', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_3-5', '47-3', '阿摩司書', 'AMO', '阿摩司書', '舊約', 'minor_prophets', 1, 9, '經文辨識', '根據《阿摩司書》的內容，以下哪一句經文出自這個範圍？', '我看見主站在祭壇旁邊； 他說：你要擊打柱頂，使門檻震動， 打碎柱頂，落在眾人頭上； 所剩下的人，我必用刀殺戮， 無一人能逃避，無一人能逃脫。', '雅各家啊，我必要聚集你們， 必要招聚 以色列剩下的人， 安置在一處，如 波斯拉的羊， 又如草場上的羊群； 因為人數 眾多就必大大喧嘩。', '她必追隨所愛的，卻追不上； 她必尋找他們，卻尋不見， 便說：我要歸回前夫， 因我那時的光景比如今還好。', '且為我的百姓拈鬮，將童子換妓女，賣童女買酒喝。', 0, '正確內容記載於 阿摩司書 9:1。', '阿摩司書 9:1', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_4-1', '47-4', '腓利門書', 'PHM', '腓利門書', '新約', 'pauline', 1, 1, '經文辨識', '根據《腓利門書》的內容，以下哪一句經文出自這個範圍？', '無論是 希臘人、化外人、聰明人、愚拙人，我都欠他們的債，', '願恩惠、平安從上帝我們的父和主耶穌基督歸與你們！', '就如 經上所記： 我要滅絕智慧人的智慧， 廢棄聰明人的聰明。', '我們講的，乃是從前所隱藏、上帝奧祕的智慧，就是上帝在萬世以前預定使我們得榮耀的。', 1, '正確內容記載於 腓利門書 1:3。', '腓利門書 1:3', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_4-2', '47-4', '腓利門書', 'PHM', '腓利門書', '新約', 'pauline', 1, 1, '出處辨識', '「我雖然靠着基督能放膽吩咐你合宜的事，」的經文出處是哪裡？', '腓利門書 1:8', '腓利門書 1:1', '腓利門書 1:3', '腓利門書 1:11', 0, '正確內容記載於 腓利門書 1:8。', '腓利門書 1:8', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_4-3', '47-4', '腓利門書', 'PHM', '腓利門書', '新約', 'pauline', 1, 1, '經文辨識', '根據《腓利門書》的內容，以下哪一句經文出自這個範圍？', '你們作父親的，不要惹兒女的氣，恐怕他們失了志氣。', '這樣，我們可說甚麼呢？律法是罪嗎？斷乎不是！只是非因律法，我就不知何為罪。非律法說「不可起貪心」，我就不知何為貪心。', '如 經上所記：「誇口的，當指着主誇口。」', '我本來有意將他留下，在我為福音所受的捆鎖中替你伺候我。', 3, '正確內容記載於 腓利門書 1:13。', '腓利門書 1:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_4-4', '47-4', '腓利門書', 'PHM', '腓利門書', '新約', 'pauline', 1, 1, '出處辨識', '「他若虧負你，或欠你甚麼，都歸在我的帳上；」的經文出處是哪裡？', '腓利門書 1:18', '腓利門書 1:6', '腓利門書 1:21', '腓利門書 1:19', 0, '正確內容記載於 腓利門書 1:18。', '腓利門書 1:18', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_4-5', '47-4', '腓利門書', 'PHM', '腓利門書', '新約', 'pauline', 1, 1, '經文辨識', '根據《腓利門書》的內容，以下哪一句經文出自這個範圍？', '因為不知道上帝的義，想要立自己的義，就不服上帝的義了。', '為基督耶穌與我同坐監的 以巴弗問你安。', '其中也有你們這蒙召屬耶穌基督的人。', '所以，你們或吃或喝，無論做甚麼，都要為榮耀上帝而行。', 1, '正確內容記載於 腓利門書 1:23。', '腓利門書 1:23', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_5-1', '47-5', '俄巴底亞書', 'OBA', '俄巴底亞書', '舊約', 'minor_prophets', 1, 1, '經文辨識', '根據《俄巴底亞書》的內容，以下哪一句經文出自這個範圍？', '住在山穴中、居所在高處的啊， 你因狂傲自欺， 心裏說：誰能將我拉下地去呢？', '我必將她種在這地。 素不蒙憐憫的，我必憐憫； 本非我民的，我必對他說： 你是我的民； 他必說： 你是我的上帝。」', '「你起來往 尼尼微大城去，向其中的居民呼喊，因為他們的惡達到我面前。」', '看哪，耶和華出令， 大房就被攻破， 小屋就被打裂。', 0, '正確內容記載於 俄巴底亞書 1:3。', '俄巴底亞書 1:3', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_5-2', '47-5', '俄巴底亞書', 'OBA', '俄巴底亞書', '舊約', 'minor_prophets', 1, 1, '出處辨識', '「與你結盟的都送你上路，直到交界； 與你和好的欺騙你，且勝過你； 與你一同吃飯的設下網羅陷害你； 在你心…」的經文出處是哪裡？', '俄巴底亞書 1:13', '俄巴底亞書 1:4', '俄巴底亞書 1:8', '俄巴底亞書 1:7', 3, '正確內容記載於 俄巴底亞書 1:7。', '俄巴底亞書 1:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_5-3', '47-5', '俄巴底亞書', 'OBA', '俄巴底亞書', '舊約', 'minor_prophets', 1, 1, '經文辨識', '根據《俄巴底亞書》的內容，以下哪一句經文出自這個範圍？', '當外人擄掠 雅各的財物， 外邦人進入他的城門， 為 耶路撒冷拈鬮的日子， 你竟站在一旁，像與他們同夥。', '上帝從 提幔而來； 聖者從 巴蘭山臨到。 （細拉） 他的榮光遮蔽諸天； 頌讚充滿大地。', '那日，必是耶和華所知道的，不是白晝，也不是黑夜，到了晚上才有光明。', '願你的手舉起，高過敵人！ 願你的仇敵都被剪除！', 0, '正確內容記載於 俄巴底亞書 1:11。', '俄巴底亞書 1:11', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_5-4', '47-5', '俄巴底亞書', 'OBA', '俄巴底亞書', '舊約', 'minor_prophets', 1, 1, '出處辨識', '「耶和華降罰的日子臨近萬國。 你怎樣行， 他也必照樣向你行； 你的報應必歸到你頭上。」的經文出處是哪裡？', '俄巴底亞書 1:11', '俄巴底亞書 1:15', '俄巴底亞書 1:4', '俄巴底亞書 1:8', 1, '正確內容記載於 俄巴底亞書 1:15。', '俄巴底亞書 1:15', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-47_5-5', '47-5', '俄巴底亞書', 'OBA', '俄巴底亞書', '舊約', 'minor_prophets', 1, 1, '經文辨識', '根據《俄巴底亞書》的內容，以下哪一句經文出自這個範圍？', '城中若吹角，百姓豈不驚恐呢？ 災禍若臨到一城，豈非耶和華所降的嗎？', '耶和華豈喜悅千千的公羊， 或是萬萬的油河嗎？ 我豈可為自己的罪過獻我的長子嗎？ 為心中的罪惡獻我身所生的嗎？', '南地的人必得 以掃山； 高原的人必得 非利士地， 也得 以法蓮地和 撒馬利亞地； 便雅憫人必得 基列。', '耶和華對 何西阿說：「給他起名叫 耶斯列；因為再過片時，我必討 耶戶家在 耶斯列殺人流血的罪，也必使 以色列家的國滅絕。', 2, '正確內容記載於 俄巴底亞書 1:19。', '俄巴底亞書 1:19', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_1-1', '48-1', '約拿書', 'JON', '約拿書', '舊約', 'minor_prophets', 1, 4, '經文辨識', '根據《約拿書》的內容，以下哪一句經文出自這個範圍？', '免得我剝她的衣服， 使她赤體，與才生的時候一樣， 使她如曠野，如乾旱之地， 因渴而死。', '你們被囚而有指望的人都要轉回保障。 我今日說明，我必加倍賜福給你們。', '與我說話的天使對我說：「你要宣告說，萬軍之耶和華如此說：我為 耶路撒冷為 錫安，心裏極其火熱。', '水手便懼怕，各人哀求自己的神。他們將船上的貨物拋在海中，為要使船輕些。 約拿已下到底艙，躺臥沉睡。', 3, '正確內容記載於 約拿書 1:5。', '約拿書 1:5', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_1-2', '48-1', '約拿書', 'JON', '約拿書', '舊約', 'minor_prophets', 1, 4, '出處辨識', '「他們遂將 約拿抬起，拋在海中，海的狂浪就平息了。」的經文出處是哪裡？', '約拿書 4:8', '約拿書 3:6', '約拿書 1:15', '約拿書 1:4', 2, '正確內容記載於 約拿書 1:15。', '約拿書 1:15', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_1-3', '48-1', '約拿書', 'JON', '約拿書', '舊約', 'minor_prophets', 1, 4, '經文辨識', '根據《約拿書》的內容，以下哪一句經文出自這個範圍？', '姦淫和酒，並新酒， 奪去人的心。', '那信奉虛無 之神的人， 離棄憐愛他們的主；', '耶和華對 何西阿說：「給他起名叫 耶斯列；因為再過片時，我必討 耶戶家在 耶斯列殺人流血的罪，也必使 以色列家的國滅絕。', '並問萬軍之耶和華殿中的祭司和先知說：「我歷年以來，在五月間哭泣齋戒，現在還當這樣行嗎？」', 1, '正確內容記載於 約拿書 2:8。', '約拿書 2:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_1-4', '48-1', '約拿書', 'JON', '約拿書', '舊約', 'minor_prophets', 1, 4, '出處辨識', '「他又使人遍告 尼尼微通城，說：「王和大臣有令，人不可嘗甚麼，牲畜、牛羊不可吃草，也不可喝水。」的經文出處是哪裡？', '約拿書 3:7', '約拿書 1:4', '約拿書 2:9', '約拿書 1:11', 0, '正確內容記載於 約拿書 3:7。', '約拿書 3:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_1-5', '48-1', '約拿書', 'JON', '約拿書', '舊約', 'minor_prophets', 1, 4, '經文辨識', '根據《約拿書》的內容，以下哪一句經文出自這個範圍？', '所以你要對 以色列人說，萬軍之耶和華如此說：你們要轉向我，我就轉向你們。這是萬軍之耶和華說的。', '耶和華的使者告誡 約書亞說：', '我的民偏要背道離開我； 眾先知雖然招呼他們歸向至上的 主， 卻無人尊崇 主。', '次日黎明，上帝卻安排一條蟲子咬這蓖麻，以致枯槁。', 3, '正確內容記載於 約拿書 4:7。', '約拿書 4:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_2-1', '48-2', '希伯來書(一)1~7 章', 'HEB', '希伯來書', '新約', 'general_epistles', 1, 7, '經文辨識', '根據《希伯來書(一)1~7 章》的內容，以下哪一句經文出自這個範圍？', '你們必須忍耐，使你們行完了上帝的旨意，就可以得着所應許的。', '各類的走獸、飛禽、昆蟲、水族，本來都可以制伏，也已經被人制伏了；', '所有的天使，上帝從來對哪一個說： 你坐在我的右邊， 等我使你仇敵作你的腳凳？', '我的弟兄們，不要多人作師傅，因為曉得我們要受更重的判斷。', 2, '正確內容記載於 希伯來書 1:13。', '希伯來書 1:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_2-2', '48-2', '希伯來書(一)1~7 章', 'HEB', '希伯來書', '新約', 'general_epistles', 1, 7, '出處辨識', '「聖靈有話說： 你們今日若聽他的話，」的經文出處是哪裡？', '希伯來書 6:11', '希伯來書 7:7', '希伯來書 3:7', '希伯來書 1:4', 2, '正確內容記載於 希伯來書 3:7。', '希伯來書 3:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_2-3', '48-2', '希伯來書(一)1~7 章', 'HEB', '希伯來書', '新約', 'general_epistles', 1, 7, '經文辨識', '根據《希伯來書(一)1~7 章》的內容，以下哪一句經文出自這個範圍？', '我們既然有一位已經升入高天尊榮的大祭司，就是上帝的兒子耶穌，便當持定所承認的道。', '他們因着信，過 紅海如行乾地； 埃及人試着要過去，就被吞滅了。', '基督在創世以前是預先被 上帝知道的，卻在這末世才為你們顯現。', '以諾因着信，被接去，不至於見死，人也找不着他，因為上帝已經把他接去了；只是他被接去以先，已經得了上帝喜悅他的明證。', 0, '正確內容記載於 希伯來書 4:14。', '希伯來書 4:14', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_2-4', '48-2', '希伯來書(一)1~7 章', 'HEB', '希伯來書', '新約', 'general_epistles', 1, 7, '出處辨識', '「因為上帝並非不公義，竟忘記你們所做的工和你們為他名所顯的愛心，就是先前伺候聖徒，如今還是伺候。」的經文出處是哪裡？', '希伯來書 6:16', '希伯來書 7:3', '希伯來書 7:4', '希伯來書 6:10', 3, '正確內容記載於 希伯來書 6:10。', '希伯來書 6:10', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_2-5', '48-2', '希伯來書(一)1~7 章', 'HEB', '希伯來書', '新約', 'general_epistles', 1, 7, '經文辨識', '根據《希伯來書(一)1~7 章》的內容，以下哪一句經文出自這個範圍？', '所以，你們要自卑，服在上帝大能的手下，到了時候，他必叫你們升高。', '人若說「我愛上帝」，卻恨他的弟兄，就是說謊話的；不愛他所看見的弟兄，就不能愛沒有看見的上帝。', '他成為祭司，並不是照屬肉體的條例，乃是照無窮之生命的大能。', '因為公牛和山羊的血，斷不能除罪。', 2, '正確內容記載於 希伯來書 7:16。', '希伯來書 7:16', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_3-1', '48-3', '希伯來書(二)8~13 章', 'HEB', '希伯來書', '新約', 'general_epistles', 8, 13, '經文辨識', '根據《希伯來書(二)8~13 章》的內容，以下哪一句經文出自這個範圍？', '乃是憑着基督的寶血，如同無瑕疵、無玷污的羔羊之血。', '這藉着水和血而來的，就是耶穌基督；不是單用水，乃是用水又用血，', '櫃上面有榮耀基路伯的影罩着施恩座。這幾件我現在不能一一細說。', '論到使者，又說： 上帝以風為使者， 以火焰為僕役；', 2, '正確內容記載於 希伯來書 9:5。', '希伯來書 9:5', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_3-2', '48-3', '希伯來書(二)8~13 章', 'HEB', '希伯來書', '新約', 'general_epistles', 8, 13, '出處辨識', '「凡祭司天天站着事奉 上帝，屢次獻上一樣的祭物，這祭物永不能除罪。」的經文出處是哪裡？', '希伯來書 10:11', '希伯來書 11:26', '希伯來書 10:33', '希伯來書 13:22', 0, '正確內容記載於 希伯來書 10:11。', '希伯來書 10:11', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_3-3', '48-3', '希伯來書(二)8~13 章', 'HEB', '希伯來書', '新約', 'general_epistles', 8, 13, '經文辨識', '根據《希伯來書(二)8~13 章》的內容，以下哪一句經文出自這個範圍？', '務要在主面前自卑，主就必叫你們升高。', '上帝的道是活潑的，是有功效的，比一切兩刃的劍更快，甚至魂與靈，骨節與骨髓，都能刺入、剖開，連心中的思念和主意都能辨明。', '看哪，船隻雖然甚大，又被大風催逼，只用小小的舵，就隨着掌舵的意思轉動。', '挪亞因着信，既蒙 上帝指示他未見的事，動了敬畏的心，預備了一隻方舟，使他全家得救。因此就定了那世代的罪，自己也承受了那從信而來的義。', 3, '正確內容記載於 希伯來書 11:7。', '希伯來書 11:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_3-4', '48-3', '希伯來書(二)8~13 章', 'HEB', '希伯來書', '新約', 'general_epistles', 8, 13, '出處辨識', '「我們既有這許多的見證人，如同雲彩圍着我們，就當放下各樣的重擔，脫去容易纏累我們的罪，存心忍耐，奔那擺在…」的經文出處是哪裡？', '希伯來書 11:18', '希伯來書 9:20', '希伯來書 12:1', '希伯來書 9:11', 2, '正確內容記載於 希伯來書 12:1。', '希伯來書 12:1', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-48_3-5', '48-3', '希伯來書(二)8~13 章', 'HEB', '希伯來書', '新約', 'general_epistles', 8, 13, '經文辨識', '根據《希伯來書(二)8~13 章》的內容，以下哪一句經文出自這個範圍？', '原來我們在許多事上都有過失；若有人在話語上沒有過失，他就是完全人，也能勒住自己的全身。', '耶穌基督昨日、今日、一直到永遠，是一樣的。', '獨有 麥基洗德，不與他們同譜，倒收納 亞伯拉罕的十分之一，為那蒙應許的 亞伯拉罕祝福。', '你們若因犯罪受責打，能忍耐，有甚麼可誇的呢？但你們若因行善受苦，能忍耐，這在上帝看是可喜愛的。', 1, '正確內容記載於 希伯來書 13:8。', '希伯來書 13:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_1-1', '49-1', '彌迦書', 'MIC', '彌迦書', '舊約', 'minor_prophets', 1, 7, '經文辨識', '根據《彌迦書》的內容，以下哪一句經文出自這個範圍？', '沙斐的居民哪，你們要赤身蒙羞過去。 撒南的居民不敢出來。 伯‧以薛人的哀哭使你們無處可站。', '然而那些人竭力盪槳，要把船攏岸，卻是不能，因為海浪越發向他們翻騰。', '她從那裏出來，我必賜她葡萄園， 又賜她 亞割谷作為指望的門。 她必在那裏應聲， 與幼年的日子一樣， 與從 埃及地上來的時候相同。', '「眾祭司啊，這誡命是傳給你們的。', 0, '正確內容記載於 彌迦書 1:11。', '彌迦書 1:11', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_1-2', '49-1', '彌迦書', 'MIC', '彌迦書', '舊約', 'minor_prophets', 1, 7, '出處辨識', '「吃我民的肉， 剝他們的皮， 打折他們的骨頭， 分成塊子像要下鍋， 又像釜中的肉。」的經文出處是哪裡？', '彌迦書 1:7', '彌迦書 1:12', '彌迦書 3:3', '彌迦書 1:4', 2, '正確內容記載於 彌迦書 3:3。', '彌迦書 3:3', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_1-3', '49-1', '彌迦書', 'MIC', '彌迦書', '舊約', 'minor_prophets', 1, 7, '經文辨識', '根據《彌迦書》的內容，以下哪一句經文出自這個範圍？', '他們卻不知道耶和華的意念， 也不明白他的籌劃。 他聚集他們，好像把禾捆聚到禾場一樣。', '耶和華對 何西阿說：「給他起名叫 耶斯列；因為再過片時，我必討 耶戶家在 耶斯列殺人流血的罪，也必使 以色列家的國滅絕。', '刀劍必臨到他們的城邑， 毀壞門閂，把人吞滅， 都因他們 隨從自己的計謀。', '我要聚集萬民，帶他們下到 約沙法谷，在那裏施行審判；因為他們將我的百姓，就是我的產業 以色列，分散在列國中，又分取我的地土，', 0, '正確內容記載於 彌迦書 4:12。', '彌迦書 4:12', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_1-4', '49-1', '彌迦書', 'MIC', '彌迦書', '舊約', 'minor_prophets', 1, 7, '出處辨識', '「我的百姓啊，你們當追念 摩押王 巴勒所設的謀 和 比珥的兒子 巴蘭回答他的話， 並你們從 什亭到 吉甲…」的經文出處是哪裡？', '彌迦書 1:16', '彌迦書 1:4', '彌迦書 1:6', '彌迦書 6:5', 3, '正確內容記載於 彌迦書 6:5。', '彌迦書 6:5', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_1-5', '49-1', '彌迦書', 'MIC', '彌迦書', '舊約', 'minor_prophets', 1, 7, '經文辨識', '根據《彌迦書》的內容，以下哪一句經文出自這個範圍？', '瑪革提施的居民哪，你們要哀號， 因為 迦南的商民都滅亡了！ 凡搬運銀子的都被剪除。', '你們說：月朔幾時過去， 我們好賣糧； 安息日幾時過去， 我們好擺開麥子； 賣出用小升斗， 收銀用大戥子， 用詭詐的天平欺哄人，', '那時我的仇敵， 就是曾對我說「耶和華－你上帝在哪裏」的， 他一看見這事就被羞愧遮蓋。 我必親眼見他 遭報； 他必被踐踏，如同街上的泥土。', '若再有人說預言，生他的父母必對他說：『你不得存活，因為你託耶和華的名說假預言。』生他的父母在他說預言的時候，要將他刺透。', 2, '正確內容記載於 彌迦書 7:10。', '彌迦書 7:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_2-1', '49-2', '雅各書', 'JAS', '雅各書', '新約', 'general_epistles', 1, 5, '經文辨識', '根據《雅各書》的內容，以下哪一句經文出自這個範圍？', '又向誰起誓，不容他們進入他的安息呢？豈不是向那些不信從的人嗎？', '故此，當時的世界被水淹沒就消滅了。', '忍受試探的人是有福的，因為他經過試驗以後，必得生命的冠冕；這是 主應許給那些愛他之人的。', '這樣看來，他們不能進入 安息是因為不信的緣故了。', 2, '正確內容記載於 雅各書 1:12。', '雅各書 1:12', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_2-2', '49-2', '雅各書', 'JAS', '雅各書', '新約', 'general_epistles', 1, 5, '出處辨識', '「他們不是褻瀆你們所敬奉的尊名嗎？」的經文出處是哪裡？', '雅各書 2:7', '雅各書 3:17', '雅各書 1:5', '雅各書 1:7', 0, '正確內容記載於 雅各書 2:7。', '雅各書 2:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_2-3', '49-2', '雅各書', 'JAS', '雅各書', '新約', 'general_epistles', 1, 5, '經文辨識', '根據《雅各書》的內容，以下哪一句經文出自這個範圍？', '所以，他在你們信的人就為寶貴，在那不信的人 有話說： 匠人所棄的石頭 已作了房角的頭塊石頭。', '你們不要以外面的辮頭髮，戴金飾，穿美衣為妝飾，', '並且可說那受十分之一的 利未，也是藉着 亞伯拉罕納了十分之一。', '原來我們在許多事上都有過失；若有人在話語上沒有過失，他就是完全人，也能勒住自己的全身。', 3, '正確內容記載於 雅各書 3:2。', '雅各書 3:2', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_2-4', '49-2', '雅各書', 'JAS', '雅各書', '新約', 'general_epistles', 1, 5, '出處辨識', '「你們想經上所說是徒然的嗎？上帝所賜、住在我們裏面的靈，是戀愛至於嫉妒嗎？」的經文出處是哪裡？', '雅各書 4:5', '雅各書 2:5', '雅各書 1:27', '雅各書 2:23', 0, '正確內容記載於 雅各書 4:5。', '雅各書 4:5', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_2-5', '49-2', '雅各書', 'JAS', '雅各書', '新約', 'general_epistles', 1, 5, '經文辨識', '根據《雅各書》的內容，以下哪一句經文出自這個範圍？', '原來那為萬物所屬、為萬物所本的，要領許多的兒子進榮耀裏去，使救他們的元帥，因受苦難得以完全，本是合宜的。', '再者，上帝使長子到世上來的時候，就說： 上帝的使者都要拜他。', '弟兄們，你們要把那先前奉主名說話的眾先知當作能受苦能忍耐的榜樣。', '所以主指責他的百姓說： 日子將到， 我要與 以色列家和 猶大家另立新約，', 2, '正確內容記載於 雅各書 5:10。', '雅各書 5:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_3-1', '49-3', '那鴻書', 'NAM', '那鴻書', '舊約', 'minor_prophets', 1, 3, '經文辨識', '根據《那鴻書》的內容，以下哪一句經文出自這個範圍？', '大山因他震動； 小山也都消化。 大地在他面前突起； 世界和住在其間的也都如此。', '我必剪除 亞實突的居民和 亞實基倫掌權的， 也必反手攻擊 以革倫。 非利士人所餘剩的必都滅亡。 這是主耶和華說的。', '與你結盟的都送你上路，直到交界； 與你和好的欺騙你，且勝過你； 與你一同吃飯的設下網羅陷害你； 在你心裏毫無聰明。', '不要效法你們列祖。從前的先知呼叫他們說，萬軍之耶和華如此說：『你們要回頭離開你們的惡道惡行。』他們卻不聽，也不順從我。這是耶和華說的。', 0, '正確內容記載於 那鴻書 1:5。', '那鴻書 1:5', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_3-2', '49-3', '那鴻書', 'NAM', '那鴻書', '舊約', 'minor_prophets', 1, 3, '出處辨識', '「耶和華已經出令，指着 尼尼微說： 你名下的人必不留後； 我必從你神的廟中除滅雕刻的偶像和鑄造的偶像； …」的經文出處是哪裡？', '那鴻書 3:10', '那鴻書 1:15', '那鴻書 1:5', '那鴻書 1:14', 3, '正確內容記載於 那鴻書 1:14。', '那鴻書 1:14', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_3-3', '49-3', '那鴻書', 'NAM', '那鴻書', '舊約', 'minor_prophets', 1, 3, '經文辨識', '根據《那鴻書》的內容，以下哪一句經文出自這個範圍？', '尼尼微現在空虛荒涼， 人心消化，雙膝相碰， 腰都疼痛，臉都變色。', '我要忍受耶和華的惱怒； 因我得罪了他， 直等他為我辨屈，為我伸冤。 他必領我到光明中； 我必得見他的公義。', '他又使人遍告 尼尼微通城，說：「王和大臣有令，人不可嘗甚麼，牲畜、牛羊不可吃草，也不可喝水。', '耶和華說：雖然如此， 你們應當禁食、哭泣、悲哀， 一心歸向我。', 0, '正確內容記載於 那鴻書 2:10。', '那鴻書 2:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_3-4', '49-3', '那鴻書', 'NAM', '那鴻書', '舊約', 'minor_prophets', 1, 3, '出處辨識', '「我必將可憎污穢之物拋在你身上， 辱沒你，為眾目所觀。」的經文出處是哪裡？', '那鴻書 1:15', '那鴻書 1:5', '那鴻書 3:6', '那鴻書 1:6', 2, '正確內容記載於 那鴻書 3:6。', '那鴻書 3:6', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_3-5', '49-3', '那鴻書', 'NAM', '那鴻書', '舊約', 'minor_prophets', 1, 3, '經文辨識', '根據《那鴻書》的內容，以下哪一句經文出自這個範圍？', '在那裏，火必燒滅你； 刀必殺戮你， 吞滅你如同蝻子。 任你加增人數多如蝻子， 多如蝗蟲吧！', '因此，他們必如早晨的雲霧， 又如速散的甘露， 像場上的糠詷被狂風吹去， 又像煙氣騰於窗外。', '我必興起 迦勒底人， 就是那殘忍暴躁之民，通行遍地， 佔據那不屬自己的住處。', '然而，人都不必爭辯，也不必指責， 因為這民與抗拒祭司的人一樣。', 0, '正確內容記載於 那鴻書 3:15。', '那鴻書 3:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_4-1', '49-4', '彼得前書', '1PE', '彼得前書', '新約', 'general_epistles', 1, 5, '經文辨識', '根據《彼得前書》的內容，以下哪一句經文出自這個範圍？', '摩西為僕人，在上帝的全家誠然盡忠，為要證明將來必傳說的事。', '但盼望快快地見你，我們就當面談論。', '惟有詳細察看那全備、 使人自由之律法的，並且時常如此，這人既不是聽了就忘，乃是實在行出來，就在他所行的事上必然得福。', '就是考察在他們心裏基督的靈，預先證明基督受苦難，後來得榮耀，是指着甚麼時候，並怎樣的時候。', 3, '正確內容記載於 彼得前書 1:11。', '彼得前書 1:11', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_4-2', '49-4', '彼得前書', '1PE', '彼得前書', '新約', 'general_epistles', 1, 5, '出處辨識', '「所以，他在你們信的人就為寶貴，在那不信的人 有話說： 匠人所棄的石頭 已作了房角的頭塊石頭。」的經文出處是哪裡？', '彼得前書 2:7', '彼得前書 5:2', '彼得前書 1:10', '彼得前書 2:21', 0, '正確內容記載於 彼得前書 2:7。', '彼得前書 2:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_4-3', '49-4', '彼得前書', '1PE', '彼得前書', '新約', 'general_epistles', 1, 5, '經文辨識', '根據《彼得前書》的內容，以下哪一句經文出自這個範圍？', '上帝既在古時藉着眾先知多次多方地曉諭列祖，', '親愛的 弟兄啊，我們現在是上帝的兒女，將來如何，還未顯明；但我們知道，主若顯現，我們必要像他，因為必得見他的真體。', '你們不要以外面的辮頭髮，戴金飾，穿美衣為妝飾，', '因那使人成聖的和那些得以成聖的，都是出於一。所以，他稱他們為弟兄也不以為恥，', 2, '正確內容記載於 彼得前書 3:3。', '彼得前書 3:3', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_4-4', '49-4', '彼得前書', '1PE', '彼得前書', '新約', 'general_epistles', 1, 5, '出處辨識', '「基督既在肉身受苦，你們也當將這樣的心志作為兵器，因為在肉身受過苦的，就已經與罪斷絕了。」的經文出處是哪裡？', '彼得前書 4:1', '彼得前書 1:14', '彼得前書 5:5', '彼得前書 3:13', 0, '正確內容記載於 彼得前書 4:1。', '彼得前書 4:1', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-49_4-5', '49-4', '彼得前書', '1PE', '彼得前書', '新約', 'general_epistles', 1, 5, '經文辨識', '根據《彼得前書》的內容，以下哪一句經文出自這個範圍？', '愛上帝的，也當愛弟兄，這是我們從上帝所受的命令。', '再者， 耶穌為祭司，並不是不起誓立的。', '因為上帝並非不公義，竟忘記你們所做的工和你們為他名所顯的愛心，就是先前伺候聖徒，如今還是伺候。', '到了牧長顯現的時候，你們必得那永不衰殘的榮耀冠冕。', 3, '正確內容記載於 彼得前書 5:4。', '彼得前書 5:4', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_1-1', '50-1', '哈巴谷書', 'HAB', '哈巴谷書', '舊約', 'minor_prophets', 1, 3, '經文辨識', '根據《哈巴谷書》的內容，以下哪一句經文出自這個範圍？', '主耶和華－萬軍之上帝說： 當聽這話，警戒 雅各家。', '禍哉，那些在床上圖謀罪孽、造作奸惡的！ 天一發亮，因手有能力就行出來了。', '他威武可畏， 判斷和勢力都任意發出。', '錫安的民哪，應當歌唱！ 以色列啊，應當歡呼！ 耶路撒冷的民哪，應當滿心歡喜快樂！', 2, '正確內容記載於 哈巴谷書 1:7。', '哈巴谷書 1:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_1-2', '50-1', '哈巴谷書', 'HAB', '哈巴谷書', '舊約', 'minor_prophets', 1, 3, '出處辨識', '「我要站在守望所， 立在望樓上觀看， 看耶和華對我說甚麼話， 我可用甚麼話向他訴冤。」的經文出處是哪裡？', '哈巴谷書 1:5', '哈巴谷書 3:1', '哈巴谷書 1:3', '哈巴谷書 2:1', 3, '正確內容記載於 哈巴谷書 2:1。', '哈巴谷書 2:1', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_1-3', '50-1', '哈巴谷書', 'HAB', '哈巴谷書', '舊約', 'minor_prophets', 1, 3, '經文辨識', '根據《哈巴谷書》的內容，以下哪一句經文出自這個範圍？', '以人血建城、 以罪孽立邑的有禍了！', '耶和華在他軍旅前發聲， 他的隊伍甚大； 成就他命的是強盛者。 因為耶和華的日子大而可畏， 誰能當得起呢？', '萬軍之耶和華說： 刀劍哪，應當興起， 攻擊我的牧人和我的同伴。 擊打牧人，羊就分散； 我必反手加在微小者的身上。', '雅各家啊，我必要聚集你們， 必要招聚 以色列剩下的人， 安置在一處，如 波斯拉的羊， 又如草場上的羊群； 因為人數 眾多就必大大喧嘩。', 0, '正確內容記載於 哈巴谷書 2:12。', '哈巴谷書 2:12', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_1-4', '50-1', '哈巴谷書', 'HAB', '哈巴谷書', '舊約', 'minor_prophets', 1, 3, '出處辨識', '「上帝從 提幔而來； 聖者從 巴蘭山臨到。 （細拉） 他的榮光遮蔽諸天； 頌讚充滿大地。」的經文出處是哪裡？', '哈巴谷書 1:5', '哈巴谷書 3:3', '哈巴谷書 1:3', '哈巴谷書 2:14', 1, '正確內容記載於 哈巴谷書 3:3。', '哈巴谷書 3:3', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_1-5', '50-1', '哈巴谷書', 'HAB', '哈巴谷書', '舊約', 'minor_prophets', 1, 3, '經文辨識', '根據《哈巴谷書》的內容，以下哪一句經文出自這個範圍？', '當那日，人必從 亞述， 從 埃及的城邑， 從 埃及到大河， 從這海到那海， 從這山到那山， 都歸到你這裏。', '當 猶大王 亞們的兒子 約西亞在位的時候，耶和華的話臨到 希西家的玄孫， 亞瑪利雅的曾孫， 基大利的孫子， 古示的兒子 西番雅。', '你用 敵人的戈矛刺透他戰士的頭； 他們來如旋風，要將我們分散。 他們所喜愛的是暗中吞吃貧民。', '萬軍之耶和華說：「銀子是我的，金子也是我的。', 2, '正確內容記載於 哈巴谷書 3:14。', '哈巴谷書 3:14', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_2-1', '50-2', '彼得後書', '2PE', '彼得後書', '新約', 'general_epistles', 1, 3, '經文辨識', '根據《彼得後書》的內容，以下哪一句經文出自這個範圍？', '作上帝和主耶穌基督僕人的 雅各請散住十二個支派之人的安。', '原來前約有禮拜的條例和屬世界的聖幕。', '我更求你們為我禱告，使我快些回到你們那裏去。', '有了虔敬，又要加上愛弟兄的心；有了愛弟兄的心，又要加上愛 眾人的心。', 3, '正確內容記載於 彼得後書 1:7。', '彼得後書 1:7', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_2-2', '50-2', '彼得後書', '2PE', '彼得後書', '新約', 'general_epistles', 1, 3, '出處辨識', '「我們並有先知更確的預言，如同燈照在暗處。你們在這預言上留意，直等到天發亮，晨星在你們心裏出現的時候，才…」的經文出處是哪裡？', '彼得後書 1:19', '彼得後書 3:10', '彼得後書 3:6', '彼得後書 1:15', 0, '正確內容記載於 彼得後書 1:19。', '彼得後書 1:19', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_2-3', '50-2', '彼得後書', '2PE', '彼得後書', '新約', 'general_epistles', 1, 3, '經文辨識', '根據《彼得後書》的內容，以下哪一句經文出自這個範圍？', '人有了 上帝的兒子就有生命，沒有上帝的兒子就沒有生命。', '那些隨肉身、縱污穢的情慾、輕慢主治之人的，更是如此。', '我們用舌頭頌讚那為主、為父的，又用舌頭咒詛那照着上帝形像被造的人。', '我要寬恕他們的不義， 不再記念他們的罪愆。', 1, '正確內容記載於 彼得後書 2:10。', '彼得後書 2:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_2-4', '50-2', '彼得後書', '2PE', '彼得後書', '新約', 'general_epistles', 1, 3, '出處辨識', '「俗語說得真不錯： 狗所吐的，牠轉過來又吃； 豬洗淨了又回到泥裏去滾； 這話在他們身上正合式。」的經文出處是哪裡？', '彼得後書 3:4', '彼得後書 3:12', '彼得後書 2:22', '彼得後書 1:5', 2, '正確內容記載於 彼得後書 2:22。', '彼得後書 2:22', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_2-5', '50-2', '彼得後書', '2PE', '彼得後書', '新約', 'general_epistles', 1, 3, '經文辨識', '根據《彼得後書》的內容，以下哪一句經文出自這個範圍？', '你們又忘了那勸你們如同勸兒子的話，說： 我兒，你不可輕看主的管教， 被他責備的時候也不可灰心；', '就在這末世藉着他兒子曉諭我們；又早已立他為承受萬有的，也曾藉着他創造諸世界。', '你們作妻子的要順服自己的丈夫；這樣，若有不信從道理的丈夫，他們雖然不聽道，也可以因妻子的品行被感化過來；', '切切仰望上帝的日子來到。在那日，天被火燒就銷化了，有形質的都要被烈火鎔化。', 3, '正確內容記載於 彼得後書 3:12。', '彼得後書 3:12', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_3-1', '50-3', '西番雅書', 'ZEP', '西番雅書', '舊約', 'minor_prophets', 1, 3, '經文辨識', '根據《西番雅書》的內容，以下哪一句經文出自這個範圍？', '與那些轉去不跟從耶和華的， 和不尋求耶和華也不訪問他的。', '在我們王 宴樂的日子， 首領因酒的烈性成病； 王與褻慢人拉手。', '我的民因無知識而滅亡。 你棄掉知識， 我也必棄掉你， 使你不再給我作祭司。 你既忘了你上帝的律法， 我也必忘記你的兒女。', '耶和華的日子臨近，你的財物必被搶掠，在你中間分散。', 0, '正確內容記載於 西番雅書 1:6。', '西番雅書 1:6', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_3-2', '50-3', '西番雅書', 'ZEP', '西番雅書', '舊約', 'minor_prophets', 1, 3, '出處辨識', '「是吹角吶喊的日子， 要攻擊堅固城和高大的城樓。」的經文出處是哪裡？', '西番雅書 1:13', '西番雅書 1:16', '西番雅書 3:5', '西番雅書 2:8', 1, '正確內容記載於 西番雅書 1:16。', '西番雅書 1:16', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_3-3', '50-3', '西番雅書', 'ZEP', '西番雅書', '舊約', 'minor_prophets', 1, 3, '經文辨識', '根據《西番雅書》的內容，以下哪一句經文出自這個範圍？', '於是， 何西阿去娶了 滴拉音的女兒 歌篾。這婦人懷孕，給他生了一個兒子。', '以法蓮大大惹動 主怒， 所以他流血的罪必歸在他身上。 主必將那因 以法蓮所受的羞辱歸還他。', '這事臨到他們是因他們驕傲，自誇自大， 毀謗萬軍之耶和華的百姓。', '牠們的形狀如馬， 奔跑如馬兵。', 2, '正確內容記載於 西番雅書 2:10。', '西番雅書 2:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_3-4', '50-3', '西番雅書', 'ZEP', '西番雅書', '舊約', 'minor_prophets', 1, 3, '出處辨識', '「耶和華在她中間是公義的， 斷不做非義的事， 每早晨顯明他的公義，無日不然； 只是不義的人不知羞恥。」的經文出處是哪裡？', '西番雅書 2:13', '西番雅書 3:7', '西番雅書 1:1', '西番雅書 3:5', 3, '正確內容記載於 西番雅書 3:5。', '西番雅書 3:5', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_3-5', '50-3', '西番雅書', 'ZEP', '西番雅書', '舊約', 'minor_prophets', 1, 3, '經文辨識', '根據《西番雅書》的內容，以下哪一句經文出自這個範圍？', '耶和華已經除去你的刑罰， 趕出你的仇敵。 以色列的王－耶和華在你中間； 你必不再懼怕災禍。', '以色列年幼的時候，我愛他， 就從 埃及召出我的兒子來。', '所以在這民中必有鬨嚷之聲， 你一切的保障必被拆毀， 就如 沙勒幔在爭戰的日子拆毀 伯‧亞比勒， 將其中的母子一同摔死。', '眾民也熱如火爐， 燒滅他們的官長。 他們的君王都仆倒而死； 他們中間無一人求告我。', 0, '正確內容記載於 西番雅書 3:15。', '西番雅書 3:15', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_4-1', '50-4', '約翰一書', '1JN', '約翰一書', '新約', 'general_epistles', 1, 5, '經文辨識', '根據《約翰一書》的內容，以下哪一句經文出自這個範圍？', '現今你們竟以張狂誇口；凡這樣誇口都是惡的。', '我小子們哪，我將這些話寫給你們，是要叫你們不犯罪。若有人犯罪，在父那裏我們有一位中保，就是那義者耶穌基督。', '又說：主啊，你起初立了地的根基； 天也是你手所造的。', '各人要照所得的恩賜彼此服事，作上帝百般恩賜的好管家。', 1, '正確內容記載於 約翰一書 2:1。', '約翰一書 2:1', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_4-2', '50-4', '約翰一書', '1JN', '約翰一書', '新約', 'general_epistles', 1, 5, '出處辨識', '「我寫信給你們，不是因你們不知道真理，正是因你們知道，並且知道沒有虛謊是從真理出來的。」的經文出處是哪裡？', '約翰一書 3:1', '約翰一書 3:7', '約翰一書 2:21', '約翰一書 1:1', 2, '正確內容記載於 約翰一書 2:21。', '約翰一書 2:21', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_4-3', '50-4', '約翰一書', '1JN', '約翰一書', '新約', 'general_epistles', 1, 5, '經文辨識', '根據《約翰一書》的內容，以下哪一句經文出自這個範圍？', '為此，就是死人也曾有福音傳給他們，要叫他們的肉體按着人受審判，他們的靈性卻靠上帝活着。', '我們有一祭壇，上面的祭物是那些在帳幕中供職的人不可同吃的。', '惟有詳細察看那全備、 使人自由之律法的，並且時常如此，這人既不是聽了就忘，乃是實在行出來，就在他所行的事上必然得福。', '我們因為愛弟兄，就曉得是已經出死入生了。沒有愛心的，仍住在死中。', 3, '正確內容記載於 約翰一書 3:14。', '約翰一書 3:14', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_4-4', '50-4', '約翰一書', '1JN', '約翰一書', '新約', 'general_epistles', 1, 5, '出處辨識', '「親愛的 弟兄啊，上帝既是這樣愛我們，我們也當彼此相愛。」的經文出處是哪裡？', '約翰一書 4:11', '約翰一書 1:1', '約翰一書 1:7', '約翰一書 2:26', 0, '正確內容記載於 約翰一書 4:11。', '約翰一書 4:11', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_4-5', '50-4', '約翰一書', '1JN', '約翰一書', '新約', 'general_epistles', 1, 5, '經文辨識', '根據《約翰一書》的內容，以下哪一句經文出自這個範圍？', '天使豈不都是服役的靈、奉差遣為那將要承受救恩的人效力嗎？', '他並沒有犯罪，口裏也沒有詭詐。', '這見證就是上帝賜給我們永生；這 永生也是在他兒子裏面。', '願榮耀、威嚴、能力、權柄，因我們的主耶穌基督歸與他，從萬古以前並現今，直到永永遠遠。阿們！', 2, '正確內容記載於 約翰一書 5:11。', '約翰一書 5:11', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_5-1', '50-5', '哈該書', 'HAG', '哈該書', '舊約', 'minor_prophets', 1, 2, '經文辨識', '根據《哈該書》的內容，以下哪一句經文出自這個範圍？', '田野的走獸啊，不要懼怕； 因為，曠野的草發生， 樹木結果， 無花果樹、葡萄樹也都效力。', '到了我－耶和華獻祭的日子， 必懲罰首領和王子， 並一切穿外邦衣服的。', '「這殿仍然荒涼，你們自己還住天花板的房屋嗎？', '所以耶和華如此說：現今我回到 耶路撒冷，仍施憐憫，我的殿必重建在其中，準繩必拉在 耶路撒冷之上。這是萬軍之耶和華說的。', 2, '正確內容記載於 哈該書 1:4。', '哈該書 1:4', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_5-2', '50-5', '哈該書', 'HAG', '哈該書', '舊約', 'minor_prophets', 1, 2, '出處辨識', '「那時， 撒拉鐵的兒子 所羅巴伯和 約撒答的兒子大祭司 約書亞，並剩下的百姓，都聽從耶和華－他們上帝的話…」的經文出處是哪裡？', '哈該書 2:10', '哈該書 2:6', '哈該書 2:4', '哈該書 1:12', 3, '正確內容記載於 哈該書 1:12。', '哈該書 1:12', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_5-3', '50-5', '哈該書', 'HAG', '哈該書', '舊約', 'minor_prophets', 1, 2, '經文辨識', '根據《哈該書》的內容，以下哪一句經文出自這個範圍？', '這是 照着你們出 埃及我與你們立約的話。那時，我的靈住在你們中間，你們不要懼怕。」', '田野的走獸啊，不要懼怕； 因為，曠野的草發生， 樹木結果， 無花果樹、葡萄樹也都效力。', '「我必將那施恩叫人懇求的靈，澆灌 大衛家和 耶路撒冷的居民。他們必仰望我，就是他們所扎的；必為我悲哀，如喪獨生子，又為我愁苦，如喪長子。', '你們要與你們的母親大大爭辯； 因為她不是我的妻子， 我也不是她的丈夫。 叫她除掉臉上的淫像 和胸間的淫態，', 0, '正確內容記載於 哈該書 2:5。', '哈該書 2:5', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_5-4', '50-5', '哈該書', 'HAG', '哈該書', '舊約', 'minor_prophets', 1, 2, '出處辨識', '「說：若有人用衣襟兜聖肉，這衣襟挨着餅，或湯，或酒，或油，或別的食物，便算為聖嗎？」祭司說：「不算為聖。」的經文出處是哪裡？', '哈該書 1:1', '哈該書 1:13', '哈該書 2:12', '哈該書 1:7', 2, '正確內容記載於 哈該書 2:12。', '哈該書 2:12', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_5-5', '50-5', '哈該書', 'HAG', '哈該書', '舊約', 'minor_prophets', 1, 2, '經文辨識', '根據《哈該書》的內容，以下哪一句經文出自這個範圍？', '這月二十四日，耶和華的話二次臨到 哈該說：', '因此，我必用荊棘堵塞她的道， 築牆擋住她， 使她找不着路。', '以色列啊，日子必到， 你的牆垣必重修； 到那日，你的境界必開展。', '伯利恆的 以法他啊， 你在 猶大諸城中為小， 將來必有一位從你那裏出來， 在 以色列中為我作掌權的； 他的根源從亙古，從太初就有。', 0, '正確內容記載於 哈該書 2:20。', '哈該書 2:20', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_6-1', '50-6', '約翰二書&約翰三書', '2JN,3JN', '約翰二書、約翰三書', '新約', 'general_epistles', 1, 1, '經文辨識', '根據《約翰二書&約翰三書》的內容，以下哪一句經文出自這個範圍？', '叫萬物都服在他的腳下。 既叫萬物都服他，就沒有剩下一樣不服他的。只是如今我們還不見萬物都服他。', '天地都要滅沒，你卻要長存。 天地都要像衣服漸漸舊了；', '因為經上說： 看哪，我把所揀選、 所寶貴的房角石安放在 錫安； 信靠他的人必不至於羞愧。', '恩惠、憐憫、平安從父上帝和他兒子耶穌基督在真理和愛心上必常與我們同在！', 3, '正確內容記載於 約翰二書 1:3。', '約翰二書 1:3', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_6-2', '50-6', '約翰二書&約翰三書', '2JN,3JN', '約翰二書、約翰三書', '新約', 'general_epistles', 1, 1, '出處辨識', '「凡越過基督的教訓不常守着的，就沒有上帝；常守這教訓的，就有父又有子。」的經文出處是哪裡？', '約翰二書 1:9', '約翰二書 1:4', '約翰二書 1:10', '約翰二書 1:2', 0, '正確內容記載於 約翰二書 1:9。', '約翰二書 1:9', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_6-3', '50-6', '約翰二書&約翰三書', '2JN,3JN', '約翰二書、約翰三書', '新約', 'general_epistles', 1, 1, '經文辨識', '根據《約翰二書&約翰三書》的內容，以下哪一句經文出自這個範圍？', '亞伯拉罕因着信，蒙召的時候就遵命出去，往將來要得為業的地方去；出去的時候，還不知往哪裏去。', '滅了烈火的猛勢，脫了刀劍的鋒刃；軟弱變為剛強，爭戰顯出勇敢，打退外邦的全軍。', '親愛的 兄弟啊，我願你凡事興盛，身體健壯，正如你的靈魂興盛一樣。', '因為還有一點點時候， 那要來的就來，並不遲延；', 2, '正確內容記載於 約翰三書 1:2。', '約翰三書 1:2', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_6-4', '50-6', '約翰二書&約翰三書', '2JN,3JN', '約翰二書、約翰三書', '新約', 'general_epistles', 1, 1, '出處辨識', '「因他們是為主的名出外，對於外邦人一無所取。」的經文出處是哪裡？', '約翰三書 1:3', '約翰三書 1:9', '約翰三書 1:7', '約翰二書 1:6', 2, '正確內容記載於 約翰三書 1:7。', '約翰三書 1:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-50_6-5', '50-6', '約翰二書&約翰三書', '2JN,3JN', '約翰二書、約翰三書', '新約', 'general_epistles', 1, 1, '經文辨識', '根據《約翰二書&約翰三書》的內容，以下哪一句經文出自這個範圍？', '並新約的中保耶穌，以及所灑的血；這血所說的比 亞伯的血所說的更美。', '小子們哪，我寫信給你們， 因為你們的罪藉着主名得了赦免。', '也要離惡行善， 尋求和睦，一心追趕。', '我原有許多事要寫給你，卻不願意用筆墨寫給你，', 3, '正確內容記載於 約翰三書 1:13。', '約翰三書 1:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_1-1', '51-1', '撒迦利亞書', 'ZEC', '撒迦利亞書', '舊約', 'minor_prophets', 1, 14, '經文辨識', '根據《撒迦利亞書》的內容，以下哪一句經文出自這個範圍？', '雅各家的首領、 以色列家的官長啊， 當聽我的話！ 你們厭惡公平， 在一切事上屈枉正直；', '要尋求耶和華，就必存活， 免得他在 約瑟家像火發出， 在 伯特利焚燒，無人撲滅。', '剪蟲剩下的，蝗蟲來吃； 蝗蟲剩下的，蝻子來吃； 蝻子剩下的，螞蚱來吃。', '我說：「你往哪裏去？」他對我說：「要去量 耶路撒冷，看有多寬多長。」', 3, '正確內容記載於 撒迦利亞書 2:2。', '撒迦利亞書 2:2', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_1-2', '51-1', '撒迦利亞書', 'ZEC', '撒迦利亞書', '舊約', 'minor_prophets', 1, 14, '出處辨識', '「（我見有一片圓鉛被舉起來。）這坐在量器中的是個婦人。」的經文出處是哪裡？', '撒迦利亞書 5:7', '撒迦利亞書 11:14', '撒迦利亞書 2:5', '撒迦利亞書 1:14', 0, '正確內容記載於 撒迦利亞書 5:7。', '撒迦利亞書 5:7', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_1-3', '51-1', '撒迦利亞書', 'ZEC', '撒迦利亞書', '舊約', 'minor_prophets', 1, 14, '經文辨識', '根據《撒迦利亞書》的內容，以下哪一句經文出自這個範圍？', '群畜，就是各國的走獸必臥在其中； 鵜鶘和箭豬要宿在柱頂上。 在窗戶內有鳴叫的聲音； 門檻都必毀壞， 香柏木已經露出。', '那日以先，人得不着雇價，牲畜也是如此；且因敵人的緣故，出入之人不得平安，乃因我使眾人互相攻擊。', '他們在各壇旁鋪人所當的衣服，臥在其上， 又在他們神的廟中喝受罰之人的酒。', '然而耶和華使海中起大風，海就狂風大作，甚至船幾乎破壞。', 1, '正確內容記載於 撒迦利亞書 8:10。', '撒迦利亞書 8:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_1-4', '51-1', '撒迦利亞書', 'ZEC', '撒迦利亞書', '舊約', 'minor_prophets', 1, 14, '出處辨識', '「耶和華必經過苦海，擊打海浪， 使 尼羅河的深處都枯乾。 亞述的驕傲必致卑微； 埃及的權柄必然滅沒。」的經文出處是哪裡？', '撒迦利亞書 10:11', '撒迦利亞書 1:2', '撒迦利亞書 1:21', '撒迦利亞書 5:9', 0, '正確內容記載於 撒迦利亞書 10:11。', '撒迦利亞書 10:11', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_1-5', '51-1', '撒迦利亞書', 'ZEC', '撒迦利亞書', '舊約', 'minor_prophets', 1, 14, '經文辨識', '根據《撒迦利亞書》的內容，以下哪一句經文出自這個範圍？', '那時， 撒拉鐵的兒子 所羅巴伯和 約撒答的兒子大祭司 約書亞，並剩下的百姓，都聽從耶和華－他們上帝的話和先知 哈該奉耶和華－他們上帝差來所說的話；百姓…', '你們既然奪取我的金銀，又將我可愛的寶物帶入你們宮殿，', '城裏的富戶滿行強暴； 其中的居民也說謊言， 口中的舌頭是詭詐的。', '耶和華的日子臨近，你的財物必被搶掠，在你中間分散。', 3, '正確內容記載於 撒迦利亞書 14:1。', '撒迦利亞書 14:1', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_2-1', '51-2', '猶大書', 'JUD', '猶大書', '新約', 'general_epistles', 1, 1, '經文辨識', '根據《猶大書》的內容，以下哪一句經文出自這個範圍？', '親愛的 弟兄啊，我想盡心寫信給你們，論我們同得救恩的時候，就不得不寫信勸你們，要為從前一次交付聖徒的真道竭力地爭辯。', '若山羊和公牛的血，並母牛犢的灰，灑在不潔的人身上，尚且叫人成聖，身體潔淨，', '就是考察在他們心裏基督的靈，預先證明基督受苦難，後來得榮耀，是指着甚麼時候，並怎樣的時候。', '上帝的道是活潑的，是有功效的，比一切兩刃的劍更快，甚至魂與靈，骨節與骨髓，都能刺入、剖開，連心中的思念和主意都能辨明。', 0, '正確內容記載於 猶大書 1:3。', '猶大書 1:3', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_2-2', '51-2', '猶大書', 'JUD', '猶大書', '新約', 'general_epistles', 1, 1, '出處辨識', '「這些做夢的人也像他們污穢身體，輕慢主治的，毀謗在尊位的。」的經文出處是哪裡？', '猶大書 1:9', '猶大書 1:8', '猶大書 1:15', '猶大書 1:17', 1, '正確內容記載於 猶大書 1:8。', '猶大書 1:8', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_2-3', '51-2', '猶大書', 'JUD', '猶大書', '新約', 'general_epistles', 1, 1, '經文辨識', '根據《猶大書》的內容，以下哪一句經文出自這個範圍？', '是海裏的狂浪，湧出自己可恥的沫子來；是流蕩的星，有墨黑的幽暗為他們永遠存留。', '你喜愛公義，恨惡罪惡； 所以上帝，就是你的上帝，用喜樂油膏你， 勝過膏你的同伴；', '若長荊棘和蒺藜，必被廢棄，近於咒詛，結局就是焚燒。', '務要在主面前自卑，主就必叫你們升高。', 0, '正確內容記載於 猶大書 1:13。', '猶大書 1:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_2-4', '51-2', '猶大書', 'JUD', '猶大書', '新約', 'general_epistles', 1, 1, '出處辨識', '「他們曾對你們說過，末世必有好譏誚的人隨從自己不敬虔的私慾而行。」的經文出處是哪裡？', '猶大書 1:10', '猶大書 1:5', '猶大書 1:4', '猶大書 1:18', 3, '正確內容記載於 猶大書 1:18。', '猶大書 1:18', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_2-5', '51-2', '猶大書', 'JUD', '猶大書', '新約', 'general_epistles', 1, 1, '經文辨識', '根據《猶大書》的內容，以下哪一句經文出自這個範圍？', '有些人你們要從火中搶出來，搭救他們；有些人你們要存懼怕的心憐憫他們，連那被情慾沾染的衣服也當厭惡。', '因為主所愛的，他必管教， 又鞭打凡所收納的兒子。', '你叫他比天使微小一點， 賜他榮耀尊貴為冠冕， 並將你手所造的都派他管理，', '我們將這些話寫給你們，使你們的喜樂充足。', 0, '正確內容記載於 猶大書 1:23。', '猶大書 1:23', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_3-1', '51-3', '瑪拉基書', 'MAL', '瑪拉基書', '舊約', 'minor_prophets', 1, 4, '經文辨識', '根據《瑪拉基書》的內容，以下哪一句經文出自這個範圍？', '耶和華如此說： 迦薩三番四次地犯罪， 我必不免去她的刑罰； 因為她擄掠眾民交給 以東。', '「藐視我名的祭司啊，萬軍之耶和華對你們說：兒子尊敬父親，僕人敬畏主人；我既為父親，尊敬我的在哪裏呢？我既為主人，敬畏我的在哪裏呢？你們卻說：『我們在何…', '於是， 何西阿去娶了 滴拉音的女兒 歌篾。這婦人懷孕，給他生了一個兒子。', '以色列丟棄良善； 仇敵必追逼他。', 1, '正確內容記載於 瑪拉基書 1:6。', '瑪拉基書 1:6', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_3-2', '51-3', '瑪拉基書', 'MAL', '瑪拉基書', '舊約', 'minor_prophets', 1, 4, '出處辨識', '「我必斥責你們的種子，又把你們犧牲的糞抹在你們的臉上；你們要與糞一同除掉。」的經文出處是哪裡？', '瑪拉基書 2:3', '瑪拉基書 1:7', '瑪拉基書 3:11', '瑪拉基書 3:12', 0, '正確內容記載於 瑪拉基書 2:3。', '瑪拉基書 2:3', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_3-3', '51-3', '瑪拉基書', 'MAL', '瑪拉基書', '舊約', 'minor_prophets', 1, 4, '經文辨識', '根據《瑪拉基書》的內容，以下哪一句經文出自這個範圍？', '到那日，我必在 耶斯列平原折斷 以色列的弓。」', '獅子吼叫，誰不懼怕呢？ 主耶和華發命，誰能不說預言呢？', '雅各餘剩的人必在多國多民中， 如林間百獸中的獅子， 又如少壯獅子在羊群中。 他若經過就必踐踏撕裂， 無人搭救。', '你們還說：「這是為甚麼呢？」因耶和華在你和你幼年所娶的妻中間作見證。她雖是你的配偶，又是你盟約的妻，你卻以詭詐待她。', 3, '正確內容記載於 瑪拉基書 2:14。', '瑪拉基書 2:14', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_3-4', '51-3', '瑪拉基書', 'MAL', '瑪拉基書', '舊約', 'minor_prophets', 1, 4, '出處辨識', '「人豈可奪取上帝之物呢？你們竟奪取我 的供物。你們卻說：『我們在何事上奪取你 的供物呢？』就是你們在當納…」的經文出處是哪裡？', '瑪拉基書 3:8', '瑪拉基書 2:16', '瑪拉基書 1:3', '瑪拉基書 2:17', 0, '正確內容記載於 瑪拉基書 3:8。', '瑪拉基書 3:8', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-51_3-5', '51-3', '瑪拉基書', 'MAL', '瑪拉基書', '舊約', 'minor_prophets', 1, 4, '經文辨識', '根據《瑪拉基書》的內容，以下哪一句經文出自這個範圍？', '你們的女兒淫亂， 你們的新婦行淫， 我卻不懲罰她們； 因為你們自己離群與娼妓同居， 與妓女一同獻祭。 這無知的民必致傾倒。', '萬軍之耶和華說：「那日臨近，勢如燒着的火爐，凡狂傲的和行惡的必如碎稭，在那日必被燒盡，根本枝條一無存留。', '我在怒氣中將王賜你， 又在烈怒中將王廢去。', '以色列啊，不要像外邦人歡喜快樂； 因為你行邪淫離棄你的上帝， 在各穀場上 如妓女喜愛賞賜。', 1, '正確內容記載於 瑪拉基書 4:1。', '瑪拉基書 4:1', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-52_1-1', '52-1', '啟示錄(一)1~16 章', 'REV', '啟示錄', '新約', 'prophecy', 1, 16, '經文辨識', '根據《啟示錄(一)1~16 章》的內容，以下哪一句經文出自這個範圍？', '並肉桂、荳蔻、香料、香膏、乳香、酒、油、細麵、麥子、牛、羊、車、馬，和奴僕、人口。', '智慧的心在此 可以思想。那七頭就是女人所坐的七座山，', '「你要寫信給 士每拿教會的使者，說：『那首先的、末後的、死過又活的，說：', '那先前有如今沒有的獸，就是第八位；他也和那七位同列，並且歸於沉淪。', 2, '正確內容記載於 啟示錄 2:8。', '啟示錄 2:8', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-52_1-2', '52-1', '啟示錄(一)1~16 章', 'REV', '啟示錄', '新約', 'prophecy', 1, 16, '出處辨識', '「我又看見一位大力的天使大聲宣傳說：「有誰配展開那書卷，揭開那七印呢？」的經文出處是哪裡？', '啟示錄 3:11', '啟示錄 5:2', '啟示錄 1:1', '啟示錄 3:21', 1, '正確內容記載於 啟示錄 5:2。', '啟示錄 5:2', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-52_1-3', '52-1', '啟示錄(一)1~16 章', 'REV', '啟示錄', '新約', 'prophecy', 1, 16, '經文辨識', '根據《啟示錄(一)1~16 章》的內容，以下哪一句經文出自這個範圍？', '第三位天使吹號，就有燒着的大星，好像火把從天上落下來，落在江河的三分之一和眾水的泉源上。', '我又看見死了的人，無論大小，都站在寶座前。案卷展開了，並且另有一卷展開，就是生命冊。死了的人都憑着這些案卷所記載的，照他們所行的受審判。', '智慧的心在此 可以思想。那七頭就是女人所坐的七座山，', '坐寶座的說：「看哪，我將一切都更新了！」又說：「你要寫上；因這些話是可信的，是真實的。」', 0, '正確內容記載於 啟示錄 8:10。', '啟示錄 8:10', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-52_1-4', '52-1', '啟示錄(一)1~16 章', 'REV', '啟示錄', '新約', 'prophecy', 1, 16, '出處辨識', '「天上現出大異象來：有一個婦人身披日頭，腳踏月亮，頭戴十二星的冠冕。」的經文出處是哪裡？', '啟示錄 9:21', '啟示錄 1:7', '啟示錄 14:18', '啟示錄 12:1', 3, '正確內容記載於 啟示錄 12:1。', '啟示錄 12:1', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-52_1-5', '52-1', '啟示錄(一)1~16 章', 'REV', '啟示錄', '新約', 'prophecy', 1, 16, '經文辨識', '根據《啟示錄(一)1~16 章》的內容，以下哪一句經文出自這個範圍？', '我看見彷彿有玻璃海，其中有火攙雜。又看見那些勝了獸和獸的像並牠名字數目的人，都站在玻璃海上，拿着上帝的琴，', '他們同心合意將自己的能力、權柄給那獸。', '又量了城牆，按着人的尺寸，就是天使的尺寸，共有一百四十四肘。', '我看見那獸和地上的君王，並他們的眾軍都聚集，要與騎 白馬的並他的軍兵爭戰。', 0, '正確內容記載於 啟示錄 15:2。', '啟示錄 15:2', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-52_2-1', '52-2', '啟示錄(二)17~22 章', 'REV', '啟示錄', '新約', 'prophecy', 17, 22, '經文辨識', '根據《啟示錄(二)17~22 章》的內容，以下哪一句經文出自這個範圍？', '這羔羊前來，從坐寶座的右手裏拿了書卷。', '他們同心合意將自己的能力、權柄給那獸。', '他手裏拿着小書卷，是展開的。他右腳踏海，左腳踏地，', '寶座的周圍又有二十四個座位；其上坐着二十四位長老，身穿白衣，頭上戴着金冠冕。', 1, '正確內容記載於 啟示錄 17:13。', '啟示錄 17:13', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-52_2-2', '52-2', '啟示錄(二)17~22 章', 'REV', '啟示錄', '新約', 'prophecy', 17, 22, '出處辨識', '「天哪，眾聖徒、眾使徒、眾先知啊， 你們都要因她歡喜， 因為上帝已經在她身上伸了你們的冤。」的經文出處是哪裡？', '啟示錄 18:20', '啟示錄 18:18', '啟示錄 19:12', '啟示錄 19:10', 0, '正確內容記載於 啟示錄 18:20。', '啟示錄 18:20', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-52_2-3', '52-2', '啟示錄(二)17~22 章', 'REV', '啟示錄', '新約', 'prophecy', 17, 22, '經文辨識', '根據《啟示錄(二)17~22 章》的內容，以下哪一句經文出自這個範圍？', '有一根葦子賜給我，當作量度的杖；且有話說：「起來！將上帝的殿和祭壇，並在殿中禮拜的人都量一量。', '凡得勝的必這樣穿白衣，我也必不從生命冊上塗抹他的名；且要在我父面前，和我父眾使者面前，認他的名。', '第二樣災禍過去，第三樣災禍快到了。', '我又看見一位天使從天降下，手裏拿着無底坑的鑰匙和一條大鍊子。', 3, '正確內容記載於 啟示錄 20:1。', '啟示錄 20:1', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-52_2-4', '52-2', '啟示錄(二)17~22 章', 'REV', '啟示錄', '新約', 'prophecy', 17, 22, '出處辨識', '「城中有上帝的榮耀；城的光輝如同極貴的寶石，好像碧玉，明如水晶。」的經文出處是哪裡？', '啟示錄 19:21', '啟示錄 19:8', '啟示錄 21:11', '啟示錄 22:3', 2, '正確內容記載於 啟示錄 21:11。', '啟示錄 21:11', 'easy', 'active') ON CONFLICT(id) DO NOTHING;
INSERT INTO quiz_questions (id, topic_code, topic_title, book_codes, book_name, testament, section, chapter_start, chapter_end, question_type, question, option_a, option_b, option_c, option_d, correct_index, explanation, reference, difficulty, status) VALUES ('seed-52_2-5', '52-2', '啟示錄(二)17~22 章', 'REV', '啟示錄', '新約', 'prophecy', 17, 22, '經文辨識', '根據《啟示錄(二)17~22 章》的內容，以下哪一句經文出自這個範圍？', '你要警醒，堅固那剩下將要衰微的；因我見你的行為，在我上帝面前，沒有一樣是完全的。', '他對我說：「千萬不可！我與你和你的弟兄眾先知，並那些守這書上言語的人，同是作僕人的。你要敬拜上帝。」', '我就觀看，見有一匹白馬；騎在馬上的，拿着弓，並有冠冕賜給他。他便出來，勝了又要勝。', '耶穌基督的啟示，就是上帝賜給他，叫他將必要快成的事指示他的眾僕人。他就差遣使者曉諭他的僕人 約翰。', 1, '正確內容記載於 啟示錄 22:9。', '啟示錄 22:9', 'medium', 'active') ON CONFLICT(id) DO NOTHING;
